def normalize_base_weight_source(
    value: Any,
    *,
    default: str = BASE_WEIGHT_SOURCE_UNKNOWN,
) -> str:
    """
    Normalize a base-weight source.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in BASE_WEIGHT_SOURCES:
        return normalized

    return _BASE_WEIGHT_SOURCE_ALIASES.get(
        normalized,
        default,
    )


def normalize_base_weight_status(
    value: Any,
    *,
    default: str = BASE_WEIGHT_STATUS_UNKNOWN,
) -> str:
    """
    Normalize a base-weight resolution status.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in BASE_WEIGHT_STATUSES:
        return normalized

    return _BASE_WEIGHT_STATUS_ALIASES.get(
        normalized,
        default,
    )


def normalize_base_weight_policy(
    value: Any,
    *,
    default: str = DEFAULT_BASE_WEIGHT_POLICY,
) -> str:
    """
    Normalize a base-weight lookup policy.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in BASE_WEIGHT_POLICIES:
        return normalized

    return _BASE_WEIGHT_POLICY_ALIASES.get(
        normalized,
        default,
    )


# -----------------------------------------------------------------------------
# 8.3. Base-weight exceptions
# -----------------------------------------------------------------------------

class BaseWeightError(ScoringError):
    """
    Base exception for interaction base-weight failures.
    """


class UnknownInteractionWeightError(BaseWeightError):
    """
    Raised when no weight can be resolved for an interaction type.
    """


class InvalidInteractionWeightError(BaseWeightError):
    """
    Raised when a configured interaction weight is invalid.
    """


class ConflictingInteractionWeightError(BaseWeightError):
    """
    Raised when equivalent canonical keys define conflicting weights.
    """


# -----------------------------------------------------------------------------
# 8.4. Weight-mapping normalization
# -----------------------------------------------------------------------------

def normalize_interaction_weight_mapping(
    weights: Optional[Mapping[Any, Number]],
    *,
    allow_unknown: bool = True,
) -> Mapping[str, float]:
    """
    Normalize a mapping of interaction types to finite numeric weights.

    Aliases such as ``hbond``, ``pi_stack`` and ``pi_cation`` are converted to
    their canonical interaction types. Conflicting aliases are rejected.
    """

    if weights is None:
        return MappingProxyType({})

    if not isinstance(weights, Mapping):
        raise InvalidInteractionWeightError(
            "Interaction weights must be provided as a mapping."
        )

    normalized_weights: Dict[str, float] = {}

    for raw_type, raw_weight in weights.items():
        canonical_type = normalize_interaction_type(
            raw_type,
            preserve_unknown=True,
        )

        if (
            canonical_type == SCORE_TYPE_UNKNOWN
            and not allow_unknown
        ):
            raise InvalidInteractionWeightError(
                f"Unknown interaction type {raw_type!r} is not allowed."
            )

        try:
            weight = float(
                _coerce_finite_score_value(
                    raw_weight,
                    name=(
                        "interaction weight for "
                        f"{canonical_type!r}"
                    ),
                )
            )
        except ScoringError as exc:
            raise InvalidInteractionWeightError(
                f"Invalid weight for interaction type "
                f"{canonical_type!r}."
            ) from exc

        previous_weight = normalized_weights.get(
            canonical_type
        )

        if (
            previous_weight is not None
            and abs(previous_weight - weight)
            > SCORE_COMPARISON_TOLERANCE
        ):
            raise ConflictingInteractionWeightError(
                f"Canonical interaction type {canonical_type!r} "
                "received conflicting weights through different aliases."
            )

        normalized_weights[canonical_type] = weight

    return MappingProxyType(normalized_weights)


def normalize_family_weight_mapping(
    weights: Optional[Mapping[Any, Number]],
) -> Mapping[str, float]:
    """
    Normalize a mapping of interaction families to finite weights.
    """

    if weights is None:
        return MappingProxyType({})

    if not isinstance(weights, Mapping):
        raise InvalidInteractionWeightError(
            "Interaction-family weights must be provided as a mapping."
        )

    normalized_weights: Dict[str, float] = {}

    for raw_family, raw_weight in weights.items():
        canonical_family = canonical_interaction_family(
            raw_family
        )

        try:
            weight = float(
                _coerce_finite_score_value(
                    raw_weight,
                    name=(
                        "interaction-family weight for "
                        f"{canonical_family!r}"
                    ),
                )
            )
        except ScoringError as exc:
            raise InvalidInteractionWeightError(
                f"Invalid weight for interaction family "
                f"{canonical_family!r}."
            ) from exc

        previous_weight = normalized_weights.get(
            canonical_family
        )

        if (
            previous_weight is not None
            and abs(previous_weight - weight)
            > SCORE_COMPARISON_TOLERANCE
        ):
            raise ConflictingInteractionWeightError(
                f"Canonical interaction family {canonical_family!r} "
                "received conflicting weights."
            )

        normalized_weights[canonical_family] = weight

    return MappingProxyType(normalized_weights)


# -----------------------------------------------------------------------------
# 8.5. BaseWeightProfile
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class BaseWeightProfile:
    """
    Immutable set of base weights used by the scoring engine.

    Parameters
    ----------
    interaction_weights
        Canonical interaction-type weights.
    family_weights
        Optional family-level fallback weights.
    unknown_weight
        Weight used when no canonical type or family weight is found.
    policy
        Type-only, type-then-family or family-only lookup policy.
    strict
        Raise instead of returning the unknown fallback.
    allow_zero_weight
        Permit neutral interactions with a zero base weight.
    """

    interaction_weights: Mapping[str, float] = field(
        default_factory=lambda: DEFAULT_INTERACTION_WEIGHTS
    )
    family_weights: Mapping[str, float] = field(
        default_factory=lambda: DEFAULT_INTERACTION_FAMILY_WEIGHTS
    )

    unknown_weight: float = DEFAULT_UNKNOWN_INTERACTION_WEIGHT
    policy: str = DEFAULT_BASE_WEIGHT_POLICY

    strict: bool = False
    allow_zero_weight: bool = True

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize and validate the profile.
        """

        interaction_weights = normalize_interaction_weight_mapping(
            self.interaction_weights
        )
        family_weights = normalize_family_weight_mapping(
            self.family_weights
        )

        unknown_weight = float(
            _coerce_finite_score_value(
                self.unknown_weight,
                name="BaseWeightProfile.unknown_weight",
            )
        )

        policy = normalize_base_weight_policy(
            self.policy
        )

        if not self.allow_zero_weight:
            zero_types = tuple(
                interaction_type
                for interaction_type, weight
                in interaction_weights.items()
                if abs(weight) <= SCORE_COMPARISON_TOLERANCE
            )

            if zero_types:
                raise InvalidInteractionWeightError(
                    "Zero interaction weights are disabled, but the "
                    f"following types have zero weight: {zero_types!r}."
                )

            zero_families = tuple(
                interaction_family
                for interaction_family, weight
                in family_weights.items()
                if abs(weight) <= SCORE_COMPARISON_TOLERANCE
            )

            if zero_families:
                raise InvalidInteractionWeightError(
                    "Zero family weights are disabled, but the "
                    f"following families have zero weight: "
                    f"{zero_families!r}."
                )

        object.__setattr__(
            self,
            "interaction_weights",
            interaction_weights,
        )
        object.__setattr__(
            self,
            "family_weights",
            family_weights,
        )
        object.__setattr__(
            self,
            "unknown_weight",
            unknown_weight,
        )
        object.__setattr__(
            self,
            "policy",
            policy,
        )
        object.__setattr__(
            self,
            "strict",
            bool(self.strict),
        )
        object.__setattr__(
            self,
            "allow_zero_weight",
            bool(self.allow_zero_weight),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def weight_for_type(
        self,
        interaction_type: Any,
        *,
        interaction_family: Optional[Any] = None,
        overrides: Optional[Mapping[Any, Number]] = None,
        strict: Optional[bool] = None,
    ) -> float:
        """
        Resolve and return a base weight.
        """

        return resolve_base_weight(
            interaction_type,
            interaction_family=interaction_family,
            profile=self,
            overrides=overrides,
            strict=strict,
        ).weight

    def with_updates(
        self,
        **changes: Any,
    ) -> "BaseWeightProfile":
        """
        Return a validated profile copy.
        """

        return replace(
            self,
            **changes,
        )

    def with_interaction_weight(
        self,
        interaction_type: Any,
        weight: Number,
    ) -> "BaseWeightProfile":
        """
        Return a copy with one interaction-type weight replaced.
        """

        canonical_type = normalize_interaction_type(
            interaction_type,
            preserve_unknown=True,
        )

        normalized_weight = float(
            _coerce_finite_score_value(
                weight,
                name=(
                    "interaction weight for "
                    f"{canonical_type!r}"
                ),
            )
        )

        updated_weights = dict(
            self.interaction_weights
        )
        updated_weights[canonical_type] = (
            normalized_weight
        )

        return replace(
            self,
            interaction_weights=updated_weights,
        )

    def without_interaction_weight(
        self,
        interaction_type: Any,
    ) -> "BaseWeightProfile":
        """
        Return a copy without a type-specific weight.
        """

        canonical_type = normalize_interaction_type(
            interaction_type,
            preserve_unknown=True,
        )

        updated_weights = dict(
            self.interaction_weights
        )
        updated_weights.pop(
            canonical_type,
            None,
        )

        return replace(
            self,
            interaction_weights=updated_weights,
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "interaction_weights": dict(
                self.interaction_weights
            ),
            "family_weights": dict(
                self.family_weights
            ),
            "unknown_weight": float(
                self.unknown_weight
            ),
            "policy": self.policy,
            "strict": bool(self.strict),
            "allow_zero_weight": bool(
                self.allow_zero_weight
            ),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result

    def __hash__(self) -> int:
        """
        Return a stable hash excluding arbitrary metadata.
        """

        return hash(
            (
                tuple(
                    sorted(
                        self.interaction_weights.items()
                    )
                ),
                tuple(
                    sorted(
                        self.family_weights.items()
                    )
                ),
                self.unknown_weight,
                self.policy,
                self.strict,
                self.allow_zero_weight,
            )
        )


DEFAULT_BASE_WEIGHT_PROFILE: Final[
    BaseWeightProfile
] = BaseWeightProfile()


# -----------------------------------------------------------------------------
# 8.6. BaseWeightResolution
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class BaseWeightResolution:
    """
    Immutable result of resolving an interaction base weight.
    """

    interaction_type: str
    interaction_family: str
    weight: float

    source: str = BASE_WEIGHT_SOURCE_UNKNOWN
    status: str = BASE_WEIGHT_STATUS_UNKNOWN
    matched_key: str = ""

    used_fallback: bool = False
    reason: str = ""

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize base-weight resolution data.
        """

        interaction_type = normalize_interaction_type(
            self.interaction_type,
            preserve_unknown=True,
        )

        interaction_family = canonical_interaction_family(
            self.interaction_family
            or interaction_type
        )

        weight = float(
            _coerce_finite_score_value(
                self.weight,
                name="BaseWeightResolution.weight",
            )
        )

        object.__setattr__(
            self,
            "interaction_type",
            interaction_type,
        )
        object.__setattr__(
            self,
            "interaction_family",
            interaction_family,
        )
        object.__setattr__(
            self,
            "weight",
            weight,
        )
        object.__setattr__(
            self,
            "source",
            normalize_base_weight_source(
                self.source
            ),
        )
        object.__setattr__(
            self,
            "status",
            normalize_base_weight_status(
                self.status
            ),
        )
        object.__setattr__(
            self,
            "matched_key",
            _coerce_identifier(
                self.matched_key
            ),
        )
        object.__setattr__(
            self,
            "used_fallback",
            bool(self.used_fallback),
        )
        object.__setattr__(
            self,
            "reason",
            _coerce_optional_text(
                self.reason
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def resolved(self) -> bool:
        """
        Return whether a configured type or family weight was found.
        """

        return self.status == BASE_WEIGHT_STATUS_RESOLVED

    @property
    def favorable(self) -> bool:
        """Return whether the base contribution is favorable."""

        return self.weight > 0.0

    @property
    def unfavorable(self) -> bool:
        """Return whether the base contribution is unfavorable."""

        return self.weight < 0.0

    @property
    def neutral(self) -> bool:
        """Return whether the base contribution is neutral."""

        return abs(
            self.weight
        ) <= SCORE_COMPARISON_TOLERANCE

    def to_component(
        self,
    ) -> ScoreComponent:
        """
        Convert the resolution to a base-weight ScoreComponent.
        """

        return make_base_weight_component(
            value=self.weight,
            interaction_type=self.interaction_type,
            source=self.source,
            description=self.reason,
            metadata={
                "interaction_family": (
                    self.interaction_family
                ),
                "matched_key": self.matched_key,
                "status": self.status,
                "used_fallback": (
                    self.used_fallback
                ),
            },
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "interaction_type": self.interaction_type,
            "interaction_family": (
                self.interaction_family
            ),
            "weight": float(self.weight),
            "source": self.source,
            "status": self.status,
            "matched_key": self.matched_key,
            "used_fallback": bool(
                self.used_fallback
            ),
            "reason": self.reason,
            "resolved": bool(self.resolved),
            "favorable": bool(self.favorable),
            "unfavorable": bool(self.unfavorable),
            "neutral": bool(self.neutral),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result

    def __float__(self) -> float:
        """Return the resolved weight."""

        return float(self.weight)

    def __hash__(self) -> int:
        """
        Return a stable hash excluding arbitrary metadata.
        """

        return hash(
            (
                self.interaction_type,
                self.interaction_family,
                self.weight,
                self.source,
                self.status,
                self.matched_key,
                self.used_fallback,
                self.reason,
            )
        )


# -----------------------------------------------------------------------------
# 8.7. ScoringConfig integration
# -----------------------------------------------------------------------------

def extract_config_interaction_weights(
    scoring_config: Optional[ScoringConfig],
) -> Mapping[str, float]:
    """
    Extract canonical interaction weights from ScoringConfig.

    The helper accepts common field names to preserve compatibility with
    previous DockAnalyzer configuration layouts.
    """

    if scoring_config is None:
        return MappingProxyType({})

    if not isinstance(scoring_config, ScoringConfig):
        raise InvalidInteractionWeightError(
            "scoring_config must be a ScoringConfig instance or None."
        )

    extracted = extract_named_value(
        scoring_config,
        (
            "interaction_weights",
            "weights",
            "base_weights",
            "score_weights",
        ),
        allow_none=False,
        call_methods=False,
    )

    if not extracted.found:
        return MappingProxyType({})

    return normalize_interaction_weight_mapping(
        extracted.value
    )


def extract_config_family_weights(
    scoring_config: Optional[ScoringConfig],
) -> Mapping[str, float]:
    """
    Extract optional family-level weights from ScoringConfig.
    """

    if scoring_config is None:
        return MappingProxyType({})

    if not isinstance(scoring_config, ScoringConfig):
        raise InvalidInteractionWeightError(
            "scoring_config must be a ScoringConfig instance or None."
        )

    extracted = extract_named_value(
        scoring_config,
        (
            "interaction_family_weights",
            "family_weights",
        ),
        allow_none=False,
        call_methods=False,
    )

    if not extracted.found:
        return MappingProxyType({})

    return normalize_family_weight_mapping(
        extracted.value
    )


def base_weight_profile_from_config(
    scoring_config: ScoringConfig,
    *,
    policy: str = DEFAULT_BASE_WEIGHT_POLICY,
    unknown_weight: Number = DEFAULT_UNKNOWN_INTERACTION_WEIGHT,
    strict: bool = False,
    include_default_family_weights: bool = True,
) -> BaseWeightProfile:
    """
    Construct a BaseWeightProfile from ScoringConfig.
    """

    interaction_weights = extract_config_interaction_weights(
        scoring_config
    )

    family_weights = extract_config_family_weights(
        scoring_config
    )

    if (
        not family_weights
        and include_default_family_weights
    ):
        family_weights = (
            DEFAULT_INTERACTION_FAMILY_WEIGHTS
        )

    return BaseWeightProfile(
        interaction_weights=interaction_weights,
        family_weights=family_weights,
        unknown_weight=float(
            _coerce_finite_score_value(
                unknown_weight,
                name="unknown_weight",
            )
        ),
        policy=policy,
        strict=strict,
        metadata={
            "source": object_type_name(
                scoring_config
            ),
        },
    )


# -----------------------------------------------------------------------------
# 8.8. Base-weight resolution
# -----------------------------------------------------------------------------

def resolve_base_weight(
    interaction_type: Any,
    *,
    interaction_family: Optional[Any] = None,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
    strict: Optional[bool] = None,
) -> BaseWeightResolution:
    """
    Resolve the base weight for a canonical interaction type.

    Resolution precedence
    ---------------------
    1. Explicit call-level overrides.
    2. Weights extracted from ``ScoringConfig``.
    3. Weights stored in ``BaseWeightProfile``.
    4. Family-level fallback, when enabled.
    5. The profile unknown weight.

    Strength, geometry, classification, bonuses and penalties are not applied
    by this function.
    """

    if not isinstance(profile, BaseWeightProfile):
        raise InvalidInteractionWeightError(
            "profile must be a BaseWeightProfile instance."
        )

    canonical_type = normalize_interaction_type(
        interaction_type,
        preserve_unknown=True,
    )

    canonical_family = canonical_interaction_family(
        (
            interaction_family
            if interaction_family is not None
            else canonical_type
        )
    )

    strict_mode = (
        profile.strict
        if strict is None
        else bool(strict)
    )

    normalized_overrides = (
        normalize_interaction_weight_mapping(
            overrides
        )
        if overrides is not None
        else MappingProxyType({})
    )

    if canonical_type in normalized_overrides:
        weight = normalized_overrides[
            canonical_type
        ]

        return BaseWeightResolution(
            interaction_type=canonical_type,
            interaction_family=canonical_family,
            weight=weight,
            source=BASE_WEIGHT_SOURCE_OVERRIDE,
            status=BASE_WEIGHT_STATUS_RESOLVED,
            matched_key=canonical_type,
            used_fallback=False,
            reason=(
                "The base weight was resolved from an explicit "
                "call-level override."
            ),
        )

    config_type_weights = (
        extract_config_interaction_weights(
            scoring_config
        )
    )

    if canonical_type in config_type_weights:
        weight = config_type_weights[
            canonical_type
        ]

        return BaseWeightResolution(
            interaction_type=canonical_type,
            interaction_family=canonical_family,
            weight=weight,
            source=BASE_WEIGHT_SOURCE_CONFIG,
            status=BASE_WEIGHT_STATUS_RESOLVED,
            matched_key=canonical_type,
            used_fallback=False,
            reason=(
                "The base weight was resolved from ScoringConfig."
            ),
        )

    config_family_weights = (
        extract_config_family_weights(
            scoring_config
        )
    )

    policy = profile.policy

    if policy != BASE_WEIGHT_POLICY_FAMILY_ONLY:
        if canonical_type in profile.interaction_weights:
            weight = profile.interaction_weights[
                canonical_type
            ]

            return BaseWeightResolution(
                interaction_type=canonical_type,
                interaction_family=canonical_family,
                weight=weight,
                source=BASE_WEIGHT_SOURCE_DEFAULT,
                status=BASE_WEIGHT_STATUS_RESOLVED,
                matched_key=canonical_type,
                used_fallback=False,
                reason=(
                    "The base weight was resolved from the "
                    "interaction-type weight profile."
                ),
            )

    if policy in {
        BASE_WEIGHT_POLICY_TYPE_THEN_FAMILY,
        BASE_WEIGHT_POLICY_FAMILY_ONLY,
    }:
        if canonical_family in config_family_weights:
            weight = config_family_weights[
                canonical_family
            ]

            return BaseWeightResolution(
                interaction_type=canonical_type,
                interaction_family=canonical_family,
                weight=weight,
                source=BASE_WEIGHT_SOURCE_CONFIG,
                status=BASE_WEIGHT_STATUS_RESOLVED,
                matched_key=canonical_family,
                used_fallback=True,
                reason=(
                    "No type-specific weight was available; the "
                    "weight was resolved from a ScoringConfig family "
                    "weight."
                ),
            )

        if canonical_family in profile.family_weights:
            weight = profile.family_weights[
                canonical_family
            ]

            return BaseWeightResolution(
                interaction_type=canonical_type,
                interaction_family=canonical_family,
                weight=weight,
                source=BASE_WEIGHT_SOURCE_FAMILY,
                status=BASE_WEIGHT_STATUS_FALLBACK,
                matched_key=canonical_family,
                used_fallback=True,
                reason=(
                    "No type-specific weight was available; a "
                    "family-level fallback was used."
                ),
            )

    if strict_mode:
        raise UnknownInteractionWeightError(
            f"No base weight is defined for interaction type "
            f"{canonical_type!r} in family "
            f"{canonical_family!r}."
        )

    return BaseWeightResolution(
        interaction_type=canonical_type,
        interaction_family=canonical_family,
        weight=profile.unknown_weight,
        source=BASE_WEIGHT_SOURCE_FALLBACK,
        status=BASE_WEIGHT_STATUS_UNKNOWN,
        matched_key=SCORE_TYPE_UNKNOWN,
        used_fallback=True,
        reason=(
            "No type-specific or family-level weight was available; "
            "the unknown-interaction fallback weight was used."
        ),
    )


def resolve_interaction_base_weight(
    interaction: Any,
    *,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
    strict: Optional[bool] = None,
) -> BaseWeightResolution:
    """
    Resolve the base weight directly from an interaction-like object.
    """

    if isinstance(interaction, InteractionScore):
        return BaseWeightResolution(
            interaction_type=interaction.interaction_type,
            interaction_family=interaction.interaction_family,
            weight=interaction.base_weight,
            source=BASE_WEIGHT_SOURCE_DEFAULT,
            status=BASE_WEIGHT_STATUS_RESOLVED,
            matched_key=interaction.interaction_type,
            used_fallback=False,
            reason=(
                "The source InteractionScore already stores a "
                "base weight."
            ),
            metadata={
                "existing_score": True,
            },
        )

    if isinstance(
        interaction,
        ExtractedInteractionData,
    ):
        interaction_type = interaction.interaction_type
        interaction_family = (
            interaction.interaction_family
        )

    elif isinstance(
        interaction,
        InteractionRecognitionResult,
    ):
        interaction_type = interaction.interaction_type
        interaction_family = (
            interaction.interaction_family
        )

    else:
        interaction_type = extract_interaction_type(
            interaction
        )
        interaction_family = extract_interaction_family(
            interaction,
            interaction_type=interaction_type,
        )

    return resolve_base_weight(
        interaction_type,
        interaction_family=interaction_family,
        profile=profile,
        scoring_config=scoring_config,
        overrides=overrides,
        strict=strict,
    )


def resolve_base_weights(
    source: Any,
    *,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
    strict: Optional[bool] = None,
    skip_errors: bool = False,
) -> Tuple[BaseWeightResolution, ...]:
    """
    Resolve base weights for a heterogeneous interaction collection.
    """

    resolutions: List[BaseWeightResolution] = []

    for interaction in iter_interaction_objects(
        source
    ):
        try:
            resolution = resolve_interaction_base_weight(
                interaction,
                profile=profile,
                scoring_config=scoring_config,
                overrides=overrides,
                strict=strict,
            )
        except (
            ScoringError,
            TypeError,
            ValueError,
            AttributeError,
        ):
            if skip_errors:
                continue

            raise

        resolutions.append(resolution)

    return tuple(resolutions)


# -----------------------------------------------------------------------------
# 8.9. Weight lookup helpers
# -----------------------------------------------------------------------------

def base_weight_for_type(
    interaction_type: Any,
    *,
    interaction_family: Optional[Any] = None,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
    strict: Optional[bool] = None,
) -> float:
    """
    Return only the resolved numeric base weight.
    """

    return resolve_base_weight(
        interaction_type,
        interaction_family=interaction_family,
        profile=profile,
        scoring_config=scoring_config,
        overrides=overrides,
        strict=strict,
    ).weight


def has_type_specific_base_weight(
    interaction_type: Any,
    *,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
) -> bool:
    """
    Return whether a type-specific weight exists without family fallback.
    """

    canonical_type = normalize_interaction_type(
        interaction_type,
        preserve_unknown=True,
    )

    normalized_overrides = (
        normalize_interaction_weight_mapping(
            overrides
        )
        if overrides is not None
        else MappingProxyType({})
    )

    if canonical_type in normalized_overrides:
        return True

    config_weights = extract_config_interaction_weights(
        scoring_config
    )

    if canonical_type in config_weights:
        return True

    return canonical_type in profile.interaction_weights


def base_weight_source_for_type(
    interaction_type: Any,
    *,
    interaction_family: Optional[Any] = None,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
) -> str:
    """
    Return the source used to resolve an interaction weight.
    """

    return resolve_base_weight(
        interaction_type,
        interaction_family=interaction_family,
        profile=profile,
        scoring_config=scoring_config,
        overrides=overrides,
        strict=False,
    ).source


# -----------------------------------------------------------------------------
# 8.10. Weight polarity and ordering
# -----------------------------------------------------------------------------

def classify_base_weight(
    weight: Number,
) -> str:
    """
    Classify a base weight as favorable, unfavorable or neutral.
    """

    normalized_weight = _coerce_finite_score_value(
        weight,
        name="base weight",
    )

    if normalized_weight > SCORE_COMPARISON_TOLERANCE:
        return POLARITY_FAVORABLE

    if normalized_weight < -SCORE_COMPARISON_TOLERANCE:
        return POLARITY_UNFAVORABLE

    return POLARITY_NEUTRAL


def interaction_type_base_weight_polarity(
    interaction_type: Any,
    *,
    interaction_family: Optional[Any] = None,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
) -> str:
    """
    Return the polarity of an interaction type's base weight.
    """

    weight = base_weight_for_type(
        interaction_type,
        interaction_family=interaction_family,
        profile=profile,
        scoring_config=scoring_config,
        overrides=overrides,
        strict=False,
    )

    return classify_base_weight(weight)


def sort_interaction_types_by_base_weight(
    interaction_types: Iterable[Any],
    *,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
    descending: bool = True,
) -> Tuple[str, ...]:
    """
    Sort canonical interaction types by resolved base weight.
    """

    canonical_types = tuple(
        dict.fromkeys(
            normalize_interaction_type(
                interaction_type,
                preserve_unknown=True,
            )
            for interaction_type in interaction_types
        )
    )

    return tuple(
        sorted(
            canonical_types,
            key=lambda interaction_type: (
                base_weight_for_type(
                    interaction_type,
                    profile=profile,
                    scoring_config=scoring_config,
                    overrides=overrides,
                    strict=False,
                ),
                interaction_type,
            ),
            reverse=descending,
        )
    )


# -----------------------------------------------------------------------------
# 8.11. Applying the base weight to extracted interactions
# -----------------------------------------------------------------------------

def interaction_score_with_base_weight(
    data: ExtractedInteractionData,
    *,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
    strict: Optional[bool] = None,
    preserve_components: bool = True,
) -> InteractionScore:
    """
    Create an InteractionScore containing only the resolved base weight.

    All multipliers remain neutral at ``1.0`` and all penalties and bonuses
    remain zero. Later sections will apply those scoring terms.
    """

    validate_extracted_interaction_data(data)

    resolution = resolve_base_weight(
        data.interaction_type,
        interaction_family=data.interaction_family,
        profile=profile,
        scoring_config=scoring_config,
        overrides=overrides,
        strict=strict,
    )

    metadata = dict(data.metadata)
    metadata["base_weight_resolution"] = (
        resolution.to_dict(
            include_metadata=True,
        )
    )

    weighted_data = replace(
        data,
        polarity=classify_base_weight(
            resolution.weight
        ),
        metadata=metadata,
    )

    return interaction_score_from_extracted_data(
        weighted_data,
        base_weight=resolution.weight,
        strength_multiplier=(
            DEFAULT_NEUTRAL_MULTIPLIER
        ),
        classification_multiplier=(
            DEFAULT_NEUTRAL_MULTIPLIER
        ),
        geometry_multiplier=(
            DEFAULT_NEUTRAL_MULTIPLIER
        ),
        penalty_score=0.0,
        bonus_score=0.0,
        preserve_components=preserve_components,
    )


def interactions_with_base_weights(
    interactions: Iterable[ExtractedInteractionData],
    *,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
    strict: Optional[bool] = None,
    preserve_components: bool = True,
    skip_errors: bool = False,
) -> Tuple[InteractionScore, ...]:
    """
    Convert extracted interactions to base-weighted scores.
    """

    scores: List[InteractionScore] = []

    for interaction in interactions:
        try:
            score = interaction_score_with_base_weight(
                interaction,
                profile=profile,
                scoring_config=scoring_config,
                overrides=overrides,
                strict=strict,
                preserve_components=preserve_components,
            )
        except (
            ScoringError,
            TypeError,
            ValueError,
            AttributeError,
        ):
            if skip_errors:
                continue

            raise

        scores.append(score)

    return sort_interaction_scores(scores)


def extract_recognize_and_apply_base_weights(
    source: Any,
    *,
    container_name: Optional[str] = None,
    pose_id: Optional[str] = None,
    model_id: Optional[str] = None,
    ligand_id: Optional[str] = None,
    recognition_config: InteractionRecognitionConfig = (
        DEFAULT_INTERACTION_RECOGNITION_CONFIG
    ),
    recognition_rules: Iterable[
        InteractionRecognitionRule
    ] = (),
    weight_profile: BaseWeightProfile = (
        DEFAULT_BASE_WEIGHT_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    weight_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strict_weights: Optional[bool] = None,
    preserve_references: bool = True,
    skip_errors: bool = False,
) -> Tuple[InteractionScore, ...]:
    """
    Execute extraction, recognition and base-weight assignment.
    """

    extracted = extract_and_recognize_interactions(
        source,
        container_name=container_name,
        pose_id=pose_id,
        model_id=model_id,
        ligand_id=ligand_id,
        config=recognition_config,
        custom_rules=recognition_rules,
        preserve_references=preserve_references,
        skip_errors=skip_errors,
    )

    return interactions_with_base_weights(
        extracted,
        profile=weight_profile,
        scoring_config=scoring_config,
        overrides=weight_overrides,
        strict=strict_weights,
        preserve_components=True,
        skip_errors=skip_errors,
    )


# -----------------------------------------------------------------------------
# 8.12. Base-weight summaries
# -----------------------------------------------------------------------------

def base_weights_by_interaction_type(
    interaction_types: Optional[Iterable[Any]] = None,
    *,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
) -> Mapping[str, float]:
    """
    Return resolved base weights by canonical interaction type.
    """

    if interaction_types is None:
        interaction_types = tuple(
            sorted(
                set(profile.interaction_weights)
                | set(
                    extract_config_interaction_weights(
                        scoring_config
                    )
                )
                | set(
                    normalize_interaction_weight_mapping(
                        overrides
                    )
                    if overrides is not None
                    else ()
                )
            )
        )

    result: Dict[str, float] = {}

    for interaction_type in interaction_types:
        canonical_type = normalize_interaction_type(
            interaction_type,
            preserve_unknown=True,
        )

        result[canonical_type] = (
            base_weight_for_type(
                canonical_type,
                profile=profile,
                scoring_config=scoring_config,
                overrides=overrides,
                strict=False,
            )
        )

    return MappingProxyType(result)


def group_interaction_types_by_base_weight(
    interaction_types: Optional[Iterable[Any]] = None,
    *,
    profile: BaseWeightProfile = DEFAULT_BASE_WEIGHT_PROFILE,
    scoring_config: Optional[ScoringConfig] = None,
    overrides: Optional[Mapping[Any, Number]] = None,
) -> Mapping[float, Tuple[str, ...]]:
    """
    Group interaction types by their resolved numeric base weight.
    """

    weights = base_weights_by_interaction_type(
        interaction_types,
        profile=profile,
        scoring_config=scoring_config,
        overrides=overrides,
    )

    grouped: Dict[float, List[str]] = {}

    for interaction_type, weight in weights.items():
        grouped.setdefault(
            float(weight),
            [],
        ).append(interaction_type)

    return MappingProxyType(
        {
            weight: tuple(
                sorted(types)
            )
            for weight, types in sorted(
                grouped.items(),
                key=lambda item: item[0],
                reverse=True,
            )
        }
    )


def summarize_base_weight_resolutions(
    resolutions: Iterable[BaseWeightResolution],
) -> Mapping[str, Any]:
    """
    Summarize a base-weight resolution collection.
    """

    normalized = tuple(
        validate_base_weight_resolution(
            resolution
        )
        for resolution in resolutions
    )

    source_counts: Dict[str, int] = {}
    status_counts: Dict[str, int] = {}
    type_counts: Dict[str, int] = {}

    total_weight = 0.0
    favorable_count = 0
    unfavorable_count = 0
    neutral_count = 0

    for resolution in normalized:
        source_counts[resolution.source] = (
            source_counts.get(
                resolution.source,
                0,
            )
            + 1
        )

        status_counts[resolution.status] = (
            status_counts.get(
                resolution.status,
                0,
            )
            + 1
        )

        type_counts[resolution.interaction_type] = (
            type_counts.get(
                resolution.interaction_type,
                0,
            )
            + 1
        )

        total_weight += resolution.weight

        if resolution.favorable:
            favorable_count += 1
        elif resolution.unfavorable:
            unfavorable_count += 1
        else:
            neutral_count += 1

    return MappingProxyType(
        {
            "count": len(normalized),
            "total_weight": float(total_weight),
            "mean_weight": (
                0.0
                if not normalized
                else float(
                    total_weight
                    / len(normalized)
                )
            ),
            "favorable_count": favorable_count,
            "unfavorable_count": unfavorable_count,
            "neutral_count": neutral_count,
            "source_counts": MappingProxyType(
                source_counts
            ),
            "status_counts": MappingProxyType(
                status_counts
            ),
            "type_counts": MappingProxyType(
                type_counts
            ),
        }
    )


# -----------------------------------------------------------------------------
# 8.13. Validation
# -----------------------------------------------------------------------------

def validate_base_weight_profile(
    profile: BaseWeightProfile,
) -> BaseWeightProfile:
    """
    Validate and return a base-weight profile.
    """

    if not isinstance(
        profile,
        BaseWeightProfile,
    ):
        raise InvalidInteractionWeightError(
            "Expected a BaseWeightProfile instance."
        )

    normalize_interaction_weight_mapping(
        profile.interaction_weights
    )
    normalize_family_weight_mapping(
        profile.family_weights
    )

    return profile


def validate_base_weight_resolution(
    resolution: BaseWeightResolution,
) -> BaseWeightResolution:
    """
    Validate and return a base-weight resolution.
    """

    if not isinstance(
        resolution,
        BaseWeightResolution,
    ):
        raise InvalidInteractionWeightError(
            "Expected a BaseWeightResolution instance."
        )

    _coerce_finite_score_value(
        resolution.weight,
        name="BaseWeightResolution.weight",
    )

    return resolution


def validate_interaction_base_weights(
    weights: Mapping[Any, Number],
) -> Mapping[str, float]:
    """
    Validate and return canonical interaction weights.
    """

    return normalize_interaction_weight_mapping(
        weights
    )


# -----------------------------------------------------------------------------
# 8.14. Explainability
# -----------------------------------------------------------------------------

def explain_base_weight_resolution(
    resolution: BaseWeightResolution,
) -> ScoreExplanation:
    """
    Create a structured explanation for a base-weight resolution.
    """

    validate_base_weight_resolution(
        resolution
    )

    if resolution.status == BASE_WEIGHT_STATUS_RESOLVED:
        severity = EXPLANATION_SEVERITY_SUCCESS
    elif resolution.status == BASE_WEIGHT_STATUS_FALLBACK:
        severity = EXPLANATION_SEVERITY_WARNING
    elif resolution.status == BASE_WEIGHT_STATUS_REJECTED:
        severity = EXPLANATION_SEVERITY_ERROR
    else:
        severity = EXPLANATION_SEVERITY_WARNING

    polarity = classify_base_weight(
        resolution.weight
    )

    return ScoreExplanation(
        explanation_id=(
            f"base_weight:"
            f"{resolution.interaction_type}:"
            f"{resolution.source}"
        ),
        title=(
            "Base weight: "
            + interaction_type_display_name(
                resolution.interaction_type
            )
        ),
        message=resolution.reason,
        scope=EXPLANATION_SCOPE_INTERACTION,
        severity=severity,
        level=EXPLANATION_LEVEL_STANDARD,
        value=resolution.weight,
        entity_id=resolution.interaction_type,
        interaction_type=resolution.interaction_type,
        tags=(
            "base_weight",
            resolution.source,
            resolution.status,
            polarity,
        ),
        metadata={
            "interaction_family": (
                resolution.interaction_family
            ),
            "matched_key": resolution.matched_key,
            "used_fallback": (
                resolution.used_fallback
            ),
        },
    )


# -----------------------------------------------------------------------------
# 8.15. Section consistency validation
# -----------------------------------------------------------------------------

def _validate_section_8_base_weights() -> None:
    """
    Validate base-weight structures during module import.
    """

    profile = BaseWeightProfile(
        interaction_weights={
            "hydrogen_bond": 2.0,
            "hydrophobic": 1.0,
            "pi_stack": 2.0,
            "pi_cation": 2.0,
            "salt_bridge": 3.0,
            "clash": -2.0,
        },
        family_weights=(
            DEFAULT_INTERACTION_FAMILY_WEIGHTS
        ),
        unknown_weight=0.0,
        policy=BASE_WEIGHT_POLICY_TYPE_THEN_FAMILY,
    )

    hydrogen_bond = resolve_base_weight(
        "hbond",
        profile=profile,
    )

    if hydrogen_bond.interaction_type != (
        SCORE_TYPE_HYDROGEN_BOND
    ):
        raise RuntimeError(
            "Hydrogen-bond type normalization validation failed."
        )

    if hydrogen_bond.weight != 2.0:
        raise RuntimeError(
            "Hydrogen-bond base-weight validation failed."
        )

    salt_bridge = resolve_base_weight(
        "saltbridge",
        profile=profile,
    )

    if salt_bridge.weight != 3.0:
        raise RuntimeError(
            "Salt-bridge base-weight validation failed."
        )

    clash = resolve_base_weight(
        "clash",
        profile=profile,
    )

    if clash.weight != -2.0:
        raise RuntimeError(
            "Clash base-weight validation failed."
        )

    override = resolve_base_weight(
        "hydrogen_bond",
        profile=profile,
        overrides={
            "hbond": 4.0,
        },
    )

    if override.weight != 4.0:
        raise RuntimeError(
            "Base-weight override validation failed."
        )

    if override.source != BASE_WEIGHT_SOURCE_OVERRIDE:
        raise RuntimeError(
            "Base-weight source validation failed."
        )

    family_fallback_profile = (
        profile.without_interaction_weight(
            "cation_pi"
        )
    )

    family_fallback = resolve_base_weight(
        "cation_pi",
        profile=family_fallback_profile,
    )

    if family_fallback.interaction_family != SCORE_FAMILY_PI:
        raise RuntimeError(
            "Interaction-family fallback validation failed."
        )

    unknown = resolve_base_weight(
        "unmapped_interaction",
        profile=profile,
        strict=False,
    )

    if unknown.weight != profile.unknown_weight:
        raise RuntimeError(
            "Unknown base-weight fallback validation failed."
        )

    data = ExtractedInteractionData(
        interaction_id="hbond_1",
        interaction_type="hydrogen_bond",
        interaction_family="hydrogen_bond",
        atom_pair=(
            "A:10:N",
            "L:1:O",
        ),
        residue_pair=(
            "A:10:LYS",
            "L:1:LIG",
        ),
    )

    score = interaction_score_with_base_weight(
        data,
        profile=profile,
    )

    if score.base_weight != 2.0:
        raise RuntimeError(
            "InteractionScore base-weight integration failed."
        )

    if score.final_score != 2.0:
        raise RuntimeError(
            "Neutral-multiplier base score validation failed."
        )

    explanation = explain_base_weight_resolution(
        hydrogen_bond
    )

    if explanation.scope != EXPLANATION_SCOPE_INTERACTION:
        raise RuntimeError(
            "Base-weight explanation validation failed."
        )

    validate_base_weight_profile(profile)
    validate_base_weight_resolution(
        hydrogen_bond
    )


_validate_section_8_base_weights()


