def normalize_geometry_source(
    value: Any,
    *,
    default: str = GEOMETRY_SOURCE_UNKNOWN,
) -> str:
    """
    Normalize a geometry-quality source.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in GEOMETRY_SOURCES:
        return normalized

    return _GEOMETRY_SOURCE_ALIASES.get(
        normalized,
        default,
    )


def normalize_geometry_status(
    value: Any,
    *,
    default: str = GEOMETRY_STATUS_UNKNOWN,
) -> str:
    """
    Normalize a geometry-resolution status.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in GEOMETRY_STATUSES:
        return normalized

    return _GEOMETRY_STATUS_ALIASES.get(
        normalized,
        default,
    )


def normalize_geometry_direction(
    value: Any,
    *,
    default: str = GEOMETRY_DIRECTION_TARGET,
) -> str:
    """
    Normalize metric direction semantics.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in GEOMETRY_DIRECTIONS:
        return normalized

    return _GEOMETRY_DIRECTION_ALIASES.get(
        normalized,
        default,
    )


def normalize_geometry_combination_mode(
    value: Any,
    *,
    default: str = DEFAULT_GEOMETRY_COMBINATION_MODE,
) -> str:
    """
    Normalize geometry-metric combination mode.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in GEOMETRY_COMBINATION_MODES:
        return normalized

    return _GEOMETRY_COMBINATION_ALIASES.get(
        normalized,
        default,
    )


# -----------------------------------------------------------------------------
# 10.3. Exceptions
# -----------------------------------------------------------------------------

class GeometryQualityError(ScoringError):
    """
    Base exception for geometry-quality failures.
    """


class InvalidGeometryQualityError(GeometryQualityError):
    """
    Raised when geometry-quality data are invalid.
    """


class UnknownGeometryQualityError(GeometryQualityError):
    """
    Raised when geometry quality cannot be resolved.
    """


class InvalidGeometryRuleError(GeometryQualityError):
    """
    Raised when a geometry-evaluation rule is invalid.
    """


class ConflictingGeometryQualityError(GeometryQualityError):
    """
    Raised when equivalent geometry labels define conflicting values.
    """


# -----------------------------------------------------------------------------
# 10.4. GeometryMetricRule
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class GeometryMetricRule:
    """
    Immutable rule for converting one geometry metric to a quality score.

    The normalized score ranges from ``0.0`` to ``1.0``.

    For ``lower_is_better``:
    - values at or below ``ideal_value`` score 1.0;
    - values at or above ``limit_value`` score 0.0.

    For ``higher_is_better``:
    - values at or above ``ideal_value`` score 1.0;
    - values at or below ``limit_value`` score 0.0.

    For ``target``:
    - values inside ``ideal_min`` and ``ideal_max`` score 1.0;
    - values outside ``limit_min`` and ``limit_max`` score 0.0.
    """

    metric: str
    direction: str = GEOMETRY_DIRECTION_TARGET

    ideal_value: Optional[float] = None
    limit_value: Optional[float] = None

    ideal_min: Optional[float] = None
    ideal_max: Optional[float] = None
    limit_min: Optional[float] = None
    limit_max: Optional[float] = None

    weight: float = 1.0
    required: bool = False
    enabled: bool = True

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize and validate the metric rule.
        """

        metric = _normalize_scoring_name(
            self.metric
        )

        if metric not in GEOMETRY_METRICS:
            raise InvalidGeometryRuleError(
                f"Unsupported geometry metric {self.metric!r}."
            )

        direction = normalize_geometry_direction(
            self.direction
        )

        weight = float(
            _coerce_finite_score_value(
                self.weight,
                name="GeometryMetricRule.weight",
            )
        )

        if weight < 0.0:
            raise InvalidGeometryRuleError(
                "GeometryMetricRule.weight cannot be negative."
            )

        scalar_values = {
            "ideal_value": self.ideal_value,
            "limit_value": self.limit_value,
            "ideal_min": self.ideal_min,
            "ideal_max": self.ideal_max,
            "limit_min": self.limit_min,
            "limit_max": self.limit_max,
        }

        normalized_values: Dict[str, Optional[float]] = {}

        for name, value in scalar_values.items():
            normalized_values[name] = (
                None
                if value is None
                else float(
                    _coerce_finite_score_value(
                        value,
                        name=f"GeometryMetricRule.{name}",
                    )
                )
            )

        if direction in {
            GEOMETRY_DIRECTION_LOWER_IS_BETTER,
            GEOMETRY_DIRECTION_HIGHER_IS_BETTER,
        }:
            if (
                normalized_values["ideal_value"] is None
                or normalized_values["limit_value"] is None
            ):
                raise InvalidGeometryRuleError(
                    "Directional geometry rules require ideal_value "
                    "and limit_value."
                )

            if (
                normalized_values["ideal_value"]
                == normalized_values["limit_value"]
            ):
                raise InvalidGeometryRuleError(
                    "ideal_value and limit_value must differ."
                )

        else:
            required_names = (
                "ideal_min",
                "ideal_max",
                "limit_min",
                "limit_max",
            )

            if any(
                normalized_values[name] is None
                for name in required_names
            ):
                raise InvalidGeometryRuleError(
                    "Target geometry rules require ideal_min, "
                    "ideal_max, limit_min and limit_max."
                )

            ideal_min = normalized_values["ideal_min"]
            ideal_max = normalized_values["ideal_max"]
            limit_min = normalized_values["limit_min"]
            limit_max = normalized_values["limit_max"]

            if not (
                limit_min
                <= ideal_min
                <= ideal_max
                <= limit_max
            ):
                raise InvalidGeometryRuleError(
                    "Target geometry bounds must satisfy "
                    "limit_min <= ideal_min <= ideal_max <= limit_max."
                )

        object.__setattr__(self, "metric", metric)
        object.__setattr__(self, "direction", direction)
        object.__setattr__(self, "weight", weight)
        object.__setattr__(self, "required", bool(self.required))
        object.__setattr__(self, "enabled", bool(self.enabled))

        for name, value in normalized_values.items():
            object.__setattr__(self, name, value)

        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def evaluate(
        self,
        value: Optional[Number],
    ) -> Optional[float]:
        """
        Evaluate one metric value.

        Returns ``None`` when the value is missing and the metric is optional.
        """

        if not self.enabled:
            return None

        if value is None:
            if self.required:
                raise InvalidGeometryQualityError(
                    f"Required geometry metric {self.metric!r} is missing."
                )

            return None

        numeric_value = float(
            _coerce_finite_score_value(
                value,
                name=f"geometry metric {self.metric!r}",
            )
        )

        if self.direction == GEOMETRY_DIRECTION_LOWER_IS_BETTER:
            assert self.ideal_value is not None
            assert self.limit_value is not None

            if numeric_value <= self.ideal_value:
                return 1.0

            if numeric_value >= self.limit_value:
                return 0.0

            return float(
                1.0
                - (
                    numeric_value - self.ideal_value
                )
                / (
                    self.limit_value - self.ideal_value
                )
            )

        if self.direction == GEOMETRY_DIRECTION_HIGHER_IS_BETTER:
            assert self.ideal_value is not None
            assert self.limit_value is not None

            if numeric_value >= self.ideal_value:
                return 1.0

            if numeric_value <= self.limit_value:
                return 0.0

            return float(
                (
                    numeric_value - self.limit_value
                )
                / (
                    self.ideal_value - self.limit_value
                )
            )

        assert self.ideal_min is not None
        assert self.ideal_max is not None
        assert self.limit_min is not None
        assert self.limit_max is not None

        if self.ideal_min <= numeric_value <= self.ideal_max:
            return 1.0

        if (
            numeric_value <= self.limit_min
            or numeric_value >= self.limit_max
        ):
            return 0.0

        if numeric_value < self.ideal_min:
            denominator = self.ideal_min - self.limit_min

            if denominator <= 0.0:
                return 1.0

            return float(
                (
                    numeric_value - self.limit_min
                )
                / denominator
            )

        denominator = self.limit_max - self.ideal_max

        if denominator <= 0.0:
            return 1.0

        return float(
            (
                self.limit_max - numeric_value
            )
            / denominator
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "metric": self.metric,
            "direction": self.direction,
            "ideal_value": self.ideal_value,
            "limit_value": self.limit_value,
            "ideal_min": self.ideal_min,
            "ideal_max": self.ideal_max,
            "limit_min": self.limit_min,
            "limit_max": self.limit_max,
            "weight": float(self.weight),
            "required": bool(self.required),
            "enabled": bool(self.enabled),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


