# -----------------------------------------------------------------------------
# 10.6. GeometryQualityProfile
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class GeometryQualityProfile:
    """
    Immutable geometry-quality evaluation profile.
    """

    multipliers: Mapping[str, float] = field(
        default_factory=lambda: DEFAULT_GEOMETRY_MULTIPLIERS
    )

    rules_by_type: Mapping[
        str,
        Tuple[GeometryMetricRule, ...],
    ] = field(
        default_factory=lambda: DEFAULT_GEOMETRY_RULES_BY_TYPE
    )

    ideal_minimum_score: float = (
        DEFAULT_GEOMETRY_IDEAL_MINIMUM_SCORE
    )
    good_minimum_score: float = (
        DEFAULT_GEOMETRY_GOOD_MINIMUM_SCORE
    )
    acceptable_minimum_score: float = (
        DEFAULT_GEOMETRY_ACCEPTABLE_MINIMUM_SCORE
    )
    poor_minimum_score: float = (
        DEFAULT_GEOMETRY_POOR_MINIMUM_SCORE
    )

    unknown_multiplier: float = (
        DEFAULT_UNKNOWN_GEOMETRY_MULTIPLIER
    )
    combination_mode: str = (
        DEFAULT_GEOMETRY_COMBINATION_MODE
    )

    trust_explicit_quality: bool = True
    strict: bool = False

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize and validate the profile.
        """

        multipliers = normalize_geometry_multiplier_mapping(
            self.multipliers
        )

        normalized_rules: Dict[
            str,
            Tuple[GeometryMetricRule, ...],
        ] = {}

        for raw_type, raw_rules in self.rules_by_type.items():
            interaction_type = normalize_interaction_type(
                raw_type,
                preserve_unknown=True,
            )

            rules: List[GeometryMetricRule] = []

            for rule in raw_rules:
                if not isinstance(
                    rule,
                    GeometryMetricRule,
                ):
                    raise InvalidGeometryRuleError(
                        "rules_by_type values must contain only "
                        "GeometryMetricRule instances."
                    )

                rules.append(rule)

            normalized_rules[interaction_type] = tuple(rules)

        ideal_minimum_score = _normalize_quality_threshold(
            self.ideal_minimum_score,
            "ideal_minimum_score",
        )
        good_minimum_score = _normalize_quality_threshold(
            self.good_minimum_score,
            "good_minimum_score",
        )
        acceptable_minimum_score = _normalize_quality_threshold(
            self.acceptable_minimum_score,
            "acceptable_minimum_score",
        )
        poor_minimum_score = _normalize_quality_threshold(
            self.poor_minimum_score,
            "poor_minimum_score",
        )

        if not (
            1.0
            >= ideal_minimum_score
            >= good_minimum_score
            >= acceptable_minimum_score
            >= poor_minimum_score
            >= 0.0
        ):
            raise InvalidGeometryQualityError(
                "Geometry quality thresholds must be monotonically "
                "decreasing between 1.0 and 0.0."
            )

        unknown_multiplier = _validate_multiplier_value(
            self.unknown_multiplier,
            name="unknown geometry multiplier",
            allow_negative=False,
        )

        object.__setattr__(
            self,
            "multipliers",
            multipliers,
        )
        object.__setattr__(
            self,
            "rules_by_type",
            MappingProxyType(normalized_rules),
        )
        object.__setattr__(
            self,
            "ideal_minimum_score",
            ideal_minimum_score,
        )
        object.__setattr__(
            self,
            "good_minimum_score",
            good_minimum_score,
        )
        object.__setattr__(
            self,
            "acceptable_minimum_score",
            acceptable_minimum_score,
        )
        object.__setattr__(
            self,
            "poor_minimum_score",
            poor_minimum_score,
        )
        object.__setattr__(
            self,
            "unknown_multiplier",
            unknown_multiplier,
        )
        object.__setattr__(
            self,
            "combination_mode",
            normalize_geometry_combination_mode(
                self.combination_mode
            ),
        )
        object.__setattr__(
            self,
            "trust_explicit_quality",
            bool(self.trust_explicit_quality),
        )
        object.__setattr__(
            self,
            "strict",
            bool(self.strict),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def classify_score(
        self,
        score: Number,
    ) -> str:
        """
        Convert a normalized geometry score into a quality label.
        """

        normalized_score = _normalize_geometry_score(
            score
        )

        if normalized_score >= self.ideal_minimum_score:
            return GEOMETRY_IDEAL

        if normalized_score >= self.good_minimum_score:
            return GEOMETRY_GOOD

        if normalized_score >= self.acceptable_minimum_score:
            return GEOMETRY_ACCEPTABLE

        if normalized_score >= self.poor_minimum_score:
            return GEOMETRY_POOR

        return GEOMETRY_UNKNOWN

    def multiplier_for(
        self,
        quality: Any,
    ) -> float:
        """
        Return a geometry-quality multiplier.
        """

        canonical_quality = normalize_geometry_quality(
            quality
        )

        return self.multipliers.get(
            canonical_quality,
            self.unknown_multiplier,
        )

    def rules_for_type(
        self,
        interaction_type: Any,
    ) -> Tuple[GeometryMetricRule, ...]:
        """
        Return geometry rules for an interaction type.
        """

        canonical_type = normalize_interaction_type(
            interaction_type,
            preserve_unknown=True,
        )

        return self.rules_by_type.get(
            canonical_type,
            (),
        )

    def with_updates(
        self,
        **changes: Any,
    ) -> "GeometryQualityProfile":
        """
        Return a validated profile copy.
        """

        return replace(
            self,
            **changes,
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "multipliers": dict(self.multipliers),
            "rules_by_type": {
                interaction_type: [
                    rule.to_dict(
                        include_metadata=include_metadata
                    )
                    for rule in rules
                ]
                for interaction_type, rules
                in self.rules_by_type.items()
            },
            "ideal_minimum_score": float(
                self.ideal_minimum_score
            ),
            "good_minimum_score": float(
                self.good_minimum_score
            ),
            "acceptable_minimum_score": float(
                self.acceptable_minimum_score
            ),
            "poor_minimum_score": float(
                self.poor_minimum_score
            ),
            "unknown_multiplier": float(
                self.unknown_multiplier
            ),
            "combination_mode": self.combination_mode,
            "trust_explicit_quality": bool(
                self.trust_explicit_quality
            ),
            "strict": bool(self.strict),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


DEFAULT_GEOMETRY_QUALITY_PROFILE: Final[
    GeometryQualityProfile
] = GeometryQualityProfile()


# -----------------------------------------------------------------------------
# 10.7. Geometry metric evaluation
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class GeometryMetricEvaluation:
    """
    Evaluation result for one geometry metric.
    """

    metric: str
    value: Optional[float]
    score: Optional[float]

    weight: float = 1.0
    source: str = GEOMETRY_SOURCE_METRICS
    reason: str = ""

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize metric evaluation fields.
        """

        metric = _normalize_scoring_name(
            self.metric
        )

        if metric not in GEOMETRY_METRICS:
            raise InvalidGeometryQualityError(
                f"Unsupported geometry metric {metric!r}."
            )

        value = (
            None
            if self.value is None
            else float(
                _coerce_finite_score_value(
                    self.value,
                    name=f"geometry metric {metric!r}",
                )
            )
        )

        score = (
            None
            if self.score is None
            else _normalize_geometry_score(
                self.score
            )
        )

        weight = float(
            _coerce_finite_score_value(
                self.weight,
                name="GeometryMetricEvaluation.weight",
            )
        )

        if weight < 0.0:
            raise InvalidGeometryQualityError(
                "Geometry metric weight cannot be negative."
            )

        object.__setattr__(self, "metric", metric)
        object.__setattr__(self, "value", value)
        object.__setattr__(self, "score", score)
        object.__setattr__(self, "weight", weight)
        object.__setattr__(
            self,
            "source",
            normalize_geometry_source(
                self.source
            ),
        )
        object.__setattr__(
            self,
            "reason",
            _coerce_optional_text(
                self.reason
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def available(self) -> bool:
        """Return whether the metric produced a score."""

        return self.score is not None

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "metric": self.metric,
            "value": self.value,
            "score": self.score,
            "weight": float(self.weight),
            "source": self.source,
            "reason": self.reason,
            "available": bool(self.available),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 10.8. GeometryQualityResolution
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class GeometryQualityResolution:
    """
    Immutable geometry-quality resolution.
    """

    interaction_type: str
    quality: str
    score: Optional[float]
    multiplier: float

    source: str = GEOMETRY_SOURCE_UNKNOWN
    status: str = GEOMETRY_STATUS_UNKNOWN

    evaluations: Tuple[
        GeometryMetricEvaluation,
        ...,
    ] = field(default_factory=tuple)

    used_fallback: bool = False
    reason: str = ""

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize the geometry resolution.
        """

        interaction_type = normalize_interaction_type(
            self.interaction_type,
            preserve_unknown=True,
        )

        quality = normalize_geometry_quality(
            self.quality
        )

        score = (
            None
            if self.score is None
            else _normalize_geometry_score(
                self.score
            )
        )

        multiplier = _validate_multiplier_value(
            self.multiplier,
            name="geometry multiplier",
            allow_negative=False,
        )

        normalized_evaluations: List[
            GeometryMetricEvaluation
        ] = []

        for evaluation in self.evaluations:
            if not isinstance(
                evaluation,
                GeometryMetricEvaluation,
            ):
                raise InvalidGeometryQualityError(
                    "evaluations must contain only "
                    "GeometryMetricEvaluation instances."
                )

            normalized_evaluations.append(evaluation)

        object.__setattr__(
            self,
            "interaction_type",
            interaction_type,
        )
        object.__setattr__(
            self,
            "quality",
            quality,
        )
        object.__setattr__(
            self,
            "score",
            score,
        )
        object.__setattr__(
            self,
            "multiplier",
            multiplier,
        )
        object.__setattr__(
            self,
            "source",
            normalize_geometry_source(
                self.source
            ),
        )
        object.__setattr__(
            self,
            "status",
            normalize_geometry_status(
                self.status
            ),
        )
        object.__setattr__(
            self,
            "evaluations",
            tuple(normalized_evaluations),
        )
        object.__setattr__(
            self,
            "used_fallback",
            bool(self.used_fallback),
        )
        object.__setattr__(
            self,
            "reason",
            _coerce_optional_text(
                self.reason
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def resolved(self) -> bool:
        """Return whether geometry quality was resolved."""

        return self.status in {
            GEOMETRY_STATUS_RESOLVED,
            GEOMETRY_STATUS_INFERRED,
        }

    @property
    def neutral(self) -> bool:
        """Return whether geometry leaves the score unchanged."""

        return (
            abs(
                self.multiplier
                - NEUTRAL_MULTIPLIER
            )
            <= SCORE_COMPARISON_TOLERANCE
        )

    def apply(
        self,
        value: Number,
    ) -> float:
        """
        Apply the geometry multiplier.
        """

        numeric_value = _coerce_finite_score_value(
            value,
            name="geometry multiplier input",
        )

        return float(
            numeric_value
            * self.multiplier
        )

    def to_component(
        self,
    ) -> ScoreComponent:
        """
        Convert the resolution into a ScoreComponent.
        """

        return make_multiplier_component(
            component_type="geometry",
            value=self.multiplier,
            label=self.quality,
            source=self.source,
            description=self.reason,
            metadata={
                "geometry_score": self.score,
                "status": self.status,
                "used_fallback": self.used_fallback,
            },
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "interaction_type": self.interaction_type,
            "quality": self.quality,
            "score": self.score,
            "multiplier": float(self.multiplier),
            "source": self.source,
            "status": self.status,
            "used_fallback": bool(
                self.used_fallback
            ),
            "reason": self.reason,
            "resolved": bool(self.resolved),
            "neutral": bool(self.neutral),
            "evaluations": [
                evaluation.to_dict(
                    include_metadata=include_metadata
                )
                for evaluation in self.evaluations
            ],
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 10.9. Internal normalization helpers
# -----------------------------------------------------------------------------

def _normalize_quality_threshold(
    value: Number,
    name: str,
) -> float:
    """
    Normalize a quality threshold to the range 0–1.
    """

    normalized = float(
        _coerce_finite_score_value(
            value,
            name=name,
        )
    )

    if not 0.0 <= normalized <= 1.0:
        raise InvalidGeometryQualityError(
            f"{name} must be between 0.0 and 1.0."
        )

    return normalized


def _normalize_geometry_score(
    value: Number,
) -> float:
    """
    Normalize a geometry-quality score to the range 0–1.
    """

    normalized = float(
        _coerce_finite_score_value(
            value,
            name="geometry quality score",
        )
    )

    if not 0.0 <= normalized <= 1.0:
        raise InvalidGeometryQualityError(
            "Geometry quality scores must be between 0.0 and 1.0."
        )

    return normalized


def normalize_geometry_multiplier_mapping(
    multipliers: Optional[Mapping[Any, Number]],
) -> Mapping[str, float]:
    """
    Normalize geometry-quality multipliers.
    """

    if multipliers is None:
        return MappingProxyType({})

    if not isinstance(multipliers, Mapping):
        raise InvalidGeometryQualityError(
            "Geometry multipliers must be provided as a mapping."
        )

    normalized: Dict[str, float] = {}

    for raw_quality, raw_multiplier in multipliers.items():
        quality = normalize_geometry_quality(
            raw_quality
        )

        multiplier = _validate_multiplier_value(
            raw_multiplier,
            name=f"geometry multiplier for {quality!r}",
            allow_negative=False,
        )

        previous = normalized.get(quality)

        if (
            previous is not None
            and abs(previous - multiplier)
            > SCORE_COMPARISON_TOLERANCE
        ):
            raise ConflictingGeometryQualityError(
                f"Geometry quality {quality!r} received conflicting "
                "multipliers."
            )

        normalized[quality] = multiplier

    return MappingProxyType(normalized)


# -----------------------------------------------------------------------------
# 10.10. Metric extraction
# -----------------------------------------------------------------------------

def extract_geometry_metric_value(
    source: Any,
    metric: str,
) -> Optional[float]:
    """
    Extract one geometry metric from an interaction-like object.
    """

    normalized_metric = _normalize_scoring_name(
        metric
    )

    if normalized_metric not in GEOMETRY_METRICS:
        raise InvalidGeometryQualityError(
            f"Unsupported geometry metric {metric!r}."
        )

    if isinstance(source, ExtractedInteractionData):
        value = getattr(
            source,
            normalized_metric,
            None,
        )
    elif normalized_metric == GEOMETRY_METRIC_DISTANCE:
        value = extract_interaction_distance(source)
    elif normalized_metric == GEOMETRY_METRIC_ANGLE:
        value = extract_interaction_angle(source)
    elif normalized_metric == GEOMETRY_METRIC_OFFSET:
        value = extract_interaction_offset(source)
    elif normalized_metric == GEOMETRY_METRIC_PLANARITY:
        value = extract_interaction_planarity(source)
    else:
        value = extract_interaction_overlap(source)

    if value is None:
        return None

    return float(
        _coerce_finite_score_value(
            value,
            name=f"geometry metric {normalized_metric!r}",
        )
    )


def extract_geometry_metrics(
    source: Any,
) -> Mapping[str, Optional[float]]:
    """
    Extract all supported geometry metrics.
    """

    return MappingProxyType(
        {
            metric: extract_geometry_metric_value(
                source,
                metric,
            )
            for metric in sorted(
                GEOMETRY_METRICS
            )
        }
    )


# -----------------------------------------------------------------------------
# 10.11. Metric combination
# -----------------------------------------------------------------------------

def combine_geometry_metric_scores(
    evaluations: Iterable[GeometryMetricEvaluation],
    *,
    mode: str = DEFAULT_GEOMETRY_COMBINATION_MODE,
) -> Optional[float]:
    """
    Combine available geometry metric scores.
    """

    normalized_mode = normalize_geometry_combination_mode(
        mode
    )

    available = tuple(
        evaluation
        for evaluation in evaluations
        if evaluation.score is not None
    )

    if not available:
        return None

    scores = tuple(
        float(evaluation.score)
        for evaluation in available
        if evaluation.score is not None
    )

    if normalized_mode == GEOMETRY_COMBINATION_WORST:
        return min(scores)

    if normalized_mode == GEOMETRY_COMBINATION_BEST:
        return max(scores)

    if normalized_mode == GEOMETRY_COMBINATION_MEAN:
        return float(
            sum(scores) / len(scores)
        )

    weighted_total = sum(
        float(evaluation.score)
        * evaluation.weight
        for evaluation in available
        if evaluation.score is not None
    )

    total_weight = sum(
        evaluation.weight
        for evaluation in available
    )

    if total_weight <= 0.0:
        return float(
            sum(scores) / len(scores)
        )

    return float(
        weighted_total / total_weight
    )


# -----------------------------------------------------------------------------
# 10.12. Geometry evaluation
# -----------------------------------------------------------------------------

def evaluate_geometry_metrics(
    source: Any,
    *,
    interaction_type: Optional[Any] = None,
    profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
) -> Tuple[GeometryMetricEvaluation, ...]:
    """
    Evaluate all configured geometry metrics for an interaction.
    """

    if not isinstance(
        profile,
        GeometryQualityProfile,
    ):
        raise InvalidGeometryQualityError(
            "profile must be a GeometryQualityProfile."
        )

    canonical_type = normalize_interaction_type(
        (
            interaction_type
            if interaction_type is not None
            else extract_interaction_type(source)
        ),
        preserve_unknown=True,
    )

    rules = profile.rules_for_type(
        canonical_type
    )

    evaluations: List[
        GeometryMetricEvaluation
    ] = []

    for rule in rules:
        value = extract_geometry_metric_value(
            source,
            rule.metric,
        )

        score = rule.evaluate(value)

        evaluations.append(
            GeometryMetricEvaluation(
                metric=rule.metric,
                value=value,
                score=score,
                weight=rule.weight,
                source=GEOMETRY_SOURCE_METRICS,
                reason=(
                    "The metric was evaluated using the configured "
                    f"{canonical_type!r} geometry rule."
                ),
                metadata={
                    "direction": rule.direction,
                    "required": rule.required,
                },
            )
        )

    return tuple(evaluations)


def resolve_geometry_quality(
    source: Any,
    *,
    interaction_type: Optional[Any] = None,
    explicit_quality: Optional[Any] = None,
    profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    strict: Optional[bool] = None,
) -> GeometryQualityResolution:
    """
    Resolve geometry quality and its multiplier.
    """

    if not isinstance(
        profile,
        GeometryQualityProfile,
    ):
        raise InvalidGeometryQualityError(
            "profile must be a GeometryQualityProfile."
        )

    canonical_type = normalize_interaction_type(
        (
            interaction_type
            if interaction_type is not None
            else extract_interaction_type(source)
        ),
        preserve_unknown=True,
    )

    strict_mode = (
        profile.strict
        if strict is None
        else bool(strict)
    )

    declared_quality = explicit_quality

    if declared_quality is None:
        if isinstance(source, InteractionScore):
            declared_quality = source.geometry_quality
        elif isinstance(source, ExtractedInteractionData):
            declared_quality = source.geometry_quality
        else:
            declared_quality = extract_geometry_quality(
                source
            )

    canonical_declared_quality = normalize_geometry_quality(
        declared_quality
    )

    if (
        profile.trust_explicit_quality
        and canonical_declared_quality
        != GEOMETRY_UNKNOWN
    ):
        return GeometryQualityResolution(
            interaction_type=canonical_type,
            quality=canonical_declared_quality,
            score=None,
            multiplier=profile.multiplier_for(
                canonical_declared_quality
            ),
            source=GEOMETRY_SOURCE_EXPLICIT,
            status=GEOMETRY_STATUS_RESOLVED,
            evaluations=(),
            used_fallback=False,
            reason=(
                "Geometry quality was obtained from the explicit "
                "interaction classification."
            ),
        )

    evaluations = evaluate_geometry_metrics(
        source,
        interaction_type=canonical_type,
        profile=profile,
    )

    combined_score = combine_geometry_metric_scores(
        evaluations,
        mode=profile.combination_mode,
    )

    if combined_score is not None:
        quality = profile.classify_score(
            combined_score
        )

        return GeometryQualityResolution(
            interaction_type=canonical_type,
            quality=quality,
            score=combined_score,
            multiplier=profile.multiplier_for(
                quality
            ),
            source=GEOMETRY_SOURCE_METRICS,
            status=GEOMETRY_STATUS_INFERRED,
            evaluations=evaluations,
            used_fallback=False,
            reason=(
                "Geometry quality was inferred from the available "
                "interaction metrics."
            ),
        )

    if strict_mode:
        raise UnknownGeometryQualityError(
            f"No geometry quality or usable geometry metrics were "
            f"available for interaction type {canonical_type!r}."
        )

    return GeometryQualityResolution(
        interaction_type=canonical_type,
        quality=GEOMETRY_UNKNOWN,
        score=None,
        multiplier=profile.unknown_multiplier,
        source=GEOMETRY_SOURCE_FALLBACK,
        status=GEOMETRY_STATUS_UNKNOWN,
        evaluations=evaluations,
        used_fallback=True,
        reason=(
            "No explicit quality or usable geometry metrics were "
            "available; the unknown-geometry fallback was used."
        ),
    )


def resolve_geometry_quality_collection(
    source: Any,
    *,
    profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    strict: Optional[bool] = None,
    skip_errors: bool = False,
) -> Tuple[GeometryQualityResolution, ...]:
    """
    Resolve geometry quality for a heterogeneous collection.
    """

    resolutions: List[
        GeometryQualityResolution
    ] = []

    for interaction in iter_interaction_objects(
        source
    ):
        try:
            resolution = resolve_geometry_quality(
                interaction,
                profile=profile,
                strict=strict,
            )
        except (
            ScoringError,
            TypeError,
            ValueError,
            AttributeError,
        ):
            if skip_errors:
                continue

            raise

        resolutions.append(resolution)

    return tuple(resolutions)


# -----------------------------------------------------------------------------
# 10.13. Geometry multiplier lookup
# -----------------------------------------------------------------------------

def geometry_multiplier_for_quality(
    quality: Any,
    *,
    profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
) -> float:
    """
    Return the multiplier for a geometry-quality label.
    """

    return profile.multiplier_for(
        quality
    )


def geometry_multiplier_for_interaction(
    interaction: Any,
    *,
    profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    strict: Optional[bool] = None,
) -> float:
    """
    Resolve and return an interaction geometry multiplier.
    """

    return resolve_geometry_quality(
        interaction,
        profile=profile,
        strict=strict,
    ).multiplier


def apply_geometry_multiplier(
    value: Number,
    resolution: GeometryQualityResolution,
) -> float:
    """
    Apply a geometry-quality multiplier.
    """

    validate_geometry_quality_resolution(
        resolution
    )

    return resolution.apply(value)


# -----------------------------------------------------------------------------
# 10.14. InteractionScore integration
# -----------------------------------------------------------------------------

def interaction_score_with_geometry(
    data: ExtractedInteractionData,
    *,
    base_weight_profile: BaseWeightProfile = (
        DEFAULT_BASE_WEIGHT_PROFILE
    ),
    multiplier_profile: InteractionMultiplierProfile = (
        DEFAULT_INTERACTION_MULTIPLIER_PROFILE
    ),
    geometry_profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    weight_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strength_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    classification_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strict_weights: Optional[bool] = None,
    strict_strength: Optional[bool] = None,
    strict_classification: Optional[bool] = None,
    strict_geometry: Optional[bool] = None,
    preserve_components: bool = True,
) -> InteractionScore:
    """
    Create an InteractionScore with all multiplicative terms.

    Penalties and bonuses remain zero.
    """

    validate_extracted_interaction_data(data)

    base_resolution = resolve_base_weight(
        data.interaction_type,
        interaction_family=data.interaction_family,
        profile=base_weight_profile,
        scoring_config=scoring_config,
        overrides=weight_overrides,
        strict=strict_weights,
    )

    multiplier_resolution = (
        resolve_interaction_multipliers(
            data,
            profile=multiplier_profile,
            scoring_config=scoring_config,
            strength_overrides=strength_overrides,
            classification_overrides=(
                classification_overrides
            ),
            strict_strength=strict_strength,
            strict_classification=(
                strict_classification
            ),
        )
    )

    geometry_resolution = resolve_geometry_quality(
        data,
        interaction_type=data.interaction_type,
        explicit_quality=data.geometry_quality,
        profile=geometry_profile,
        strict=strict_geometry,
    )

    metadata = dict(data.metadata)
    metadata["base_weight_resolution"] = (
        base_resolution.to_dict(
            include_metadata=True
        )
    )
    metadata["multiplier_resolution"] = (
        multiplier_resolution.to_dict(
            include_metadata=True
        )
    )
    metadata["geometry_resolution"] = (
        geometry_resolution.to_dict(
            include_metadata=True
        )
    )

    resolved_data = replace(
        data,
        geometry_quality=(
            geometry_resolution.quality
        ),
        polarity=classify_base_weight(
            base_resolution.weight
        ),
        metadata=metadata,
    )

    return interaction_score_from_extracted_data(
        resolved_data,
        base_weight=base_resolution.weight,
        strength_multiplier=(
            multiplier_resolution.strength.multiplier
        ),
        classification_multiplier=(
            multiplier_resolution.classification.multiplier
        ),
        geometry_multiplier=(
            geometry_resolution.multiplier
        ),
        penalty_score=0.0,
        bonus_score=0.0,
        preserve_components=preserve_components,
    )


def update_interaction_score_geometry(
    score: InteractionScore,
    *,
    geometry_profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    strict: Optional[bool] = None,
) -> InteractionScore:
    """
    Resolve and replace the geometry multiplier of an InteractionScore.
    """

    validate_interaction_score(
        score,
        validate_consistency=False,
    )

    resolution = resolve_geometry_quality(
        score,
        interaction_type=score.interaction_type,
        explicit_quality=score.geometry_quality,
        profile=geometry_profile,
        strict=strict,
    )

    metadata = dict(score.metadata)
    metadata["geometry_resolution"] = (
        resolution.to_dict(
            include_metadata=True
        )
    )

    components = tuple(
        component
        for component in score.components
        if component.component_type != "geometry"
    )

    components = components + (
        resolution.to_component(),
    )

    return replace(
        score,
        geometry_quality=resolution.quality,
        geometry_multiplier=resolution.multiplier,
        components=components,
        metadata=metadata,
    )


def interactions_with_geometry(
    interactions: Iterable[ExtractedInteractionData],
    *,
    base_weight_profile: BaseWeightProfile = (
        DEFAULT_BASE_WEIGHT_PROFILE
    ),
    multiplier_profile: InteractionMultiplierProfile = (
        DEFAULT_INTERACTION_MULTIPLIER_PROFILE
    ),
    geometry_profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    weight_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strength_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    classification_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strict_weights: Optional[bool] = None,
    strict_strength: Optional[bool] = None,
    strict_classification: Optional[bool] = None,
    strict_geometry: Optional[bool] = None,
    preserve_components: bool = True,
    skip_errors: bool = False,
) -> Tuple[InteractionScore, ...]:
    """
    Convert extracted interactions into geometry-adjusted scores.
    """

    scores: List[InteractionScore] = []

    for interaction in interactions:
        try:
            score = interaction_score_with_geometry(
                interaction,
                base_weight_profile=base_weight_profile,
                multiplier_profile=multiplier_profile,
                geometry_profile=geometry_profile,
                scoring_config=scoring_config,
                weight_overrides=weight_overrides,
                strength_overrides=strength_overrides,
                classification_overrides=(
                    classification_overrides
                ),
                strict_weights=strict_weights,
                strict_strength=strict_strength,
                strict_classification=(
                    strict_classification
                ),
                strict_geometry=strict_geometry,
                preserve_components=preserve_components,
            )
        except (
            ScoringError,
            TypeError,
            ValueError,
            AttributeError,
        ):
            if skip_errors:
                continue

            raise

        scores.append(score)

    return sort_interaction_scores(scores)


# -----------------------------------------------------------------------------
# 10.15. Summary helpers
# -----------------------------------------------------------------------------

def summarize_geometry_resolutions(
    resolutions: Iterable[GeometryQualityResolution],
) -> Mapping[str, Any]:
    """
    Summarize geometry-quality resolutions.
    """

    normalized = tuple(
        validate_geometry_quality_resolution(
            resolution
        )
        for resolution in resolutions
    )

    quality_counts: Dict[str, int] = {}
    source_counts: Dict[str, int] = {}
    status_counts: Dict[str, int] = {}

    scores: List[float] = []
    multipliers: List[float] = []

    for resolution in normalized:
        quality_counts[resolution.quality] = (
            quality_counts.get(
                resolution.quality,
                0,
            )
            + 1
        )

        source_counts[resolution.source] = (
            source_counts.get(
                resolution.source,
                0,
            )
            + 1
        )

        status_counts[resolution.status] = (
            status_counts.get(
                resolution.status,
                0,
            )
            + 1
        )

        if resolution.score is not None:
            scores.append(resolution.score)

        multipliers.append(
            resolution.multiplier
        )

    return MappingProxyType(
        {
            "count": len(normalized),
            "quality_counts": MappingProxyType(
                quality_counts
            ),
            "source_counts": MappingProxyType(
                source_counts
            ),
            "status_counts": MappingProxyType(
                status_counts
            ),
            "mean_geometry_score": (
                None
                if not scores
                else float(
                    sum(scores) / len(scores)
                )
            ),
            "minimum_geometry_score": (
                None
                if not scores
                else min(scores)
            ),
            "maximum_geometry_score": (
                None
                if not scores
                else max(scores)
            ),
            "mean_geometry_multiplier": (
                0.0
                if not multipliers
                else float(
                    sum(multipliers)
                    / len(multipliers)
                )
            ),
        }
    )


# -----------------------------------------------------------------------------
# 10.16. Validation
# -----------------------------------------------------------------------------

def validate_geometry_metric_rule(
    rule: GeometryMetricRule,
) -> GeometryMetricRule:
    """
    Validate and return a geometry metric rule.
    """

    if not isinstance(
        rule,
        GeometryMetricRule,
    ):
        raise InvalidGeometryRuleError(
            "Expected a GeometryMetricRule instance."
        )

    return rule


def validate_geometry_quality_profile(
    profile: GeometryQualityProfile,
) -> GeometryQualityProfile:
    """
    Validate and return a geometry-quality profile.
    """

    if not isinstance(
        profile,
        GeometryQualityProfile,
    ):
        raise InvalidGeometryQualityError(
            "Expected a GeometryQualityProfile instance."
        )

    normalize_geometry_multiplier_mapping(
        profile.multipliers
    )

    for rules in profile.rules_by_type.values():
        for rule in rules:
            validate_geometry_metric_rule(rule)

    return profile


def validate_geometry_metric_evaluation(
    evaluation: GeometryMetricEvaluation,
) -> GeometryMetricEvaluation:
    """
    Validate and return a metric evaluation.
    """

    if not isinstance(
        evaluation,
        GeometryMetricEvaluation,
    ):
        raise InvalidGeometryQualityError(
            "Expected a GeometryMetricEvaluation instance."
        )

    return evaluation


def validate_geometry_quality_resolution(
    resolution: GeometryQualityResolution,
) -> GeometryQualityResolution:
    """
    Validate and return a geometry-quality resolution.
    """

    if not isinstance(
        resolution,
        GeometryQualityResolution,
    ):
        raise InvalidGeometryQualityError(
            "Expected a GeometryQualityResolution instance."
        )

    for evaluation in resolution.evaluations:
        validate_geometry_metric_evaluation(
            evaluation
        )

    return resolution


# -----------------------------------------------------------------------------
# 10.17. Explainability
# -----------------------------------------------------------------------------

def explain_geometry_quality_resolution(
    resolution: GeometryQualityResolution,
) -> ScoreExplanation:
    """
    Create a structured explanation for geometry quality.
    """

    validate_geometry_quality_resolution(
        resolution
    )

    if resolution.status in {
        GEOMETRY_STATUS_RESOLVED,
        GEOMETRY_STATUS_INFERRED,
    }:
        severity = EXPLANATION_SEVERITY_SUCCESS
    elif resolution.status == GEOMETRY_STATUS_REJECTED:
        severity = EXPLANATION_SEVERITY_ERROR
    else:
        severity = EXPLANATION_SEVERITY_WARNING

    children = tuple(
        ScoreExplanation(
            explanation_id=(
                f"geometry_metric:{evaluation.metric}"
            ),
            title=(
                f"Geometry metric: {evaluation.metric}"
            ),
            message=evaluation.reason,
            scope=EXPLANATION_SCOPE_INTERACTION,
            severity=(
                EXPLANATION_SEVERITY_INFO
                if evaluation.available
                else EXPLANATION_SEVERITY_WARNING
            ),
            level=EXPLANATION_LEVEL_DETAILED,
            value=evaluation.score,
            reference_value=evaluation.value,
            entity_id=evaluation.metric,
            tags=(
                "geometry",
                "metric",
                evaluation.metric,
            ),
            metadata={
                "weight": evaluation.weight,
                "source": evaluation.source,
            },
        )
        for evaluation in resolution.evaluations
    )

    return ScoreExplanation(
        explanation_id=(
            f"geometry_quality:"
            f"{resolution.interaction_type}"
        ),
        title="Geometry quality",
        message=resolution.reason,
        scope=EXPLANATION_SCOPE_INTERACTION,
        severity=severity,
        level=EXPLANATION_LEVEL_STANDARD,
        value=resolution.multiplier,
        reference_value=NEUTRAL_MULTIPLIER,
        interaction_type=resolution.interaction_type,
        tags=(
            "geometry",
            resolution.quality,
            resolution.source,
            resolution.status,
        ),
        children=children,
        metadata={
            "geometry_score": resolution.score,
            "used_fallback": resolution.used_fallback,
        },
    )


# -----------------------------------------------------------------------------
# 10.18. Section consistency validation
# -----------------------------------------------------------------------------

def _validate_section_10_geometry_quality() -> None:
    """
    Validate geometry-quality behavior during module import.
    """

    distance_rule = GeometryMetricRule(
        metric=GEOMETRY_METRIC_DISTANCE,
        direction=GEOMETRY_DIRECTION_LOWER_IS_BETTER,
        ideal_value=3.0,
        limit_value=4.0,
    )

    if distance_rule.evaluate(2.8) != 1.0:
        raise RuntimeError(
            "Ideal distance evaluation failed."
        )

    if distance_rule.evaluate(4.0) != 0.0:
        raise RuntimeError(
            "Limit distance evaluation failed."
        )

    intermediate = distance_rule.evaluate(3.5)

    if (
        intermediate is None
        or abs(intermediate - 0.5)
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Intermediate distance evaluation failed."
        )

    profile = GeometryQualityProfile(
        multipliers={
            "ideal": 1.20,
            "good": 1.00,
            "acceptable": 0.85,
            "poor": 0.60,
            "unknown": 1.00,
        },
        rules_by_type={
            "hydrogen_bond": (
                GeometryMetricRule(
                    metric=GEOMETRY_METRIC_DISTANCE,
                    direction=(
                        GEOMETRY_DIRECTION_LOWER_IS_BETTER
                    ),
                    ideal_value=2.8,
                    limit_value=3.5,
                    weight=0.5,
                ),
                GeometryMetricRule(
                    metric=GEOMETRY_METRIC_ANGLE,
                    direction=(
                        GEOMETRY_DIRECTION_HIGHER_IS_BETTER
                    ),
                    ideal_value=170.0,
                    limit_value=120.0,
                    weight=0.5,
                ),
            ),
        },
    )

    data = ExtractedInteractionData(
        interaction_id="hbond_1",
        interaction_type="hydrogen_bond",
        interaction_family="hydrogen_bond",
        strength="strong",
        classification="conventional",
        geometry_quality="unknown",
        atom_pair=(
            "A:10:N",
            "L:1:O",
        ),
        residue_pair=(
            "A:10:LYS",
            "L:1:LIG",
        ),
        distance=2.8,
        angle=170.0,
    )

    resolution = resolve_geometry_quality(
        data,
        profile=profile,
    )

    if resolution.quality != GEOMETRY_IDEAL:
        raise RuntimeError(
            "Ideal geometry-quality classification failed."
        )

    if resolution.multiplier != 1.20:
        raise RuntimeError(
            "Ideal geometry multiplier validation failed."
        )

    score = interaction_score_with_geometry(
        data,
        base_weight_profile=BaseWeightProfile(
            interaction_weights={
                "hydrogen_bond": 2.0,
            },
            family_weights={},
        ),
        multiplier_profile=(
            InteractionMultiplierProfile(
                strength_multipliers={
                    "strong": 1.25,
                    "unknown": 1.0,
                },
                classification_multipliers={
                    "conventional": 1.0,
                    "unknown": 1.0,
                },
            )
        ),
        geometry_profile=profile,
    )

    expected_score = (
        2.0
        * 1.25
        * 1.0
        * 1.20
    )

    if (
        abs(score.raw_score - expected_score)
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Geometry-adjusted InteractionScore validation failed."
        )

    if score.penalty_score != 0.0:
        raise RuntimeError(
            "Penalties must remain zero in Section 10."
        )

    explanation = (
        explain_geometry_quality_resolution(
            resolution
        )
    )

    if explanation.scope != EXPLANATION_SCOPE_INTERACTION:
        raise RuntimeError(
            "Geometry explanation validation failed."
        )

    validate_geometry_metric_rule(
        distance_rule
    )
    validate_geometry_quality_profile(
        profile
    )
    validate_geometry_quality_resolution(
        resolution
    )


_validate_section_10_geometry_quality()


