def _score_steric_family(
    interaction: Any,
    context: FamilyScoringContext,
) -> FamilyScoreContribution:
    """
    Apply steric-family refinements.

    Clash scores are already expected to have negative base weights. A family
    multiplier above one therefore increases their unfavorable magnitude.
    """

    multiplier = 1.0
    penalty = 0.0
    reasons: List[str] = []

    if (
        context.distance is not None
        and context.distance < 2.0
    ):
        multiplier *= 1.40
        penalty += 0.50
        reasons.append(
            "Severe short-range steric clash."
        )

    elif (
        context.distance is not None
        and context.distance < 2.5
    ):
        multiplier *= 1.20
        penalty += 0.20
        reasons.append(
            "Moderate steric clash."
        )

    return FamilyScoreContribution(
        interaction_family=context.interaction_family,
        interaction_type=context.interaction_type,
        multiplier=multiplier,
        penalty=penalty,
        source=FAMILY_SCORING_SOURCE_RULE,
        status=(
            FAMILY_SCORING_STATUS_NEUTRAL
            if (
                abs(multiplier - 1.0)
                <= SCORE_COMPARISON_TOLERANCE
                and penalty <= SCORE_COMPARISON_TOLERANCE
            )
            else FAMILY_SCORING_STATUS_APPLIED
        ),
        rule_name="steric_family",
        reason=" ".join(reasons),
    )


def _score_contact_family(
    interaction: Any,
    context: FamilyScoringContext,
) -> FamilyScoreContribution:
    """
    Apply generic-contact refinements.
    """

    multiplier = 1.0
    penalty = 0.0
    reason = ""

    if (
        context.distance is not None
        and context.distance > 5.0
    ):
        multiplier = 0.75
        penalty = 0.05
        reason = "Weak long-range generic contact."

    return FamilyScoreContribution(
        interaction_family=context.interaction_family,
        interaction_type=context.interaction_type,
        multiplier=multiplier,
        penalty=penalty,
        source=FAMILY_SCORING_SOURCE_RULE,
        status=(
            FAMILY_SCORING_STATUS_NEUTRAL
            if (
                abs(multiplier - 1.0)
                <= SCORE_COMPARISON_TOLERANCE
                and penalty <= SCORE_COMPARISON_TOLERANCE
            )
            else FAMILY_SCORING_STATUS_APPLIED
        ),
        rule_name="contact_family",
        reason=reason,
    )


