DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE: Final[
    FamilyScoringProfile
] = FamilyScoringProfile(
    family_multipliers=DEFAULT_FAMILY_MULTIPLIERS,
    family_adjustments=DEFAULT_FAMILY_ADJUSTMENTS,
    rules=DEFAULT_FAMILY_SCORING_RULES,
)


# -----------------------------------------------------------------------------
# 11.13. ScoringConfig extraction
# -----------------------------------------------------------------------------

def extract_config_family_multipliers(
    scoring_config: Optional[ScoringConfig],
) -> Mapping[str, float]:
    """
    Extract family multipliers from ScoringConfig.
    """

    if scoring_config is None:
        return MappingProxyType({})

    if not isinstance(scoring_config, ScoringConfig):
        raise InvalidFamilyScoringRuleError(
            "scoring_config must be a ScoringConfig instance or None."
        )

    extracted = extract_named_value(
        scoring_config,
        (
            "family_multipliers",
            "interaction_family_multipliers",
            "family_score_multipliers",
        ),
        allow_none=False,
        call_methods=False,
    )

    if not extracted.found:
        return MappingProxyType({})

    return normalize_family_multiplier_mapping(
        extracted.value
    )


def extract_config_family_adjustments(
    scoring_config: Optional[ScoringConfig],
) -> Mapping[str, float]:
    """
    Extract additive family adjustments from ScoringConfig.
    """

    if scoring_config is None:
        return MappingProxyType({})

    if not isinstance(scoring_config, ScoringConfig):
        raise InvalidFamilyScoringRuleError(
            "scoring_config must be a ScoringConfig instance or None."
        )

    extracted = extract_named_value(
        scoring_config,
        (
            "family_adjustments",
            "interaction_family_adjustments",
            "family_score_adjustments",
        ),
        allow_none=False,
        call_methods=False,
    )

    if not extracted.found:
        return MappingProxyType({})

    return normalize_family_adjustment_mapping(
        extracted.value
    )


def family_scoring_profile_from_config(
    scoring_config: ScoringConfig,
    *,
    rules: Iterable[FamilyScoringRule] = (
        DEFAULT_FAMILY_SCORING_RULES
    ),
    strict: bool = False,
) -> FamilyScoringProfile:
    """
    Build a family-scoring profile from ScoringConfig.
    """

    family_multipliers = extract_config_family_multipliers(
        scoring_config
    )
    family_adjustments = extract_config_family_adjustments(
        scoring_config
    )

    if not family_multipliers:
        family_multipliers = DEFAULT_FAMILY_MULTIPLIERS

    if not family_adjustments:
        family_adjustments = DEFAULT_FAMILY_ADJUSTMENTS

    return FamilyScoringProfile(
        family_multipliers=family_multipliers,
        family_adjustments=family_adjustments,
        rules=tuple(rules),
        strict=strict,
        metadata={
            "source": object_type_name(
                scoring_config
            ),
        },
    )


# -----------------------------------------------------------------------------
# 11.14. Family contribution aggregation
# -----------------------------------------------------------------------------

def combine_family_score_contributions(
    contributions: Iterable[FamilyScoreContribution],
    *,
    interaction_type: Any,
    interaction_family: Any,
) -> FamilyScoreContribution:
    """
    Combine multiple family contributions deterministically.
    """

    canonical_type = normalize_interaction_type(
        interaction_type,
        preserve_unknown=True,
    )
    canonical_family = canonical_interaction_family(
        interaction_family
        or canonical_type
    )

    normalized = tuple(contributions)

    if not normalized:
        return FamilyScoreContribution(
            interaction_family=canonical_family,
            interaction_type=canonical_type,
            source=FAMILY_SCORING_SOURCE_FALLBACK,
            status=FAMILY_SCORING_STATUS_NEUTRAL,
            reason="No family-specific contribution was produced.",
        )

    multiplier = 1.0
    adjustment = 0.0
    bonus = 0.0
    penalty = 0.0

    rule_names: List[str] = []
    reasons: List[str] = []

    for contribution in normalized:
        validate_family_score_contribution(
            contribution
        )

        multiplier *= contribution.multiplier
        adjustment += contribution.adjustment
        bonus += contribution.bonus
        penalty += contribution.penalty

        if contribution.rule_name:
            rule_names.append(
                contribution.rule_name
            )

        if contribution.reason:
            reasons.append(
                contribution.reason
            )

    combined = FamilyScoreContribution(
        interaction_family=canonical_family,
        interaction_type=canonical_type,
        multiplier=multiplier,
        adjustment=adjustment,
        bonus=bonus,
        penalty=penalty,
        source=FAMILY_SCORING_SOURCE_RULE,
        status=FAMILY_SCORING_STATUS_APPLIED,
        rule_name="|".join(
            dict.fromkeys(rule_names)
        ),
        reason=" ".join(reasons),
        metadata={
            "contribution_count": len(normalized),
            "rule_names": tuple(
                dict.fromkeys(rule_names)
            ),
        },
    )

    if combined.neutral:
        return replace(
            combined,
            status=FAMILY_SCORING_STATUS_NEUTRAL,
        )

    return combined


# -----------------------------------------------------------------------------
# 11.15. Family-scoring resolution
# -----------------------------------------------------------------------------

def resolve_family_scoring(
    interaction: Any,
    *,
    context: Optional[FamilyScoringContext] = None,
    profile: FamilyScoringProfile = (
        DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    strict: Optional[bool] = None,
) -> FamilyScoreContribution:
    """
    Resolve family-specific scoring for one interaction.
    """

    if not isinstance(
        profile,
        FamilyScoringProfile,
    ):
        raise InvalidFamilyScoringRuleError(
            "profile must be a FamilyScoringProfile."
        )

    if context is None:
        if isinstance(interaction, InteractionScore):
            context = FamilyScoringContext.from_interaction_score(
                interaction
            )
        else:
            raise InvalidFamilyScoringRuleError(
                "A FamilyScoringContext is required when the source "
                "is not an InteractionScore."
            )

    strict_mode = (
        profile.strict
        if strict is None
        else bool(strict)
    )

    contributions: List[
        FamilyScoreContribution
    ] = []

    config_multipliers = extract_config_family_multipliers(
        scoring_config
    )
    config_adjustments = extract_config_family_adjustments(
        scoring_config
    )

    family = context.interaction_family

    if profile.apply_profile_values_before_rules:
        if family in config_multipliers:
            multiplier = config_multipliers[
                family
            ]
            multiplier_source = (
                FAMILY_SCORING_SOURCE_CONFIG
            )
        else:
            multiplier = profile.multiplier_for_family(
                family
            )
            multiplier_source = (
                FAMILY_SCORING_SOURCE_PROFILE
            )

        if family in config_adjustments:
            adjustment = config_adjustments[
                family
            ]
            adjustment_source = (
                FAMILY_SCORING_SOURCE_CONFIG
            )
        else:
            adjustment = profile.adjustment_for_family(
                family
            )
            adjustment_source = (
                FAMILY_SCORING_SOURCE_PROFILE
            )

        source = (
            FAMILY_SCORING_SOURCE_CONFIG
            if (
                multiplier_source
                == FAMILY_SCORING_SOURCE_CONFIG
                or adjustment_source
                == FAMILY_SCORING_SOURCE_CONFIG
            )
            else FAMILY_SCORING_SOURCE_PROFILE
        )

        contributions.append(
            FamilyScoreContribution(
                interaction_family=family,
                interaction_type=context.interaction_type,
                multiplier=multiplier,
                adjustment=adjustment,
                source=source,
                status=(
                    FAMILY_SCORING_STATUS_NEUTRAL
                    if (
                        abs(multiplier - 1.0)
                        <= SCORE_COMPARISON_TOLERANCE
                        and abs(adjustment)
                        <= SCORE_COMPARISON_TOLERANCE
                    )
                    else FAMILY_SCORING_STATUS_APPLIED
                ),
                rule_name="family_profile",
                reason=(
                    "Family-level profile values were applied."
                ),
            )
        )

    matched_rule = False

    for rule in profile.rules:
        contribution = rule.evaluate(
            interaction,
            context,
        )

        if contribution is None:
            continue

        matched_rule = True
        contributions.append(contribution)

        if rule.stop_after_match:
            break

    if (
        not matched_rule
        and not contributions
        and strict_mode
    ):
        raise UnknownInteractionFamilyScoringError(
            f"No family scoring rule is available for "
            f"{context.interaction_family!r}."
        )

    return combine_family_score_contributions(
        contributions,
        interaction_type=context.interaction_type,
        interaction_family=context.interaction_family,
    )


def resolve_family_scoring_collection(
    scores: Iterable[InteractionScore],
    *,
    profile: FamilyScoringProfile = (
        DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    strict: Optional[bool] = None,
    skip_errors: bool = False,
) -> Tuple[FamilyScoreContribution, ...]:
    """
    Resolve family scoring for an InteractionScore collection.
    """

    results: List[
        FamilyScoreContribution
    ] = []

    for score in scores:
        try:
            result = resolve_family_scoring(
                score,
                profile=profile,
                scoring_config=scoring_config,
                strict=strict,
            )
        except (
            ScoringError,
            TypeError,
            ValueError,
            AttributeError,
        ):
            if skip_errors:
                continue

            raise

        results.append(result)

    return tuple(results)


# -----------------------------------------------------------------------------
# 11.16. InteractionScore integration
# -----------------------------------------------------------------------------

def apply_family_scoring_to_score(
    score: InteractionScore,
    *,
    profile: FamilyScoringProfile = (
        DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    strict: Optional[bool] = None,
) -> InteractionScore:
    """
    Apply family-specific scoring to an InteractionScore.

    Family bonus and penalty are stored separately so that later generic
    penalty and bonus sections can preserve a complete audit trail.
    """

    validate_interaction_score(
        score,
        validate_consistency=False,
    )

    context = FamilyScoringContext.from_interaction_score(
        score
    )

    contribution = resolve_family_scoring(
        score,
        context=context,
        profile=profile,
        scoring_config=scoring_config,
        strict=strict,
    )

    family_adjusted_raw_score = float(
        score.raw_score
        * contribution.multiplier
        + contribution.adjustment
    )

    penalty_score = float(
        score.penalty_score
        + contribution.penalty
    )
    bonus_score = float(
        score.bonus_score
        + contribution.bonus
    )

    final_score = float(
        family_adjusted_raw_score
        + bonus_score
        - penalty_score
    )

    metadata = dict(score.metadata)
    metadata["family_scoring"] = (
        contribution.to_dict(
            include_metadata=True
        )
    )
    metadata["pre_family_raw_score"] = (
        score.raw_score
    )
    metadata["family_adjusted_raw_score"] = (
        family_adjusted_raw_score
    )

    existing_components = tuple(
        component
        for component in score.components
        if component.component_type
        not in FAMILY_COMPONENT_TYPES
    )

    components = (
        existing_components
        + contribution.to_components()
    )

    return replace(
        score,
        raw_score=family_adjusted_raw_score,
        penalty_score=penalty_score,
        bonus_score=bonus_score,
        final_score=final_score,
        components=components,
        metadata=metadata,
    )


def interaction_score_with_family_scoring(
    data: ExtractedInteractionData,
    *,
    base_weight_profile: BaseWeightProfile = (
        DEFAULT_BASE_WEIGHT_PROFILE
    ),
    multiplier_profile: InteractionMultiplierProfile = (
        DEFAULT_INTERACTION_MULTIPLIER_PROFILE
    ),
    geometry_profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    family_profile: FamilyScoringProfile = (
        DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    weight_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strength_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    classification_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strict_weights: Optional[bool] = None,
    strict_strength: Optional[bool] = None,
    strict_classification: Optional[bool] = None,
    strict_geometry: Optional[bool] = None,
    strict_family: Optional[bool] = None,
    preserve_components: bool = True,
) -> InteractionScore:
    """
    Build a score through geometry and then apply family-specific scoring.
    """

    score = interaction_score_with_geometry(
        data,
        base_weight_profile=base_weight_profile,
        multiplier_profile=multiplier_profile,
        geometry_profile=geometry_profile,
        scoring_config=scoring_config,
        weight_overrides=weight_overrides,
        strength_overrides=strength_overrides,
        classification_overrides=(
            classification_overrides
        ),
        strict_weights=strict_weights,
        strict_strength=strict_strength,
        strict_classification=(
            strict_classification
        ),
        strict_geometry=strict_geometry,
        preserve_components=preserve_components,
    )

    return apply_family_scoring_to_score(
        score,
        profile=family_profile,
        scoring_config=scoring_config,
        strict=strict_family,
    )


def interactions_with_family_scoring(
    interactions: Iterable[ExtractedInteractionData],
    *,
    base_weight_profile: BaseWeightProfile = (
        DEFAULT_BASE_WEIGHT_PROFILE
    ),
    multiplier_profile: InteractionMultiplierProfile = (
        DEFAULT_INTERACTION_MULTIPLIER_PROFILE
    ),
    geometry_profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    family_profile: FamilyScoringProfile = (
        DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    weight_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strength_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    classification_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strict_weights: Optional[bool] = None,
    strict_strength: Optional[bool] = None,
    strict_classification: Optional[bool] = None,
    strict_geometry: Optional[bool] = None,
    strict_family: Optional[bool] = None,
    preserve_components: bool = True,
    skip_errors: bool = False,
) -> Tuple[InteractionScore, ...]:
    """
    Score extracted interactions with family-specific adjustments.
    """

    scores: List[InteractionScore] = []

    for interaction in interactions:
        try:
            score = interaction_score_with_family_scoring(
                interaction,
                base_weight_profile=base_weight_profile,
                multiplier_profile=multiplier_profile,
                geometry_profile=geometry_profile,
                family_profile=family_profile,
                scoring_config=scoring_config,
                weight_overrides=weight_overrides,
                strength_overrides=strength_overrides,
                classification_overrides=(
                    classification_overrides
                ),
                strict_weights=strict_weights,
                strict_strength=strict_strength,
                strict_classification=(
                    strict_classification
                ),
                strict_geometry=strict_geometry,
                strict_family=strict_family,
                preserve_components=preserve_components,
            )
        except (
            ScoringError,
            TypeError,
            ValueError,
            AttributeError,
        ):
            if skip_errors:
                continue

            raise

        scores.append(score)

    return sort_interaction_scores(scores)


def extract_recognize_and_apply_family_scoring(
    source: Any,
    *,
    container_name: Optional[str] = None,
    pose_id: Optional[str] = None,
    model_id: Optional[str] = None,
    ligand_id: Optional[str] = None,
    recognition_config: InteractionRecognitionConfig = (
        DEFAULT_INTERACTION_RECOGNITION_CONFIG
    ),
    recognition_rules: Iterable[
        InteractionRecognitionRule
    ] = (),
    base_weight_profile: BaseWeightProfile = (
        DEFAULT_BASE_WEIGHT_PROFILE
    ),
    multiplier_profile: InteractionMultiplierProfile = (
        DEFAULT_INTERACTION_MULTIPLIER_PROFILE
    ),
    geometry_profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    family_profile: FamilyScoringProfile = (
        DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    preserve_references: bool = True,
    skip_errors: bool = False,
) -> Tuple[InteractionScore, ...]:
    """
    Run extraction, recognition and scoring through the family stage.
    """

    extracted = extract_and_recognize_interactions(
        source,
        container_name=container_name,
        pose_id=pose_id,
        model_id=model_id,
        ligand_id=ligand_id,
        config=recognition_config,
        custom_rules=recognition_rules,
        preserve_references=preserve_references,
        skip_errors=skip_errors,
    )

    return interactions_with_family_scoring(
        extracted,
        base_weight_profile=base_weight_profile,
        multiplier_profile=multiplier_profile,
        geometry_profile=geometry_profile,
        family_profile=family_profile,
        scoring_config=scoring_config,
        skip_errors=skip_errors,
    )


# -----------------------------------------------------------------------------
# 11.17. Grouping and summaries
# -----------------------------------------------------------------------------

def group_scores_by_interaction_family(
    scores: Iterable[InteractionScore],
) -> Mapping[str, Tuple[InteractionScore, ...]]:
    """
    Group InteractionScore objects by canonical family.
    """

    grouped: Dict[str, List[InteractionScore]] = {}

    for score in scores:
        validate_interaction_score(
            score,
            validate_consistency=False,
        )

        grouped.setdefault(
            score.interaction_family,
            [],
        ).append(score)

    return MappingProxyType(
        {
            family: tuple(
                sort_interaction_scores(
                    family_scores
                )
            )
            for family, family_scores
            in sorted(grouped.items())
        }
    )


def summarize_family_scoring(
    scores: Iterable[InteractionScore],
) -> Mapping[str, Any]:
    """
    Summarize scores by interaction family.
    """

    grouped = group_scores_by_interaction_family(
        scores
    )

    summary: Dict[str, Mapping[str, Any]] = {}

    for family, family_scores in grouped.items():
        raw_total = sum(
            score.raw_score
            for score in family_scores
        )
        final_total = sum(
            score.final_score
            for score in family_scores
        )
        penalty_total = sum(
            score.penalty_score
            for score in family_scores
        )
        bonus_total = sum(
            score.bonus_score
            for score in family_scores
        )

        summary[family] = MappingProxyType(
            {
                "interaction_count": len(
                    family_scores
                ),
                "raw_score": float(raw_total),
                "final_score": float(final_total),
                "penalty_score": float(
                    penalty_total
                ),
                "bonus_score": float(
                    bonus_total
                ),
                "mean_final_score": (
                    0.0
                    if not family_scores
                    else float(
                        final_total
                        / len(family_scores)
                    )
                ),
                "interaction_types": tuple(
                    sorted(
                        {
                            score.interaction_type
                            for score in family_scores
                        }
                    )
                ),
            }
        )

    return MappingProxyType(summary)


def family_score_totals(
    scores: Iterable[InteractionScore],
) -> Mapping[str, float]:
    """
    Return final score totals by family.
    """

    summary = summarize_family_scoring(
        scores
    )

    return MappingProxyType(
        {
            family: float(
                values["final_score"]
            )
            for family, values
            in summary.items()
        }
    )


# -----------------------------------------------------------------------------
# 11.18. Validation
# -----------------------------------------------------------------------------

def validate_family_scoring_context(
    context: FamilyScoringContext,
) -> FamilyScoringContext:
    """
    Validate and return a family-scoring context.
    """

    if not isinstance(
        context,
        FamilyScoringContext,
    ):
        raise InvalidFamilyScoringRuleError(
            "Expected a FamilyScoringContext instance."
        )

    return context


def validate_family_score_contribution(
    contribution: FamilyScoreContribution,
) -> FamilyScoreContribution:
    """
    Validate and return a family contribution.
    """

    if not isinstance(
        contribution,
        FamilyScoreContribution,
    ):
        raise InvalidFamilyScoringRuleError(
            "Expected a FamilyScoreContribution instance."
        )

    return contribution


def validate_family_scoring_rule(
    rule: FamilyScoringRule,
) -> FamilyScoringRule:
    """
    Validate and return a family-scoring rule.
    """

    if not isinstance(
        rule,
        FamilyScoringRule,
    ):
        raise InvalidFamilyScoringRuleError(
            "Expected a FamilyScoringRule instance."
        )

    return rule


def validate_family_scoring_profile(
    profile: FamilyScoringProfile,
) -> FamilyScoringProfile:
    """
    Validate and return a family-scoring profile.
    """

    if not isinstance(
        profile,
        FamilyScoringProfile,
    ):
        raise InvalidFamilyScoringRuleError(
            "Expected a FamilyScoringProfile instance."
        )

    normalize_family_multiplier_mapping(
        profile.family_multipliers
    )
    normalize_family_adjustment_mapping(
        profile.family_adjustments
    )

    for rule in profile.rules:
        validate_family_scoring_rule(rule)

    return profile


# -----------------------------------------------------------------------------
# 11.19. Explainability
# -----------------------------------------------------------------------------

def explain_family_score_contribution(
    contribution: FamilyScoreContribution,
    *,
    input_score: Optional[Number] = None,
) -> ScoreExplanation:
    """
    Create a structured explanation for family-specific scoring.
    """

    validate_family_score_contribution(
        contribution
    )

    value: Optional[float]

    if input_score is None:
        value = None
        output_score = None
        delta = None
    else:
        normalized_input = float(
            _coerce_finite_score_value(
                input_score,
                name="family explanation input score",
            )
        )
        output_score = contribution.apply(
            normalized_input
        )
        delta = output_score - normalized_input
        value = output_score

    if contribution.status == FAMILY_SCORING_STATUS_APPLIED:
        severity = EXPLANATION_SEVERITY_SUCCESS
    elif contribution.status == FAMILY_SCORING_STATUS_REJECTED:
        severity = EXPLANATION_SEVERITY_ERROR
    elif contribution.status == FAMILY_SCORING_STATUS_NEUTRAL:
        severity = EXPLANATION_SEVERITY_INFO
    else:
        severity = EXPLANATION_SEVERITY_WARNING

    children: List[ScoreExplanation] = []

    children.append(
        ScoreExplanation(
            explanation_id=(
                "family_multiplier:"
                f"{contribution.interaction_family}"
            ),
            title="Family multiplier",
            message=contribution.reason,
            scope=EXPLANATION_SCOPE_INTERACTION,
            severity=EXPLANATION_SEVERITY_INFO,
            level=EXPLANATION_LEVEL_DETAILED,
            value=contribution.multiplier,
            reference_value=NEUTRAL_MULTIPLIER,
            interaction_type=contribution.interaction_type,
            tags=(
                "family_scoring",
                "multiplier",
                contribution.interaction_family,
            ),
        )
    )

    if abs(contribution.adjustment) > SCORE_COMPARISON_TOLERANCE:
        children.append(
            ScoreExplanation(
                explanation_id=(
                    "family_adjustment:"
                    f"{contribution.interaction_family}"
                ),
                title="Family additive adjustment",
                message=contribution.reason,
                scope=EXPLANATION_SCOPE_INTERACTION,
                severity=EXPLANATION_SEVERITY_INFO,
                level=EXPLANATION_LEVEL_DETAILED,
                value=contribution.adjustment,
                reference_value=0.0,
                interaction_type=contribution.interaction_type,
                tags=(
                    "family_scoring",
                    "adjustment",
                    contribution.interaction_family,
                ),
            )
        )

    if contribution.bonus > SCORE_COMPARISON_TOLERANCE:
        children.append(
            ScoreExplanation(
                explanation_id=(
                    "family_bonus:"
                    f"{contribution.interaction_family}"
                ),
                title="Family bonus",
                message=contribution.reason,
                scope=EXPLANATION_SCOPE_INTERACTION,
                severity=EXPLANATION_SEVERITY_SUCCESS,
                level=EXPLANATION_LEVEL_DETAILED,
                value=contribution.bonus,
                reference_value=0.0,
                interaction_type=contribution.interaction_type,
                tags=(
                    "family_scoring",
                    "bonus",
                    contribution.interaction_family,
                ),
            )
        )

    if contribution.penalty > SCORE_COMPARISON_TOLERANCE:
        children.append(
            ScoreExplanation(
                explanation_id=(
                    "family_penalty:"
                    f"{contribution.interaction_family}"
                ),
                title="Family penalty",
                message=contribution.reason,
                scope=EXPLANATION_SCOPE_INTERACTION,
                severity=EXPLANATION_SEVERITY_WARNING,
                level=EXPLANATION_LEVEL_DETAILED,
                value=contribution.penalty,
                reference_value=0.0,
                interaction_type=contribution.interaction_type,
                tags=(
                    "family_scoring",
                    "penalty",
                    contribution.interaction_family,
                ),
            )
        )

    return ScoreExplanation(
        explanation_id=(
            "family_scoring:"
            f"{contribution.interaction_family}:"
            f"{contribution.interaction_type}"
        ),
        title=(
            "Family-specific scoring: "
            f"{contribution.interaction_family}"
        ),
        message=contribution.reason,
        scope=EXPLANATION_SCOPE_INTERACTION,
        severity=severity,
        level=EXPLANATION_LEVEL_STANDARD,
        value=value,
        reference_value=(
            None
            if input_score is None
            else float(input_score)
        ),
        interaction_type=contribution.interaction_type,
        tags=(
            "family_scoring",
            contribution.interaction_family,
            contribution.status,
            contribution.rule_name,
        ),
        children=tuple(children),
        metadata={
            "rule_name": contribution.rule_name,
            "source": contribution.source,
            "score_delta": delta,
            "output_score": output_score,
        },
    )


# -----------------------------------------------------------------------------
# 11.20. Section consistency validation
# -----------------------------------------------------------------------------

def _validate_section_11_family_scoring() -> None:
    """
    Validate family-specific scoring behavior during import.
    """

    profile = DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE

    hydrogen_bond_data = ExtractedInteractionData(
        interaction_id="hbond_1",
        interaction_type="hydrogen_bond",
        interaction_family="hydrogen_bond",
        strength="strong",
        classification="charge_assisted",
        geometry_quality="ideal",
        atom_pair=(
            "A:10:N",
            "L:1:O",
        ),
        residue_pair=(
            "A:10:LYS",
            "L:1:LIG",
        ),
        distance=2.6,
        angle=172.0,
    )

    base_score = interaction_score_with_geometry(
        hydrogen_bond_data,
        base_weight_profile=BaseWeightProfile(
            interaction_weights={
                "hydrogen_bond": 2.0,
            },
            family_weights={},
        ),
        multiplier_profile=InteractionMultiplierProfile(
            strength_multipliers={
                "strong": 1.25,
                "unknown": 1.0,
            },
            classification_multipliers={
                "charge_assisted": 1.20,
                "unknown": 1.0,
            },
        ),
        geometry_profile=GeometryQualityProfile(
            multipliers={
                "ideal": 1.20,
                "good": 1.0,
                "acceptable": 0.85,
                "poor": 0.60,
                "unknown": 1.0,
            },
            rules_by_type={},
            trust_explicit_quality=True,
        ),
    )

    family_score = apply_family_scoring_to_score(
        base_score,
        profile=profile,
    )

    if family_score.final_score <= base_score.final_score:
        raise RuntimeError(
            "Hydrogen-bond family scoring validation failed."
        )

    contribution_data = family_score.metadata.get(
        "family_scoring"
    )

    if not isinstance(
        contribution_data,
        Mapping,
    ):
        raise RuntimeError(
            "Family scoring metadata validation failed."
        )

    clash_data = ExtractedInteractionData(
        interaction_id="clash_1",
        interaction_type="clash",
        interaction_family="steric",
        strength="strong",
        classification="conventional",
        geometry_quality="poor",
        distance=1.8,
    )

    clash_score = interaction_score_with_family_scoring(
        clash_data,
        base_weight_profile=BaseWeightProfile(
            interaction_weights={
                "clash": -2.0,
            },
            family_weights={},
        ),
        multiplier_profile=InteractionMultiplierProfile(
            strength_multipliers={
                "strong": 1.0,
                "unknown": 1.0,
            },
            classification_multipliers={
                "conventional": 1.0,
                "unknown": 1.0,
            },
        ),
        geometry_profile=GeometryQualityProfile(
            multipliers={
                "poor": 1.0,
                "unknown": 1.0,
            },
            rules_by_type={},
            trust_explicit_quality=True,
        ),
        family_profile=profile,
    )

    if clash_score.final_score >= -2.0:
        raise RuntimeError(
            "Steric family scoring validation failed."
        )

    context = FamilyScoringContext.from_interaction_score(
        base_score
    )

    contribution = resolve_family_scoring(
        base_score,
        context=context,
        profile=profile,
    )

    explanation = explain_family_score_contribution(
        contribution,
        input_score=base_score.raw_score,
    )

    if explanation.scope != EXPLANATION_SCOPE_INTERACTION:
        raise RuntimeError(
            "Family scoring explanation validation failed."
        )

    validate_family_scoring_context(context)
    validate_family_score_contribution(
        contribution
    )
    validate_family_scoring_profile(profile)


_validate_section_11_family_scoring()


