def normalize_individual_scoring_status(
    value: Any,
    *,
    default: str = INDIVIDUAL_SCORING_STATUS_FAILED,
) -> str:
    """
    Normalize an individual-scoring status.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in INDIVIDUAL_SCORING_STATUSES:
        return normalized

    return _INDIVIDUAL_SCORING_STATUS_ALIASES.get(
        normalized,
        default,
    )


def normalize_individual_scoring_source(
    value: Any,
    *,
    default: str = INDIVIDUAL_SCORING_SOURCE_UNKNOWN,
) -> str:
    """
    Normalize the source type used for individual scoring.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in INDIVIDUAL_SCORING_SOURCES:
        return normalized

    return _INDIVIDUAL_SCORING_SOURCE_ALIASES.get(
        normalized,
        default,
    )


def normalize_individual_scoring_stage(
    value: Any,
    *,
    default: str = INDIVIDUAL_SCORING_STAGE_COMPLETE,
) -> str:
    """
    Normalize an individual-scoring stage.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in INDIVIDUAL_SCORING_STAGES:
        return normalized

    return default


# -----------------------------------------------------------------------------
# 13.3. Exceptions
# -----------------------------------------------------------------------------

class IndividualScoringError(ScoringError):
    """
    Base exception for individual interaction scoring.
    """


class IndividualScoringInputError(IndividualScoringError):
    """
    Raised when the individual scoring input is unsupported.
    """


class IndividualScoringPipelineError(IndividualScoringError):
    """
    Raised when an individual scoring pipeline stage fails.
    """


class IndividualScoringValidationError(IndividualScoringError):
    """
    Raised when the final individual score is inconsistent.
    """


class IndividualScoringRejectedError(IndividualScoringError):
    """
    Raised when an interaction is rejected by the scoring policy.
    """


# -----------------------------------------------------------------------------
# 13.4. IndividualScoringOptions
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class IndividualScoringOptions:
    """
    Immutable options controlling individual interaction scoring.
    """

    strict: bool = DEFAULT_INDIVIDUAL_SCORING_STRICT

    strict_weights: Optional[bool] = None
    strict_strength: Optional[bool] = None
    strict_classification: Optional[bool] = None
    strict_geometry: Optional[bool] = None
    strict_family: Optional[bool] = None
    strict_adjustments: Optional[bool] = None

    preserve_references: bool = (
        DEFAULT_INDIVIDUAL_SCORING_PRESERVE_REFERENCES
    )
    preserve_components: bool = (
        DEFAULT_INDIVIDUAL_SCORING_PRESERVE_COMPONENTS
    )
    validate_result: bool = (
        DEFAULT_INDIVIDUAL_SCORING_VALIDATE_RESULT
    )

    recognize_interaction: bool = True
    apply_family_scoring: bool = True
    apply_adjustments: bool = True

    allow_unknown_type: bool = True
    allow_unknown_family: bool = True
    allow_neutral_score: bool = True

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize option values.
        """

        boolean_fields = (
            "strict",
            "preserve_references",
            "preserve_components",
            "validate_result",
            "recognize_interaction",
            "apply_family_scoring",
            "apply_adjustments",
            "allow_unknown_type",
            "allow_unknown_family",
            "allow_neutral_score",
        )

        for field_name in boolean_fields:
            object.__setattr__(
                self,
                field_name,
                bool(getattr(self, field_name)),
            )

        optional_boolean_fields = (
            "strict_weights",
            "strict_strength",
            "strict_classification",
            "strict_geometry",
            "strict_family",
            "strict_adjustments",
        )

        for field_name in optional_boolean_fields:
            value = getattr(self, field_name)

            object.__setattr__(
                self,
                field_name,
                (
                    None
                    if value is None
                    else bool(value)
                ),
            )

        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def strict_for(
        self,
        stage: str,
    ) -> bool:
        """
        Return the effective strict flag for one scoring stage.
        """

        normalized_stage = normalize_individual_scoring_stage(
            stage
        )

        field_by_stage = {
            INDIVIDUAL_SCORING_STAGE_BASE_WEIGHT: (
                "strict_weights"
            ),
            INDIVIDUAL_SCORING_STAGE_MULTIPLIERS: (
                "strict_strength"
            ),
            INDIVIDUAL_SCORING_STAGE_GEOMETRY: (
                "strict_geometry"
            ),
            INDIVIDUAL_SCORING_STAGE_FAMILY: (
                "strict_family"
            ),
            INDIVIDUAL_SCORING_STAGE_ADJUSTMENTS: (
                "strict_adjustments"
            ),
        }

        field_name = field_by_stage.get(
            normalized_stage
        )

        if field_name is None:
            return self.strict

        value = getattr(self, field_name)

        return (
            self.strict
            if value is None
            else bool(value)
        )

    def with_updates(
        self,
        **changes: Any,
    ) -> "IndividualScoringOptions":
        """
        Return a validated options copy.
        """

        return replace(
            self,
            **changes,
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "strict": bool(self.strict),
            "strict_weights": self.strict_weights,
            "strict_strength": self.strict_strength,
            "strict_classification": (
                self.strict_classification
            ),
            "strict_geometry": self.strict_geometry,
            "strict_family": self.strict_family,
            "strict_adjustments": self.strict_adjustments,
            "preserve_references": bool(
                self.preserve_references
            ),
            "preserve_components": bool(
                self.preserve_components
            ),
            "validate_result": bool(
                self.validate_result
            ),
            "recognize_interaction": bool(
                self.recognize_interaction
            ),
            "apply_family_scoring": bool(
                self.apply_family_scoring
            ),
            "apply_adjustments": bool(
                self.apply_adjustments
            ),
            "allow_unknown_type": bool(
                self.allow_unknown_type
            ),
            "allow_unknown_family": bool(
                self.allow_unknown_family
            ),
            "allow_neutral_score": bool(
                self.allow_neutral_score
            ),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


DEFAULT_INDIVIDUAL_SCORING_OPTIONS: Final[
    IndividualScoringOptions
] = IndividualScoringOptions()


# -----------------------------------------------------------------------------
# 13.5. IndividualScoringProfile
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class IndividualScoringProfile:
    """
    Complete immutable profile for scoring one interaction.
    """

    recognition_config: InteractionRecognitionConfig = (
        DEFAULT_INTERACTION_RECOGNITION_CONFIG
    )
    recognition_rules: Tuple[
        InteractionRecognitionRule,
        ...,
    ] = field(default_factory=tuple)

    base_weight_profile: BaseWeightProfile = (
        DEFAULT_BASE_WEIGHT_PROFILE
    )
    multiplier_profile: InteractionMultiplierProfile = (
        DEFAULT_INTERACTION_MULTIPLIER_PROFILE
    )
    geometry_profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    )
    family_profile: FamilyScoringProfile = (
        DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE
    )
    adjustment_profile: ScoreAdjustmentProfile = (
        DEFAULT_SCORE_ADJUSTMENT_PROFILE
    )

    scoring_config: Optional[ScoringConfig] = None
    options: IndividualScoringOptions = (
        DEFAULT_INDIVIDUAL_SCORING_OPTIONS
    )

    weight_overrides: Mapping[str, float] = field(
        default_factory=lambda: MappingProxyType({})
    )
    strength_overrides: Mapping[str, float] = field(
        default_factory=lambda: MappingProxyType({})
    )
    classification_overrides: Mapping[str, float] = field(
        default_factory=lambda: MappingProxyType({})
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize and validate all subprofiles.
        """

        if not isinstance(
            self.recognition_config,
            InteractionRecognitionConfig,
        ):
            raise IndividualScoringInputError(
                "recognition_config must be an "
                "InteractionRecognitionConfig."
            )

        rules: List[
            InteractionRecognitionRule
        ] = []

        for rule in self.recognition_rules:
            if not isinstance(
                rule,
                InteractionRecognitionRule,
            ):
                raise IndividualScoringInputError(
                    "recognition_rules must contain only "
                    "InteractionRecognitionRule instances."
                )

            rules.append(rule)

        validate_base_weight_profile(
            self.base_weight_profile
        )
        validate_interaction_multiplier_profile(
            self.multiplier_profile
        )
        validate_geometry_quality_profile(
            self.geometry_profile
        )
        validate_family_scoring_profile(
            self.family_profile
        )
        validate_score_adjustment_profile(
            self.adjustment_profile
        )

        if not isinstance(
            self.options,
            IndividualScoringOptions,
        ):
            raise IndividualScoringInputError(
                "options must be an IndividualScoringOptions instance."
            )

        weight_overrides = normalize_base_weight_mapping(
            self.weight_overrides,
            allow_zero=True,
        )
        strength_overrides = (
            normalize_strength_multiplier_mapping(
                self.strength_overrides
            )
        )
        classification_overrides = (
            normalize_classification_multiplier_mapping(
                self.classification_overrides
            )
        )

        object.__setattr__(
            self,
            "recognition_rules",
            tuple(rules),
        )
        object.__setattr__(
            self,
            "weight_overrides",
            weight_overrides,
        )
        object.__setattr__(
            self,
            "strength_overrides",
            strength_overrides,
        )
        object.__setattr__(
            self,
            "classification_overrides",
            classification_overrides,
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def with_updates(
        self,
        **changes: Any,
    ) -> "IndividualScoringProfile":
        """
        Return a validated profile copy.
        """

        return replace(
            self,
            **changes,
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable profile representation.
        """

        result: Dict[str, Any] = {
            "recognition_config": (
                self.recognition_config.to_dict()
                if hasattr(
                    self.recognition_config,
                    "to_dict",
                )
                else {
                    "type": object_type_name(
                        self.recognition_config
                    )
                }
            ),
            "recognition_rules": [
                (
                    rule.to_dict()
                    if hasattr(rule, "to_dict")
                    else {
                        "name": getattr(
                            rule,
                            "name",
                            object_type_name(rule),
                        )
                    }
                )
                for rule in self.recognition_rules
            ],
            "base_weight_profile": (
                self.base_weight_profile.to_dict(
                    include_metadata=include_metadata
                )
            ),
            "multiplier_profile": (
                self.multiplier_profile.to_dict(
                    include_metadata=include_metadata
                )
            ),
            "geometry_profile": (
                self.geometry_profile.to_dict(
                    include_metadata=include_metadata
                )
            ),
            "family_profile": (
                self.family_profile.to_dict(
                    include_metadata=include_metadata
                )
            ),
            "adjustment_profile": (
                self.adjustment_profile.to_dict(
                    include_metadata=include_metadata
                )
            ),
            "scoring_config": (
                None
                if self.scoring_config is None
                else {
                    "type": object_type_name(
                        self.scoring_config
                    )
                }
            ),
            "options": self.options.to_dict(
                include_metadata=include_metadata
            ),
            "weight_overrides": dict(
                self.weight_overrides
            ),
            "strength_overrides": dict(
                self.strength_overrides
            ),
            "classification_overrides": dict(
                self.classification_overrides
            ),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


DEFAULT_INDIVIDUAL_SCORING_PROFILE: Final[
    IndividualScoringProfile
] = IndividualScoringProfile()


# -----------------------------------------------------------------------------
# 13.6. IndividualScoringTrace
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class IndividualScoringTrace:
    """
    Immutable trace of one individual scoring pipeline.
    """

    completed_stages: Tuple[str, ...] = field(
        default_factory=tuple
    )
    failed_stage: Optional[str] = None

    warnings: Tuple[str, ...] = field(
        default_factory=tuple
    )
    errors: Tuple[str, ...] = field(
        default_factory=tuple
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize trace values.
        """

        completed: List[str] = []

        for stage in self.completed_stages:
            normalized = normalize_individual_scoring_stage(
                stage
            )

            if normalized not in completed:
                completed.append(normalized)

        failed_stage = (
            None
            if self.failed_stage is None
            else normalize_individual_scoring_stage(
                self.failed_stage
            )
        )

        warnings = tuple(
            _coerce_optional_text(value)
            for value in self.warnings
            if _coerce_optional_text(value)
        )
        errors = tuple(
            _coerce_optional_text(value)
            for value in self.errors
            if _coerce_optional_text(value)
        )

        object.__setattr__(
            self,
            "completed_stages",
            tuple(completed),
        )
        object.__setattr__(
            self,
            "failed_stage",
            failed_stage,
        )
        object.__setattr__(
            self,
            "warnings",
            warnings,
        )
        object.__setattr__(
            self,
            "errors",
            errors,
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def complete(self) -> bool:
        """
        Return whether the pipeline completed successfully.
        """

        return (
            self.failed_stage is None
            and INDIVIDUAL_SCORING_STAGE_COMPLETE
            in self.completed_stages
        )

    def with_completed_stage(
        self,
        stage: str,
    ) -> "IndividualScoringTrace":
        """
        Return a trace with one completed stage appended.
        """

        normalized = normalize_individual_scoring_stage(
            stage
        )

        if normalized in self.completed_stages:
            return self

        return replace(
            self,
            completed_stages=(
                self.completed_stages
                + (normalized,)
            ),
        )

    def with_warning(
        self,
        message: str,
    ) -> "IndividualScoringTrace":
        """
        Return a trace with one warning appended.
        """

        normalized = _coerce_optional_text(
            message
        )

        if not normalized:
            return self

        return replace(
            self,
            warnings=self.warnings + (normalized,),
        )

    def with_failure(
        self,
        stage: str,
        message: str,
    ) -> "IndividualScoringTrace":
        """
        Return a trace containing one pipeline failure.
        """

        normalized_message = _coerce_optional_text(
            message
        )

        return replace(
            self,
            failed_stage=normalize_individual_scoring_stage(
                stage
            ),
            errors=(
                self.errors
                + (
                    normalized_message
                    or "Individual scoring failed.",
                )
            ),
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "completed_stages": list(
                self.completed_stages
            ),
            "failed_stage": self.failed_stage,
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "complete": bool(self.complete),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 13.7. IndividualScoringResult
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class IndividualScoringResult:
    """
    Final result of scoring one interaction.
    """

    status: str
    source: str

    score: Optional[InteractionScore] = None
    extracted_data: Optional[
        ExtractedInteractionData
    ] = None

    trace: IndividualScoringTrace = field(
        default_factory=IndividualScoringTrace
    )

    message: str = ""

    interaction: Any = field(
        default=None,
        compare=False,
        hash=False,
        repr=False,
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize and validate the result.
        """

        status = normalize_individual_scoring_status(
            self.status
        )
        source = normalize_individual_scoring_source(
            self.source
        )

        if (
            self.score is not None
            and not isinstance(
                self.score,
                InteractionScore,
            )
        ):
            raise IndividualScoringValidationError(
                "score must be an InteractionScore or None."
            )

        if (
            self.extracted_data is not None
            and not isinstance(
                self.extracted_data,
                ExtractedInteractionData,
            )
        ):
            raise IndividualScoringValidationError(
                "extracted_data must be an "
                "ExtractedInteractionData instance or None."
            )

        if not isinstance(
            self.trace,
            IndividualScoringTrace,
        ):
            raise IndividualScoringValidationError(
                "trace must be an IndividualScoringTrace."
            )

        if (
            status == INDIVIDUAL_SCORING_STATUS_SCORED
            and self.score is None
        ):
            raise IndividualScoringValidationError(
                "A scored result must contain an InteractionScore."
            )

        object.__setattr__(
            self,
            "status",
            status,
        )
        object.__setattr__(
            self,
            "source",
            source,
        )
        object.__setattr__(
            self,
            "message",
            _coerce_optional_text(self.message),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def successful(self) -> bool:
        """
        Return whether a usable score is available.
        """

        return (
            self.status
            in {
                INDIVIDUAL_SCORING_STATUS_SCORED,
                INDIVIDUAL_SCORING_STATUS_PARTIAL,
            }
            and self.score is not None
        )

    @property
    def final_score(self) -> Optional[float]:
        """
        Return the final numerical score.
        """

        return (
            None
            if self.score is None
            else float(self.score.final_score)
        )

    @property
    def interaction_id(self) -> str:
        """
        Return the resolved interaction identifier.
        """

        if self.score is not None:
            return self.score.interaction_id

        if self.extracted_data is not None:
            return self.extracted_data.interaction_id

        return ""

    @property
    def interaction_type(self) -> str:
        """
        Return the resolved interaction type.
        """

        if self.score is not None:
            return self.score.interaction_type

        if self.extracted_data is not None:
            return self.extracted_data.interaction_type

        return SCORE_TYPE_UNKNOWN

    @property
    def interaction_family(self) -> str:
        """
        Return the resolved interaction family.
        """

        if self.score is not None:
            return self.score.interaction_family

        if self.extracted_data is not None:
            return self.extracted_data.interaction_family

        return SCORE_FAMILY_UNKNOWN

    def require_score(
        self,
    ) -> InteractionScore:
        """
        Return the score or raise when scoring was unsuccessful.
        """

        if self.score is None:
            raise IndividualScoringPipelineError(
                self.message
                or "The individual scoring result has no score."
            )

        return self.score

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
        include_extracted_data: bool = True,
        include_score: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable result representation.
        """

        result: Dict[str, Any] = {
            "status": self.status,
            "source": self.source,
            "successful": bool(self.successful),
            "interaction_id": self.interaction_id,
            "interaction_type": self.interaction_type,
            "interaction_family": (
                self.interaction_family
            ),
            "final_score": self.final_score,
            "message": self.message,
            "trace": self.trace.to_dict(
                include_metadata=include_metadata
            ),
        }

        if include_score:
            result["score"] = (
                None
                if self.score is None
                else interaction_score_to_dict(
                    self.score,
                    include_metadata=include_metadata,
                )
            )

        if include_extracted_data:
            result["extracted_data"] = (
                None
                if self.extracted_data is None
                else extracted_interaction_data_to_dict(
                    self.extracted_data,
                    include_metadata=include_metadata,
                )
            )

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 13.8. Input-source detection
# -----------------------------------------------------------------------------

def identify_individual_scoring_source(
    value: Any,
) -> str:
    """
    Identify the source form supplied to individual scoring.
    """

    if isinstance(value, InteractionScore):
        return INDIVIDUAL_SCORING_SOURCE_SCORE

    if isinstance(
        value,
        ExtractedInteractionData,
    ):
        return INDIVIDUAL_SCORING_SOURCE_EXTRACTED

    if isinstance(value, Mapping):
        return INDIVIDUAL_SCORING_SOURCE_MAPPING

    if value is not None:
        return INDIVIDUAL_SCORING_SOURCE_OBJECT

    return INDIVIDUAL_SCORING_SOURCE_UNKNOWN


# -----------------------------------------------------------------------------
# 13.9. Mapping conversion
# -----------------------------------------------------------------------------

def extracted_interaction_data_from_mapping(
    value: Mapping[str, Any],
    *,
    preserve_reference: bool = True,
) -> ExtractedInteractionData:
    """
    Convert a mapping into ExtractedInteractionData.
    """

    if not isinstance(value, Mapping):
        raise IndividualScoringInputError(
            "value must be a mapping."
        )

    interaction_type = normalize_interaction_type(
        value.get(
            "interaction_type",
            value.get(
                "type",
                SCORE_TYPE_UNKNOWN,
            ),
        ),
        preserve_unknown=True,
    )

    interaction_family = canonical_interaction_family(
        value.get(
            "interaction_family",
            value.get(
                "family",
                interaction_type,
            ),
        )
    )

    data = ExtractedInteractionData(
        interaction_id=_coerce_identifier(
            value.get(
                "interaction_id",
                value.get(
                    "id",
                    "",
                ),
            )
        ),
        interaction_type=interaction_type,
        interaction_family=interaction_family,
        strength=value.get(
            "strength",
            STRENGTH_UNKNOWN,
        ),
        classification=value.get(
            "classification",
            CLASSIFICATION_UNKNOWN,
        ),
        geometry_quality=value.get(
            "geometry_quality",
            GEOMETRY_UNKNOWN,
        ),
        polarity=value.get(
            "polarity",
            POLARITY_UNKNOWN,
        ),
        atom_pair=tuple(
            value.get(
                "atom_pair",
                (),
            )
        ),
        residue_pair=tuple(
            value.get(
                "residue_pair",
                (),
            )
        ),
        distance=value.get("distance"),
        angle=value.get("angle"),
        offset=value.get("offset"),
        planarity=value.get("planarity"),
        overlap=value.get("overlap"),
        pose_id=_coerce_identifier(
            value.get(
                "pose_id",
                "",
            )
        ),
        model_id=_coerce_identifier(
            value.get(
                "model_id",
                "",
            )
        ),
        ligand_id=_coerce_identifier(
            value.get(
                "ligand_id",
                "",
            )
        ),
        container_name=_coerce_identifier(
            value.get(
                "container_name",
                "",
            )
        ),
        interaction=(
            value
            if preserve_reference
            else None
        ),
        metadata=value.get(
            "metadata",
            {},
        ),
    )

    validate_extracted_interaction_data(data)

    return data


# -----------------------------------------------------------------------------
# 13.10. Extracting one interaction
# -----------------------------------------------------------------------------

def extract_single_interaction(
    interaction: Any,
    *,
    profile: IndividualScoringProfile = (
        DEFAULT_INDIVIDUAL_SCORING_PROFILE
    ),
    container_name: Optional[str] = None,
    pose_id: Optional[str] = None,
    model_id: Optional[str] = None,
    ligand_id: Optional[str] = None,
) -> ExtractedInteractionData:
    """
    Extract exactly one interaction into the canonical scoring model.
    """

    if isinstance(
        interaction,
        ExtractedInteractionData,
    ):
        return interaction

    if isinstance(interaction, Mapping):
        return extracted_interaction_data_from_mapping(
            interaction,
            preserve_reference=(
                profile.options.preserve_references
            ),
        )

    extracted = extract_interaction_data(
        interaction,
        container_name=container_name,
        pose_id=pose_id,
        model_id=model_id,
        ligand_id=ligand_id,
        preserve_reference=(
            profile.options.preserve_references
        ),
    )

    validate_extracted_interaction_data(
        extracted
    )

    return extracted


# -----------------------------------------------------------------------------
# 13.11. Recognition of one interaction
# -----------------------------------------------------------------------------

def recognize_single_interaction(
    data: ExtractedInteractionData,
    *,
    profile: IndividualScoringProfile = (
        DEFAULT_INDIVIDUAL_SCORING_PROFILE
    ),
) -> ExtractedInteractionData:
    """
    Apply the recognition engine to one extracted interaction.
    """

    validate_extracted_interaction_data(data)

    if not profile.options.recognize_interaction:
        return data

    recognized = recognize_extracted_interaction(
        data,
        config=profile.recognition_config,
        custom_rules=profile.recognition_rules,
    )

    validate_extracted_interaction_data(
        recognized
    )

    return recognized


# -----------------------------------------------------------------------------
# 13.12. Individual scoring-policy validation
# -----------------------------------------------------------------------------

def validate_individual_scoring_policy(
    data: ExtractedInteractionData,
    *,
    options: IndividualScoringOptions = (
        DEFAULT_INDIVIDUAL_SCORING_OPTIONS
    ),
) -> ExtractedInteractionData:
    """
    Validate whether one interaction may be scored.
    """

    validate_extracted_interaction_data(data)

    if (
        not options.allow_unknown_type
        and data.interaction_type
        == SCORE_TYPE_UNKNOWN
    ):
        raise IndividualScoringRejectedError(
            "Unknown interaction types are disabled."
        )

    if (
        not options.allow_unknown_family
        and data.interaction_family
        == SCORE_FAMILY_UNKNOWN
    ):
        raise IndividualScoringRejectedError(
            "Unknown interaction families are disabled."
        )

    return data


# -----------------------------------------------------------------------------
# 13.13. Scoring already extracted data
# -----------------------------------------------------------------------------

def score_extracted_interaction(
    data: ExtractedInteractionData,
    *,
    profile: IndividualScoringProfile = (
        DEFAULT_INDIVIDUAL_SCORING_PROFILE
    ),
) -> InteractionScore:
    """
    Score one canonical ExtractedInteractionData object.

    This is the central individual-scoring function after extraction and
    recognition have already been completed.
    """

    if not isinstance(
        profile,
        IndividualScoringProfile,
    ):
        raise IndividualScoringInputError(
            "profile must be an IndividualScoringProfile."
        )

    validate_individual_scoring_policy(
        data,
        options=profile.options,
    )

    options = profile.options

    if options.apply_family_scoring:
        if options.apply_adjustments:
            score = interaction_score_with_adjustments(
                data,
                base_weight_profile=(
                    profile.base_weight_profile
                ),
                multiplier_profile=(
                    profile.multiplier_profile
                ),
                geometry_profile=(
                    profile.geometry_profile
                ),
                family_profile=(
                    profile.family_profile
                ),
                adjustment_profile=(
                    profile.adjustment_profile
                ),
                scoring_config=profile.scoring_config,
                weight_overrides=(
                    profile.weight_overrides
                ),
                strength_overrides=(
                    profile.strength_overrides
                ),
                classification_overrides=(
                    profile.classification_overrides
                ),
                strict_weights=options.strict_weights,
                strict_strength=options.strict_strength,
                strict_classification=(
                    options.strict_classification
                ),
                strict_geometry=options.strict_geometry,
                strict_family=options.strict_family,
                strict_adjustments=(
                    options.strict_adjustments
                ),
                preserve_components=(
                    options.preserve_components
                ),
            )

        else:
            score = interaction_score_with_family_scoring(
                data,
                base_weight_profile=(
                    profile.base_weight_profile
                ),
                multiplier_profile=(
                    profile.multiplier_profile
                ),
                geometry_profile=(
                    profile.geometry_profile
                ),
                family_profile=(
                    profile.family_profile
                ),
                scoring_config=profile.scoring_config,
                weight_overrides=(
                    profile.weight_overrides
                ),
                strength_overrides=(
                    profile.strength_overrides
                ),
                classification_overrides=(
                    profile.classification_overrides
                ),
                strict_weights=options.strict_weights,
                strict_strength=options.strict_strength,
                strict_classification=(
                    options.strict_classification
                ),
                strict_geometry=options.strict_geometry,
                strict_family=options.strict_family,
                preserve_components=(
                    options.preserve_components
                ),
            )

    else:
        score = interaction_score_with_geometry(
            data,
            base_weight_profile=(
                profile.base_weight_profile
            ),
            multiplier_profile=(
                profile.multiplier_profile
            ),
            geometry_profile=(
                profile.geometry_profile
            ),
            scoring_config=profile.scoring_config,
            weight_overrides=(
                profile.weight_overrides
            ),
            strength_overrides=(
                profile.strength_overrides
            ),
            classification_overrides=(
                profile.classification_overrides
            ),
            strict_weights=options.strict_weights,
            strict_strength=options.strict_strength,
            strict_classification=(
                options.strict_classification
            ),
            strict_geometry=options.strict_geometry,
            preserve_components=(
                options.preserve_components
            ),
        )

        if options.apply_adjustments:
            score = apply_adjustments_to_interaction_score(
                score,
                profile=profile.adjustment_profile,
                strict=options.strict_adjustments,
            )

    if options.validate_result:
        validate_individual_interaction_score(
            score,
            options=options,
        )

    return score


# -----------------------------------------------------------------------------
# 13.14. Rescoring an InteractionScore
# -----------------------------------------------------------------------------

def rescore_individual_interaction(
    score: InteractionScore,
    *,
    profile: IndividualScoringProfile = (
        DEFAULT_INDIVIDUAL_SCORING_PROFILE
    ),
) -> InteractionScore:
    """
    Rebuild an individual score from the original interaction reference.

    When no original interaction reference is available, the existing score
    is updated only through family scoring and adjustments.
    """

    validate_interaction_score(
        score,
        validate_consistency=False,
    )

    interaction = score.interaction

    if interaction is not None:
        result = score_individual_interaction(
            interaction,
            profile=profile,
            container_name=score.container_name,
            pose_id=score.pose_id,
            model_id=score.model_id,
            ligand_id=score.ligand_id,
            raise_errors=True,
        )

        return result.require_score()

    updated = score

    if profile.options.apply_family_scoring:
        updated = apply_family_scoring_to_score(
            updated,
            profile=profile.family_profile,
            scoring_config=profile.scoring_config,
            strict=profile.options.strict_family,
        )

    if profile.options.apply_adjustments:
        updated = apply_adjustments_to_interaction_score(
            updated,
            profile=profile.adjustment_profile,
            strict=profile.options.strict_adjustments,
        )

    if profile.options.validate_result:
        validate_individual_interaction_score(
            updated,
            options=profile.options,
        )

    return updated


# -----------------------------------------------------------------------------
# 13.15. Main individual-scoring API
# -----------------------------------------------------------------------------

def score_individual_interaction(
    interaction: Any,
    *,
    profile: IndividualScoringProfile = (
        DEFAULT_INDIVIDUAL_SCORING_PROFILE
    ),
    container_name: Optional[str] = None,
    pose_id: Optional[str] = None,
    model_id: Optional[str] = None,
    ligand_id: Optional[str] = None,
    raise_errors: bool = False,
) -> IndividualScoringResult:
    """
    Score one interaction through the complete scoring pipeline.

    Supported inputs:
    - ExtractedInteractionData;
    - InteractionScore;
    - mapping;
    - interaction object from any detector module.
    """

    if not isinstance(
        profile,
        IndividualScoringProfile,
    ):
        raise IndividualScoringInputError(
            "profile must be an IndividualScoringProfile."
        )

    source = identify_individual_scoring_source(
        interaction
    )

    trace = IndividualScoringTrace(
        metadata={
            "source_type": object_type_name(
                interaction
            ),
        }
    )

    extracted: Optional[
        ExtractedInteractionData
    ] = None

    try:
        if isinstance(interaction, InteractionScore):
            trace = trace.with_completed_stage(
                INDIVIDUAL_SCORING_STAGE_EXTRACTION
            )
            trace = trace.with_completed_stage(
                INDIVIDUAL_SCORING_STAGE_RECOGNITION
            )

            rescored = rescore_individual_interaction(
                interaction,
                profile=profile,
            )

            for stage in (
                INDIVIDUAL_SCORING_STAGE_BASE_WEIGHT,
                INDIVIDUAL_SCORING_STAGE_MULTIPLIERS,
                INDIVIDUAL_SCORING_STAGE_GEOMETRY,
                INDIVIDUAL_SCORING_STAGE_FAMILY,
                INDIVIDUAL_SCORING_STAGE_ADJUSTMENTS,
                INDIVIDUAL_SCORING_STAGE_VALIDATION,
                INDIVIDUAL_SCORING_STAGE_COMPLETE,
            ):
                trace = trace.with_completed_stage(stage)

            return IndividualScoringResult(
                status=INDIVIDUAL_SCORING_STATUS_SCORED,
                source=source,
                score=rescored,
                extracted_data=None,
                trace=trace,
                message=(
                    "The existing InteractionScore was rescored."
                ),
                interaction=interaction,
                metadata={
                    "rescored": True,
                },
            )

        extracted = extract_single_interaction(
            interaction,
            profile=profile,
            container_name=container_name,
            pose_id=pose_id,
            model_id=model_id,
            ligand_id=ligand_id,
        )

        trace = trace.with_completed_stage(
            INDIVIDUAL_SCORING_STAGE_EXTRACTION
        )

        recognized = recognize_single_interaction(
            extracted,
            profile=profile,
        )

        trace = trace.with_completed_stage(
            INDIVIDUAL_SCORING_STAGE_RECOGNITION
        )

        validate_individual_scoring_policy(
            recognized,
            options=profile.options,
        )

        score = score_extracted_interaction(
            recognized,
            profile=profile,
        )

        trace = trace.with_completed_stage(
            INDIVIDUAL_SCORING_STAGE_BASE_WEIGHT
        )
        trace = trace.with_completed_stage(
            INDIVIDUAL_SCORING_STAGE_MULTIPLIERS
        )
        trace = trace.with_completed_stage(
            INDIVIDUAL_SCORING_STAGE_GEOMETRY
        )

        if profile.options.apply_family_scoring:
            trace = trace.with_completed_stage(
                INDIVIDUAL_SCORING_STAGE_FAMILY
            )

        if profile.options.apply_adjustments:
            trace = trace.with_completed_stage(
                INDIVIDUAL_SCORING_STAGE_ADJUSTMENTS
            )

        if profile.options.validate_result:
            trace = trace.with_completed_stage(
                INDIVIDUAL_SCORING_STAGE_VALIDATION
            )

        trace = trace.with_completed_stage(
            INDIVIDUAL_SCORING_STAGE_COMPLETE
        )

        return IndividualScoringResult(
            status=INDIVIDUAL_SCORING_STATUS_SCORED,
            source=source,
            score=score,
            extracted_data=recognized,
            trace=trace,
            message=(
                "The interaction was scored successfully."
            ),
            interaction=(
                interaction
                if profile.options.preserve_references
                else None
            ),
            metadata={
                "profile_metadata": dict(
                    profile.metadata
                ),
            },
        )

    except IndividualScoringRejectedError as exc:
        failed_trace = trace.with_failure(
            INDIVIDUAL_SCORING_STAGE_VALIDATION,
            str(exc),
        )

        if raise_errors:
            raise

        return IndividualScoringResult(
            status=INDIVIDUAL_SCORING_STATUS_REJECTED,
            source=source,
            score=None,
            extracted_data=extracted,
            trace=failed_trace,
            message=str(exc),
            interaction=(
                interaction
                if profile.options.preserve_references
                else None
            ),
        )

    except Exception as exc:
        failed_stage = _infer_failed_individual_scoring_stage(
            trace
        )

        failed_trace = trace.with_failure(
            failed_stage,
            str(exc),
        )

        if raise_errors:
            if isinstance(exc, ScoringError):
                raise

            raise IndividualScoringPipelineError(
                "Individual interaction scoring failed."
            ) from exc

        return IndividualScoringResult(
            status=INDIVIDUAL_SCORING_STATUS_FAILED,
            source=source,
            score=None,
            extracted_data=extracted,
            trace=failed_trace,
            message=str(exc),
            interaction=(
                interaction
                if profile.options.preserve_references
                else None
            ),
            metadata={
                "error_type": object_type_name(exc),
            },
        )


def _infer_failed_individual_scoring_stage(
    trace: IndividualScoringTrace,
) -> str:
    """
    Infer the first pipeline stage that has not completed.
    """

    completed = set(
        trace.completed_stages
    )

    for stage in INDIVIDUAL_SCORING_STAGES:
        if stage not in completed:
            return stage

    return INDIVIDUAL_SCORING_STAGE_COMPLETE


# -----------------------------------------------------------------------------
# 13.16. Convenience wrappers
# -----------------------------------------------------------------------------

def individual_interaction_score(
    interaction: Any,
    *,
    profile: IndividualScoringProfile = (
        DEFAULT_INDIVIDUAL_SCORING_PROFILE
    ),
    container_name: Optional[str] = None,
    pose_id: Optional[str] = None,
    model_id: Optional[str] = None,
    ligand_id: Optional[str] = None,
) -> InteractionScore:
    """
    Score one interaction and return only InteractionScore.

    This function raises when scoring fails.
    """

    result = score_individual_interaction(
        interaction,
        profile=profile,
        container_name=container_name,
        pose_id=pose_id,
        model_id=model_id,
        ligand_id=ligand_id,
        raise_errors=True,
    )

    return result.require_score()


def try_score_individual_interaction(
    interaction: Any,
    *,
    profile: IndividualScoringProfile = (
        DEFAULT_INDIVIDUAL_SCORING_PROFILE
    ),
    container_name: Optional[str] = None,
    pose_id: Optional[str] = None,
    model_id: Optional[str] = None,
    ligand_id: Optional[str] = None,
) -> Optional[InteractionScore]:
    """
    Score one interaction and return None when scoring fails.
    """

    result = score_individual_interaction(
        interaction,
        profile=profile,
        container_name=container_name,
        pose_id=pose_id,
        model_id=model_id,
        ligand_id=ligand_id,
        raise_errors=False,
    )

    return result.score


def score_individual_mapping(
    interaction: Mapping[str, Any],
    *,
    profile: IndividualScoringProfile = (
        DEFAULT_INDIVIDUAL_SCORING_PROFILE
    ),
) -> IndividualScoringResult:
    """
    Score one dictionary-like interaction.
    """

    return score_individual_interaction(
        interaction,
        profile=profile,
    )


# -----------------------------------------------------------------------------
# 13.17. Individual score decomposition
# -----------------------------------------------------------------------------

def individual_score_decomposition(
    score: InteractionScore,
) -> Mapping[str, Any]:
    """
    Return the complete numerical decomposition of one score.
    """

    validate_interaction_score(
        score,
        validate_consistency=False,
    )

    multiplicative_score = float(
        score.base_weight
        * score.strength_multiplier
        * score.classification_multiplier
        * score.geometry_multiplier
    )

    family_data = score.metadata.get(
        "family_scoring",
        {},
    )

    if isinstance(family_data, Mapping):
        family_multiplier = float(
            family_data.get(
                "multiplier",
                1.0,
            )
        )
        family_adjustment = float(
            family_data.get(
                "adjustment",
                0.0,
            )
        )
        family_bonus = float(
            family_data.get(
                "bonus",
                0.0,
            )
        )
        family_penalty = float(
            family_data.get(
                "penalty",
                0.0,
            )
        )
    else:
        family_multiplier = 1.0
        family_adjustment = 0.0
        family_bonus = 0.0
        family_penalty = 0.0

    family_raw_score = float(
        multiplicative_score
        * family_multiplier
        + family_adjustment
    )

    adjustment_data = score.metadata.get(
        "score_adjustments",
        (),
    )

    adjustment_count = (
        len(adjustment_data)
        if isinstance(
            adjustment_data,
            Sequence,
        )
        and not isinstance(
            adjustment_data,
            (
                str,
                bytes,
                bytearray,
            ),
        )
        else 0
    )

    return MappingProxyType(
        {
            "base_weight": float(
                score.base_weight
            ),
            "strength_multiplier": float(
                score.strength_multiplier
            ),
            "classification_multiplier": float(
                score.classification_multiplier
            ),
            "geometry_multiplier": float(
                score.geometry_multiplier
            ),
            "multiplicative_score": (
                multiplicative_score
            ),
            "family_multiplier": (
                family_multiplier
            ),
            "family_adjustment": (
                family_adjustment
            ),
            "family_bonus": family_bonus,
            "family_penalty": family_penalty,
            "family_raw_score": (
                family_raw_score
            ),
            "stored_raw_score": float(
                score.raw_score
            ),
            "penalty_score": float(
                score.penalty_score
            ),
            "bonus_score": float(
                score.bonus_score
            ),
            "final_score": float(
                score.final_score
            ),
            "adjustment_count": (
                adjustment_count
            ),
        }
    )


# -----------------------------------------------------------------------------
# 13.18. Validation
# -----------------------------------------------------------------------------

def validate_individual_scoring_options(
    options: IndividualScoringOptions,
) -> IndividualScoringOptions:
    """
    Validate and return individual-scoring options.
    """

    if not isinstance(
        options,
        IndividualScoringOptions,
    ):
        raise IndividualScoringValidationError(
            "Expected IndividualScoringOptions."
        )

    return options


def validate_individual_scoring_profile(
    profile: IndividualScoringProfile,
) -> IndividualScoringProfile:
    """
    Validate and return an individual-scoring profile.
    """

    if not isinstance(
        profile,
        IndividualScoringProfile,
    ):
        raise IndividualScoringValidationError(
            "Expected IndividualScoringProfile."
        )

    validate_individual_scoring_options(
        profile.options
    )
    validate_base_weight_profile(
        profile.base_weight_profile
    )
    validate_interaction_multiplier_profile(
        profile.multiplier_profile
    )
    validate_geometry_quality_profile(
        profile.geometry_profile
    )
    validate_family_scoring_profile(
        profile.family_profile
    )
    validate_score_adjustment_profile(
        profile.adjustment_profile
    )

    return profile


def validate_individual_interaction_score(
    score: InteractionScore,
    *,
    options: IndividualScoringOptions = (
        DEFAULT_INDIVIDUAL_SCORING_OPTIONS
    ),
) -> InteractionScore:
    """
    Validate the final score of one interaction.
    """

    validate_interaction_score(
        score,
        validate_consistency=False,
    )

    if not math.isfinite(score.raw_score):
        raise IndividualScoringValidationError(
            "raw_score must be finite."
        )

    if not math.isfinite(score.final_score):
        raise IndividualScoringValidationError(
            "final_score must be finite."
        )

    if score.penalty_score < 0.0:
        raise IndividualScoringValidationError(
            "penalty_score cannot be negative."
        )

    if score.bonus_score < 0.0:
        raise IndividualScoringValidationError(
            "bonus_score cannot be negative."
        )

    if (
        not options.allow_neutral_score
        and abs(score.final_score)
        <= SCORE_COMPARISON_TOLERANCE
    ):
        raise IndividualScoringValidationError(
            "Neutral individual scores are disabled."
        )

    if (
        not options.allow_unknown_type
        and score.interaction_type
        == SCORE_TYPE_UNKNOWN
    ):
        raise IndividualScoringValidationError(
            "The final score has an unknown interaction type."
        )

    if (
        not options.allow_unknown_family
        and score.interaction_family
        == SCORE_FAMILY_UNKNOWN
    ):
        raise IndividualScoringValidationError(
            "The final score has an unknown interaction family."
        )

    return score


def validate_individual_scoring_trace(
    trace: IndividualScoringTrace,
) -> IndividualScoringTrace:
    """
    Validate and return an individual-scoring trace.
    """

    if not isinstance(
        trace,
        IndividualScoringTrace,
    ):
        raise IndividualScoringValidationError(
            "Expected IndividualScoringTrace."
        )

    return trace


def validate_individual_scoring_result(
    result: IndividualScoringResult,
) -> IndividualScoringResult:
    """
    Validate and return an individual-scoring result.
    """

    if not isinstance(
        result,
        IndividualScoringResult,
    ):
        raise IndividualScoringValidationError(
            "Expected IndividualScoringResult."
        )

    validate_individual_scoring_trace(
        result.trace
    )

    if result.score is not None:
        validate_interaction_score(
            result.score,
            validate_consistency=False,
        )

    if (
        result.status
        == INDIVIDUAL_SCORING_STATUS_SCORED
        and result.score is None
    ):
        raise IndividualScoringValidationError(
            "A scored result must contain a score."
        )

    return result


# -----------------------------------------------------------------------------
# 13.19. Explainability
# -----------------------------------------------------------------------------

def explain_individual_interaction_score(
    score: InteractionScore,
) -> ScoreExplanation:
    """
    Build a complete explanation tree for one interaction score.
    """

    validate_interaction_score(
        score,
        validate_consistency=False,
    )

    children: List[ScoreExplanation] = []

    base_resolution = score.metadata.get(
        "base_weight_resolution"
    )

    if isinstance(base_resolution, Mapping):
        children.append(
            ScoreExplanation(
                explanation_id="individual:base_weight",
                title="Base interaction weight",
                message=_coerce_optional_text(
                    base_resolution.get(
                        "reason",
                        "",
                    )
                ),
                scope=EXPLANATION_SCOPE_INTERACTION,
                severity=EXPLANATION_SEVERITY_INFO,
                level=EXPLANATION_LEVEL_STANDARD,
                value=float(score.base_weight),
                reference_value=0.0,
                interaction_type=score.interaction_type,
                tags=(
                    "individual_scoring",
                    "base_weight",
                ),
                metadata=dict(base_resolution),
            )
        )

    children.append(
        ScoreExplanation(
            explanation_id="individual:multipliers",
            title="Interaction multipliers",
            message=(
                "Strength, classification and geometry multipliers "
                "were applied to the base interaction weight."
            ),
            scope=EXPLANATION_SCOPE_INTERACTION,
            severity=EXPLANATION_SEVERITY_INFO,
            level=EXPLANATION_LEVEL_STANDARD,
            value=float(
                score.strength_multiplier
                * score.classification_multiplier
                * score.geometry_multiplier
            ),
            reference_value=1.0,
            interaction_type=score.interaction_type,
            tags=(
                "individual_scoring",
                "multipliers",
            ),
            metadata={
                "strength_multiplier": (
                    score.strength_multiplier
                ),
                "classification_multiplier": (
                    score.classification_multiplier
                ),
                "geometry_multiplier": (
                    score.geometry_multiplier
                ),
            },
        )
    )

    family_data = score.metadata.get(
        "family_scoring"
    )

    if isinstance(family_data, Mapping):
        family_contribution = FamilyScoreContribution(
            interaction_family=family_data.get(
                "interaction_family",
                score.interaction_family,
            ),
            interaction_type=family_data.get(
                "interaction_type",
                score.interaction_type,
            ),
            multiplier=family_data.get(
                "multiplier",
                1.0,
            ),
            adjustment=family_data.get(
                "adjustment",
                0.0,
            ),
            bonus=family_data.get(
                "bonus",
                0.0,
            ),
            penalty=family_data.get(
                "penalty",
                0.0,
            ),
            source=family_data.get(
                "source",
                FAMILY_SCORING_SOURCE_UNKNOWN,
            ),
            status=family_data.get(
                "status",
                FAMILY_SCORING_STATUS_NEUTRAL,
            ),
            rule_name=family_data.get(
                "rule_name",
                "",
            ),
            reason=family_data.get(
                "reason",
                "",
            ),
            metadata=family_data.get(
                "metadata",
                {},
            ),
        )

        children.append(
            explain_family_score_contribution(
                family_contribution,
                input_score=score.metadata.get(
                    "pre_family_raw_score",
                    score.raw_score,
                ),
            )
        )

    raw_adjustments = score.metadata.get(
        "score_adjustments",
        (),
    )

    adjustments: List[ScoreAdjustment] = []

    if isinstance(
        raw_adjustments,
        Sequence,
    ) and not isinstance(
        raw_adjustments,
        (
            str,
            bytes,
            bytearray,
        ),
    ):
        for index, raw_adjustment in enumerate(
            raw_adjustments
        ):
            if isinstance(
                raw_adjustment,
                ScoreAdjustment,
            ):
                adjustments.append(
                    raw_adjustment
                )

            elif isinstance(
                raw_adjustment,
                Mapping,
            ):
                adjustments.append(
                    coerce_score_adjustment(
                        raw_adjustment,
                        index=index,
                    )
                )

    if adjustments:
        children.append(
            explain_score_adjustments(
                adjustments,
                input_score=float(
                    score.metadata.get(
                        "pre_adjustment_final_score",
                        score.raw_score,
                    )
                ),
            )
        )

    decomposition = individual_score_decomposition(
        score
    )

    severity = (
        EXPLANATION_SEVERITY_SUCCESS
        if score.final_score > 0.0
        else (
            EXPLANATION_SEVERITY_WARNING
            if score.final_score < 0.0
            else EXPLANATION_SEVERITY_INFO
        )
    )

    return ScoreExplanation(
        explanation_id=(
            f"individual_score:"
            f"{score.interaction_id}"
        ),
        title="Individual interaction score",
        message=(
            "The final score was calculated from the base weight, "
            "interaction multipliers, family-specific scoring and "
            "score adjustments."
        ),
        scope=EXPLANATION_SCOPE_INTERACTION,
        severity=severity,
        level=EXPLANATION_LEVEL_SUMMARY,
        value=float(score.final_score),
        reference_value=0.0,
        interaction_type=score.interaction_type,
        entity_id=score.interaction_id,
        tags=(
            "individual_scoring",
            score.interaction_type,
            score.interaction_family,
            score.polarity,
        ),
        children=tuple(children),
        metadata=dict(decomposition),
    )


def explain_individual_scoring_result(
    result: IndividualScoringResult,
) -> ScoreExplanation:
    """
    Explain an IndividualScoringResult.
    """

    validate_individual_scoring_result(
        result
    )

    if result.score is not None:
        return explain_individual_interaction_score(
            result.score
        )

    severity = (
        EXPLANATION_SEVERITY_ERROR
        if result.status
        in {
            INDIVIDUAL_SCORING_STATUS_FAILED,
            INDIVIDUAL_SCORING_STATUS_REJECTED,
        }
        else EXPLANATION_SEVERITY_WARNING
    )

    return ScoreExplanation(
        explanation_id="individual_score:unavailable",
        title="Individual interaction score unavailable",
        message=result.message,
        scope=EXPLANATION_SCOPE_INTERACTION,
        severity=severity,
        level=EXPLANATION_LEVEL_SUMMARY,
        value=None,
        reference_value=None,
        interaction_type=result.interaction_type,
        entity_id=result.interaction_id,
        tags=(
            "individual_scoring",
            result.status,
            result.source,
        ),
        metadata={
            "trace": result.trace.to_dict(
                include_metadata=True
            ),
        },
    )


# -----------------------------------------------------------------------------
# 13.20. Serialization helpers
# -----------------------------------------------------------------------------

def individual_scoring_result_to_dict(
    result: IndividualScoringResult,
    *,
    include_metadata: bool = True,
    include_extracted_data: bool = True,
    include_score: bool = True,
) -> Dict[str, Any]:
    """
    Convert one individual scoring result to a dictionary.
    """

    validate_individual_scoring_result(
        result
    )

    return result.to_dict(
        include_metadata=include_metadata,
        include_extracted_data=(
            include_extracted_data
        ),
        include_score=include_score,
    )


def serialize_individual_scoring_result(
    result: IndividualScoringResult,
    *,
    indent: Optional[int] = 2,
    sort_keys: bool = True,
    include_metadata: bool = True,
) -> str:
    """
    Serialize one individual scoring result as JSON.
    """

    return json.dumps(
        individual_scoring_result_to_dict(
            result,
            include_metadata=include_metadata,
        ),
        indent=indent,
        sort_keys=sort_keys,
        ensure_ascii=False,
        default=str,
    )


# -----------------------------------------------------------------------------
# 13.21. Section consistency validation
# -----------------------------------------------------------------------------

def _validate_section_13_individual_scoring() -> None:
    """
    Validate individual interaction scoring during import.
    """

    profile = IndividualScoringProfile(
        base_weight_profile=BaseWeightProfile(
            interaction_weights={
                "hydrogen_bond": 2.0,
            },
            family_weights={},
        ),
        multiplier_profile=InteractionMultiplierProfile(
            strength_multipliers={
                "strong": 1.25,
                "unknown": 1.0,
            },
            classification_multipliers={
                "charge_assisted": 1.20,
                "unknown": 1.0,
            },
        ),
        geometry_profile=GeometryQualityProfile(
            multipliers={
                "ideal": 1.20,
                "good": 1.0,
                "acceptable": 0.85,
                "poor": 0.60,
                "unknown": 1.0,
            },
            rules_by_type={},
            trust_explicit_quality=True,
        ),
        family_profile=FamilyScoringProfile(
            family_multipliers={
                "hydrogen_bond": 1.0,
            },
            family_adjustments={
                "hydrogen_bond": 0.0,
            },
            rules=(),
        ),
        adjustment_profile=ScoreAdjustmentProfile(
            rules=(),
        ),
        options=IndividualScoringOptions(
            recognize_interaction=False,
            apply_family_scoring=True,
            apply_adjustments=True,
        ),
    )

    data = ExtractedInteractionData(
        interaction_id="hbond_individual_1",
        interaction_type="hydrogen_bond",
        interaction_family="hydrogen_bond",
        strength="strong",
        classification="charge_assisted",
        geometry_quality="ideal",
        polarity="favorable",
        atom_pair=(
            "A:10:N",
            "L:1:O",
        ),
        residue_pair=(
            "A:10:LYS",
            "L:1:LIG",
        ),
        distance=2.7,
        angle=170.0,
    )

    result = score_individual_interaction(
        data,
        profile=profile,
        raise_errors=True,
    )

    if not result.successful:
        raise RuntimeError(
            "Individual scoring result validation failed."
        )

    score = result.require_score()

    expected = (
        2.0
        * 1.25
        * 1.20
        * 1.20
    )

    if (
        abs(score.final_score - expected)
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Individual score calculation validation failed."
        )

    if not result.trace.complete:
        raise RuntimeError(
            "Individual scoring trace validation failed."
        )

    decomposition = individual_score_decomposition(
        score
    )

    if (
        abs(
            decomposition["multiplicative_score"]
            - expected
        )
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Individual score decomposition validation failed."
        )

    mapping_result = score_individual_mapping(
        {
            "interaction_id": "contact_mapping_1",
            "interaction_type": "contact",
            "interaction_family": "contact",
            "strength": "unknown",
            "classification": "unknown",
            "geometry_quality": "unknown",
            "distance": 4.0,
        },
        profile=IndividualScoringProfile(
            base_weight_profile=BaseWeightProfile(
                interaction_weights={
                    "contact": 1.0,
                },
                family_weights={},
            ),
            multiplier_profile=InteractionMultiplierProfile(
                strength_multipliers={
                    "unknown": 1.0,
                },
                classification_multipliers={
                    "unknown": 1.0,
                },
            ),
            geometry_profile=GeometryQualityProfile(
                multipliers={
                    "unknown": 1.0,
                },
                rules_by_type={},
            ),
            family_profile=FamilyScoringProfile(
                family_multipliers={
                    "contact": 1.0,
                },
                family_adjustments={
                    "contact": 0.0,
                },
                rules=(),
            ),
            adjustment_profile=ScoreAdjustmentProfile(
                rules=(),
            ),
            options=IndividualScoringOptions(
                recognize_interaction=False,
            ),
        ),
    )

    if mapping_result.score is None:
        raise RuntimeError(
            "Mapping-based individual scoring validation failed."
        )

    explanation = explain_individual_scoring_result(
        result
    )

    if explanation.scope != EXPLANATION_SCOPE_INTERACTION:
        raise RuntimeError(
            "Individual score explanation validation failed."
        )

    serialized = serialize_individual_scoring_result(
        result
    )

    if "hbond_individual_1" not in serialized:
        raise RuntimeError(
            "Individual score serialization validation failed."
        )

    validate_individual_scoring_options(
        profile.options
    )
    validate_individual_scoring_profile(
        profile
    )
    validate_individual_interaction_score(
        score,
        options=profile.options,
    )
    validate_individual_scoring_trace(
        result.trace
    )
    validate_individual_scoring_result(
        result
    )


_validate_section_13_individual_scoring()


