# -----------------------------------------------------------------------------
# 15.1. Residue-aggregation constants
# -----------------------------------------------------------------------------

RESIDUE_AGGREGATION_STATUS_AGGREGATED: Final[str] = "aggregated"
RESIDUE_AGGREGATION_STATUS_PARTIAL: Final[str] = "partial"
RESIDUE_AGGREGATION_STATUS_EMPTY: Final[str] = "empty"
RESIDUE_AGGREGATION_STATUS_FAILED: Final[str] = "failed"

RESIDUE_AGGREGATION_STATUSES: Final[FrozenSet[str]] = frozenset(
    {
        RESIDUE_AGGREGATION_STATUS_AGGREGATED,
        RESIDUE_AGGREGATION_STATUS_PARTIAL,
        RESIDUE_AGGREGATION_STATUS_EMPTY,
        RESIDUE_AGGREGATION_STATUS_FAILED,
    }
)


RESIDUE_ALLOCATION_FULL: Final[str] = "full"
RESIDUE_ALLOCATION_EQUAL_SPLIT: Final[str] = "equal_split"
RESIDUE_ALLOCATION_WEIGHTED: Final[str] = "weighted"
RESIDUE_ALLOCATION_PRIMARY_ONLY: Final[str] = "primary_only"

RESIDUE_ALLOCATION_MODES: Final[FrozenSet[str]] = frozenset(
    {
        RESIDUE_ALLOCATION_FULL,
        RESIDUE_ALLOCATION_EQUAL_SPLIT,
        RESIDUE_ALLOCATION_WEIGHTED,
        RESIDUE_ALLOCATION_PRIMARY_ONLY,
    }
)


RESIDUE_SIDE_RECEPTOR: Final[str] = "receptor"
RESIDUE_SIDE_LIGAND: Final[str] = "ligand"
RESIDUE_SIDE_PARTNER: Final[str] = "partner"
RESIDUE_SIDE_UNKNOWN: Final[str] = "unknown"

RESIDUE_SIDES: Final[FrozenSet[str]] = frozenset(
    {
        RESIDUE_SIDE_RECEPTOR,
        RESIDUE_SIDE_LIGAND,
        RESIDUE_SIDE_PARTNER,
        RESIDUE_SIDE_UNKNOWN,
    }
)


RESIDUE_RANKING_FINAL_SCORE: Final[str] = "final_score"
RESIDUE_RANKING_ABSOLUTE_SCORE: Final[str] = "absolute_score"
RESIDUE_RANKING_INTERACTION_COUNT: Final[str] = "interaction_count"
RESIDUE_RANKING_FAVORABLE_SCORE: Final[str] = "favorable_score"
RESIDUE_RANKING_UNFAVORABLE_SCORE: Final[str] = "unfavorable_score"

RESIDUE_RANKING_MODES: Final[FrozenSet[str]] = frozenset(
    {
        RESIDUE_RANKING_FINAL_SCORE,
        RESIDUE_RANKING_ABSOLUTE_SCORE,
        RESIDUE_RANKING_INTERACTION_COUNT,
        RESIDUE_RANKING_FAVORABLE_SCORE,
        RESIDUE_RANKING_UNFAVORABLE_SCORE,
    }
)


DEFAULT_RESIDUE_ALLOCATION_MODE: Final[str] = (
    RESIDUE_ALLOCATION_EQUAL_SPLIT
)
DEFAULT_RESIDUE_RANKING_MODE: Final[str] = (
    RESIDUE_RANKING_ABSOLUTE_SCORE
)
DEFAULT_RESIDUE_HOTSPOT_LIMIT: Final[int] = 10
DEFAULT_RESIDUE_INCLUDE_LIGAND: Final[bool] = False
DEFAULT_RESIDUE_INCLUDE_UNKNOWN: Final[bool] = True
DEFAULT_RESIDUE_PRESERVE_INTERACTIONS: Final[bool] = True


