def normalize_score_normalization_status(
    value: Any,
    *,
    default: str = SCORE_NORMALIZATION_STATUS_FAILED,
) -> str:
    """
    Normalize a score-normalization status.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in SCORE_NORMALIZATION_STATUSES:
        return normalized

    return _SCORE_NORMALIZATION_STATUS_ALIASES.get(
        normalized,
        default,
    )


def normalize_score_normalization_method(
    value: Any,
    *,
    default: str = DEFAULT_SCORE_NORMALIZATION_METHOD,
) -> str:
    """
    Normalize a cross-pose score-normalization method.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in SCORE_NORMALIZATION_METHODS:
        return normalized

    return _SCORE_NORMALIZATION_METHOD_ALIASES.get(
        normalized,
        default,
    )


def normalize_score_direction(
    value: Any,
    *,
    default: str = DEFAULT_SCORE_NORMALIZATION_DIRECTION,
) -> str:
    """
    Normalize the meaning of better and worse scores.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in SCORE_DIRECTIONS:
        return normalized

    return _SCORE_DIRECTION_ALIASES.get(
        normalized,
        default,
    )


def normalize_score_degenerate_policy(
    value: Any,
    *,
    default: str = DEFAULT_SCORE_DEGENERATE_POLICY,
) -> str:
    """
    Normalize the policy used for constant or degenerate score sets.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in SCORE_DEGENERATE_POLICIES:
        return normalized

    return _SCORE_DEGENERATE_POLICY_ALIASES.get(
        normalized,
        default,
    )


def normalize_score_normalization_ranking_mode(
    value: Any,
    *,
    default: str = DEFAULT_SCORE_NORMALIZATION_RANKING_MODE,
) -> str:
    """
    Normalize the ranking metric used after normalization.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in SCORE_NORMALIZATION_RANKING_MODES:
        return normalized

    return _SCORE_NORMALIZATION_RANKING_ALIASES.get(
        normalized,
        default,
    )


def normalize_score_reference_mode(
    value: Any,
    *,
    default: str = DEFAULT_SCORE_REFERENCE_MODE,
) -> str:
    """
    Normalize the reference-value selection mode.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in SCORE_REFERENCE_MODES:
        return normalized

    return _SCORE_REFERENCE_MODE_ALIASES.get(
        normalized,
        default,
    )


# -----------------------------------------------------------------------------
# 17.3. Exceptions
# -----------------------------------------------------------------------------

class ScoreNormalizationError(ScoringError):
    """
    Base exception for cross-pose score normalization.
    """


class ScoreNormalizationInputError(ScoreNormalizationError):
    """
    Raised when normalization input is invalid.
    """


class ScoreNormalizationMethodError(ScoreNormalizationError):
    """
    Raised when a normalization method cannot be applied.
    """


class ScoreNormalizationDegenerateError(ScoreNormalizationError):
    """
    Raised when a degenerate score set cannot be normalized.
    """


class ScoreNormalizationReferenceError(ScoreNormalizationError):
    """
    Raised when a required reference score is unavailable.
    """


class ScoreNormalizationValidationError(ScoreNormalizationError):
    """
    Raised when normalized scores are inconsistent.
    """


# -----------------------------------------------------------------------------
# 17.4. ScoreNormalizationStatistics
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ScoreNormalizationStatistics:
    """
    Descriptive statistics used by a normalization operation.
    """

    count: int

    minimum: Optional[float]
    maximum: Optional[float]
    mean: Optional[float]
    median: Optional[float]

    population_variance: Optional[float]
    population_standard_deviation: Optional[float]

    first_quartile: Optional[float]
    third_quartile: Optional[float]
    interquartile_range: Optional[float]
    median_absolute_deviation: Optional[float]

    maximum_absolute_value: Optional[float]
    value_range: Optional[float]

    reference_value: Optional[float] = None
    degenerate: bool = False

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize descriptive statistics.
        """

        count = int(self.count)

        if count < 0:
            raise ScoreNormalizationValidationError(
                "ScoreNormalizationStatistics.count cannot be negative."
            )

        object.__setattr__(
            self,
            "count",
            count,
        )

        for field_name in (
            "minimum",
            "maximum",
            "mean",
            "median",
            "population_variance",
            "population_standard_deviation",
            "first_quartile",
            "third_quartile",
            "interquartile_range",
            "median_absolute_deviation",
            "maximum_absolute_value",
            "value_range",
            "reference_value",
        ):
            value = getattr(self, field_name)

            object.__setattr__(
                self,
                field_name,
                (
                    None
                    if value is None
                    else float(
                        _coerce_finite_score_value(
                            value,
                            name=(
                                "ScoreNormalizationStatistics."
                                f"{field_name}"
                            ),
                        )
                    )
                ),
            )

        object.__setattr__(
            self,
            "degenerate",
            bool(self.degenerate),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable statistics representation.
        """

        result: Dict[str, Any] = {
            "count": self.count,
            "minimum": self.minimum,
            "maximum": self.maximum,
            "mean": self.mean,
            "median": self.median,
            "population_variance": self.population_variance,
            "population_standard_deviation": (
                self.population_standard_deviation
            ),
            "first_quartile": self.first_quartile,
            "third_quartile": self.third_quartile,
            "interquartile_range": self.interquartile_range,
            "median_absolute_deviation": (
                self.median_absolute_deviation
            ),
            "maximum_absolute_value": (
                self.maximum_absolute_value
            ),
            "value_range": self.value_range,
            "reference_value": self.reference_value,
            "degenerate": self.degenerate,
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 17.5. Normalization options
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ScoreNormalizationOptions:
    """
    Immutable configuration for cross-pose normalization.
    """

    method: str = DEFAULT_SCORE_NORMALIZATION_METHOD
    direction: str = DEFAULT_SCORE_NORMALIZATION_DIRECTION
    degenerate_policy: str = DEFAULT_SCORE_DEGENERATE_POLICY
    ranking_mode: str = DEFAULT_SCORE_NORMALIZATION_RANKING_MODE

    lower_bound: float = DEFAULT_SCORE_NORMALIZATION_LOWER_BOUND
    upper_bound: float = DEFAULT_SCORE_NORMALIZATION_UPPER_BOUND

    reference_mode: str = DEFAULT_SCORE_REFERENCE_MODE
    reference_value: Optional[float] = None

    epsilon: float = DEFAULT_SCORE_NORMALIZATION_EPSILON
    clip: bool = DEFAULT_SCORE_NORMALIZATION_CLIP

    assign_ranks: bool = DEFAULT_SCORE_NORMALIZATION_ASSIGN_RANKS
    preserve_pose_result: bool = (
        DEFAULT_SCORE_NORMALIZATION_PRESERVE_POSE_RESULT
    )
    validate_result: bool = (
        DEFAULT_SCORE_NORMALIZATION_VALIDATE_RESULT
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize score-normalization options.
        """

        method = normalize_score_normalization_method(
            self.method
        )
        direction = normalize_score_direction(
            self.direction
        )
        degenerate_policy = normalize_score_degenerate_policy(
            self.degenerate_policy
        )
        ranking_mode = (
            normalize_score_normalization_ranking_mode(
                self.ranking_mode
            )
        )
        reference_mode = normalize_score_reference_mode(
            self.reference_mode
        )

        lower_bound = float(
            _coerce_finite_score_value(
                self.lower_bound,
                name="ScoreNormalizationOptions.lower_bound",
            )
        )
        upper_bound = float(
            _coerce_finite_score_value(
                self.upper_bound,
                name="ScoreNormalizationOptions.upper_bound",
            )
        )

        if upper_bound <= lower_bound:
            raise ScoreNormalizationInputError(
                "upper_bound must be greater than lower_bound."
            )

        epsilon = float(
            _coerce_finite_score_value(
                self.epsilon,
                name="ScoreNormalizationOptions.epsilon",
            )
        )

        if epsilon <= 0.0:
            raise ScoreNormalizationInputError(
                "epsilon must be greater than zero."
            )

        reference_value = (
            None
            if self.reference_value is None
            else float(
                _coerce_finite_score_value(
                    self.reference_value,
                    name="ScoreNormalizationOptions.reference_value",
                )
            )
        )

        if (
            reference_mode == SCORE_REFERENCE_EXPLICIT
            and reference_value is None
            and method
            in {
                SCORE_NORMALIZATION_REFERENCE_RATIO,
                SCORE_NORMALIZATION_REFERENCE_DIFFERENCE,
            }
        ):
            raise ScoreNormalizationReferenceError(
                "An explicit reference_value is required when "
                "reference_mode='explicit'."
            )

        object.__setattr__(self, "method", method)
        object.__setattr__(self, "direction", direction)
        object.__setattr__(
            self,
            "degenerate_policy",
            degenerate_policy,
        )
        object.__setattr__(
            self,
            "ranking_mode",
            ranking_mode,
        )
        object.__setattr__(
            self,
            "reference_mode",
            reference_mode,
        )
        object.__setattr__(
            self,
            "reference_value",
            reference_value,
        )
        object.__setattr__(
            self,
            "lower_bound",
            lower_bound,
        )
        object.__setattr__(
            self,
            "upper_bound",
            upper_bound,
        )
        object.__setattr__(
            self,
            "epsilon",
            epsilon,
        )

        for field_name in (
            "clip",
            "assign_ranks",
            "preserve_pose_result",
            "validate_result",
        ):
            object.__setattr__(
                self,
                field_name,
                bool(getattr(self, field_name)),
            )

        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def midpoint(self) -> float:
        """
        Return the midpoint of the configured output interval.
        """

        return (
            self.lower_bound
            + self.upper_bound
        ) / 2.0

    @property
    def output_range(self) -> float:
        """
        Return the width of the configured output interval.
        """

        return self.upper_bound - self.lower_bound

    def with_updates(
        self,
        **changes: Any,
    ) -> "ScoreNormalizationOptions":
        """
        Return a validated options copy.
        """

        return replace(self, **changes)

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable options representation.
        """

        result: Dict[str, Any] = {
            "method": self.method,
            "direction": self.direction,
            "degenerate_policy": self.degenerate_policy,
            "ranking_mode": self.ranking_mode,
            "lower_bound": self.lower_bound,
            "upper_bound": self.upper_bound,
            "midpoint": self.midpoint,
            "reference_mode": self.reference_mode,
            "reference_value": self.reference_value,
            "epsilon": self.epsilon,
            "clip": self.clip,
            "assign_ranks": self.assign_ranks,
            "preserve_pose_result": self.preserve_pose_result,
            "validate_result": self.validate_result,
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


DEFAULT_SCORE_NORMALIZATION_OPTIONS: Final[
    ScoreNormalizationOptions
] = ScoreNormalizationOptions()


# -----------------------------------------------------------------------------
# 17.6. NormalizedPoseScore
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class NormalizedPoseScore:
    """
    Normalized score representation for one docking pose.
    """

    pose_id: str
    model_id: str
    ligand_id: str

    input_index: int

    raw_score: float
    oriented_score: float
    normalized_score: float

    rank: Optional[int] = None
    tied_rank: Optional[float] = None
    percentile: Optional[float] = None

    best: bool = False
    worst: bool = False
    tied: bool = False

    method: str = DEFAULT_SCORE_NORMALIZATION_METHOD
    direction: str = DEFAULT_SCORE_NORMALIZATION_DIRECTION

    pose_result: Optional[PoseScoringResult] = field(
        default=None,
        compare=False,
        hash=False,
        repr=False,
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize one normalized pose score.
        """

        input_index = int(self.input_index)

        if input_index < 0:
            raise ScoreNormalizationValidationError(
                "NormalizedPoseScore.input_index cannot be negative."
            )

        for field_name in (
            "raw_score",
            "oriented_score",
            "normalized_score",
        ):
            object.__setattr__(
                self,
                field_name,
                float(
                    _coerce_finite_score_value(
                        getattr(self, field_name),
                        name=f"NormalizedPoseScore.{field_name}",
                    )
                ),
            )

        rank = None if self.rank is None else int(self.rank)

        if rank is not None and rank < 1:
            raise ScoreNormalizationValidationError(
                "NormalizedPoseScore.rank must be positive or None."
            )

        tied_rank = (
            None
            if self.tied_rank is None
            else float(
                _coerce_finite_score_value(
                    self.tied_rank,
                    name="NormalizedPoseScore.tied_rank",
                )
            )
        )

        percentile = (
            None
            if self.percentile is None
            else float(
                _coerce_finite_score_value(
                    self.percentile,
                    name="NormalizedPoseScore.percentile",
                )
            )
        )

        if (
            percentile is not None
            and not 0.0 <= percentile <= 1.0
        ):
            raise ScoreNormalizationValidationError(
                "percentile must be between 0.0 and 1.0."
            )

        if (
            self.pose_result is not None
            and not isinstance(
                self.pose_result,
                PoseScoringResult,
            )
        ):
            raise ScoreNormalizationValidationError(
                "pose_result must be a PoseScoringResult or None."
            )

        object.__setattr__(
            self,
            "pose_id",
            _coerce_identifier(self.pose_id),
        )
        object.__setattr__(
            self,
            "model_id",
            _coerce_identifier(self.model_id),
        )
        object.__setattr__(
            self,
            "ligand_id",
            _coerce_identifier(self.ligand_id),
        )
        object.__setattr__(
            self,
            "input_index",
            input_index,
        )
        object.__setattr__(
            self,
            "rank",
            rank,
        )
        object.__setattr__(
            self,
            "tied_rank",
            tied_rank,
        )
        object.__setattr__(
            self,
            "percentile",
            percentile,
        )
        object.__setattr__(
            self,
            "best",
            bool(self.best),
        )
        object.__setattr__(
            self,
            "worst",
            bool(self.worst),
        )
        object.__setattr__(
            self,
            "tied",
            bool(self.tied),
        )
        object.__setattr__(
            self,
            "method",
            normalize_score_normalization_method(
                self.method
            ),
        )
        object.__setattr__(
            self,
            "direction",
            normalize_score_direction(
                self.direction
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
        include_pose_result: bool = False,
    ) -> Dict[str, Any]:
        """
        Return a serializable normalized pose score.
        """

        result: Dict[str, Any] = {
            "pose_id": self.pose_id,
            "model_id": self.model_id,
            "ligand_id": self.ligand_id,
            "input_index": self.input_index,
            "raw_score": self.raw_score,
            "oriented_score": self.oriented_score,
            "normalized_score": self.normalized_score,
            "rank": self.rank,
            "tied_rank": self.tied_rank,
            "percentile": self.percentile,
            "best": self.best,
            "worst": self.worst,
            "tied": self.tied,
            "method": self.method,
            "direction": self.direction,
        }

        if include_pose_result:
            result["pose_result"] = (
                None
                if self.pose_result is None
                else self.pose_result.to_dict(
                    include_metadata=include_metadata,
                    include_collection_result=False,
                )
            )

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 17.7. ScoreNormalizationResult
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ScoreNormalizationResult:
    """
    Result of normalizing a collection of pose scores.
    """

    status: str
    method: str
    direction: str

    scores: Tuple[NormalizedPoseScore, ...]
    statistics: ScoreNormalizationStatistics

    best_pose_ids: Tuple[str, ...] = field(
        default_factory=tuple
    )
    worst_pose_ids: Tuple[str, ...] = field(
        default_factory=tuple
    )

    message: str = ""

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize the complete normalization result.
        """

        scores = tuple(self.scores)

        for score in scores:
            if not isinstance(score, NormalizedPoseScore):
                raise ScoreNormalizationValidationError(
                    "scores must contain only NormalizedPoseScore instances."
                )

        if not isinstance(
            self.statistics,
            ScoreNormalizationStatistics,
        ):
            raise ScoreNormalizationValidationError(
                "statistics must be a ScoreNormalizationStatistics instance."
            )

        object.__setattr__(
            self,
            "status",
            normalize_score_normalization_status(
                self.status
            ),
        )
        object.__setattr__(
            self,
            "method",
            normalize_score_normalization_method(
                self.method
            ),
        )
        object.__setattr__(
            self,
            "direction",
            normalize_score_direction(
                self.direction
            ),
        )
        object.__setattr__(
            self,
            "scores",
            scores,
        )
        object.__setattr__(
            self,
            "best_pose_ids",
            tuple(
                _coerce_identifier(value)
                for value in self.best_pose_ids
            ),
        )
        object.__setattr__(
            self,
            "worst_pose_ids",
            tuple(
                _coerce_identifier(value)
                for value in self.worst_pose_ids
            ),
        )
        object.__setattr__(
            self,
            "message",
            _coerce_optional_text(self.message),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def successful(self) -> bool:
        """
        Return whether normalized scores were produced.
        """

        return bool(self.scores)

    @property
    def best_scores(self) -> Tuple[NormalizedPoseScore, ...]:
        """
        Return all poses sharing the best normalized result.
        """

        return tuple(
            score
            for score in self.scores
            if score.best
        )

    @property
    def worst_scores(self) -> Tuple[NormalizedPoseScore, ...]:
        """
        Return all poses sharing the worst normalized result.
        """

        return tuple(
            score
            for score in self.scores
            if score.worst
        )

    def require_scores(
        self,
    ) -> Tuple[NormalizedPoseScore, ...]:
        """
        Return normalized scores or raise if none exist.
        """

        if not self.scores:
            raise ScoreNormalizationError(
                self.message
                or "No normalized pose scores are available."
            )

        return self.scores

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
        include_pose_results: bool = False,
    ) -> Dict[str, Any]:
        """
        Return a serializable normalization result.
        """

        result: Dict[str, Any] = {
            "status": self.status,
            "successful": self.successful,
            "method": self.method,
            "direction": self.direction,
            "message": self.message,
            "statistics": self.statistics.to_dict(
                include_metadata=include_metadata
            ),
            "scores": [
                score.to_dict(
                    include_metadata=include_metadata,
                    include_pose_result=include_pose_results,
                )
                for score in self.scores
            ],
            "best_pose_ids": list(self.best_pose_ids),
            "worst_pose_ids": list(self.worst_pose_ids),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 17.8. Quantile and descriptive-statistics helpers
# -----------------------------------------------------------------------------

def score_quantile(
    values: Sequence[float],
    probability: Number,
) -> float:
    """
    Calculate a deterministic linearly interpolated quantile.

    This implementation does not depend on NumPy.
    """

    normalized_values = tuple(
        sorted(
            float(
                _coerce_finite_score_value(
                    value,
                    name="quantile value",
                )
            )
            for value in values
        )
    )

    if not normalized_values:
        raise ScoreNormalizationInputError(
            "At least one value is required to calculate a quantile."
        )

    probability_value = float(
        _coerce_finite_score_value(
            probability,
            name="quantile probability",
        )
    )

    if not 0.0 <= probability_value <= 1.0:
        raise ScoreNormalizationInputError(
            "Quantile probability must be between 0.0 and 1.0."
        )

    if len(normalized_values) == 1:
        return normalized_values[0]

    position = probability_value * (
        len(normalized_values) - 1
    )
    lower_index = int(math.floor(position))
    upper_index = int(math.ceil(position))

    if lower_index == upper_index:
        return normalized_values[lower_index]

    fraction = position - lower_index

    return float(
        normalized_values[lower_index]
        + (
            normalized_values[upper_index]
            - normalized_values[lower_index]
        )
        * fraction
    )


def score_median_absolute_deviation(
    values: Sequence[float],
    *,
    center: Optional[float] = None,
) -> float:
    """
    Calculate the unscaled median absolute deviation.
    """

    normalized_values = tuple(
        float(
            _coerce_finite_score_value(
                value,
                name="median absolute deviation value",
            )
        )
        for value in values
    )

    if not normalized_values:
        raise ScoreNormalizationInputError(
            "At least one value is required."
        )

    resolved_center = (
        float(statistics.median(normalized_values))
        if center is None
        else float(
            _coerce_finite_score_value(
                center,
                name="median absolute deviation center",
            )
        )
    )

    deviations = tuple(
        abs(value - resolved_center)
        for value in normalized_values
    )

    return float(statistics.median(deviations))


def resolve_score_reference_value(
    values: Sequence[float],
    *,
    options: ScoreNormalizationOptions,
) -> Optional[float]:
    """
    Resolve the score used by reference-based normalization.
    """

    if not values:
        return None

    mode = options.reference_mode

    if mode == SCORE_REFERENCE_EXPLICIT:
        if options.reference_value is None:
            raise ScoreNormalizationReferenceError(
                "An explicit reference value is required."
            )

        return options.reference_value

    if mode == SCORE_REFERENCE_MEAN:
        return float(statistics.fmean(values))

    if mode == SCORE_REFERENCE_MEDIAN:
        return float(statistics.median(values))

    if mode == SCORE_REFERENCE_MINIMUM:
        return float(min(values))

    if mode == SCORE_REFERENCE_MAXIMUM:
        return float(max(values))

    if mode == SCORE_REFERENCE_FIRST:
        return float(values[0])

    raise ScoreNormalizationReferenceError(
        f"Unsupported reference mode: {mode!r}."
    )


def build_score_normalization_statistics(
    values: Sequence[float],
    *,
    options: ScoreNormalizationOptions = (
        DEFAULT_SCORE_NORMALIZATION_OPTIONS
    ),
) -> ScoreNormalizationStatistics:
    """
    Build descriptive statistics for pose-score normalization.
    """

    normalized_values = tuple(
        float(
            _coerce_finite_score_value(
                value,
                name="pose normalization value",
            )
        )
        for value in values
    )

    if not normalized_values:
        return ScoreNormalizationStatistics(
            count=0,
            minimum=None,
            maximum=None,
            mean=None,
            median=None,
            population_variance=None,
            population_standard_deviation=None,
            first_quartile=None,
            third_quartile=None,
            interquartile_range=None,
            median_absolute_deviation=None,
            maximum_absolute_value=None,
            value_range=None,
            reference_value=None,
            degenerate=True,
        )

    minimum = float(min(normalized_values))
    maximum = float(max(normalized_values))
    mean = float(statistics.fmean(normalized_values))
    median = float(statistics.median(normalized_values))

    population_variance = float(
        statistics.pvariance(normalized_values)
    )
    population_standard_deviation = float(
        math.sqrt(population_variance)
    )

    first_quartile = score_quantile(
        normalized_values,
        0.25,
    )
    third_quartile = score_quantile(
        normalized_values,
        0.75,
    )
    interquartile_range = (
        third_quartile - first_quartile
    )
    median_absolute_deviation = (
        score_median_absolute_deviation(
            normalized_values,
            center=median,
        )
    )

    maximum_absolute_value = float(
        max(abs(value) for value in normalized_values)
    )
    value_range = maximum - minimum

    reference_value = resolve_score_reference_value(
        normalized_values,
        options=options,
    )

    degenerate = (
        value_range <= options.epsilon
    )

    return ScoreNormalizationStatistics(
        count=len(normalized_values),
        minimum=minimum,
        maximum=maximum,
        mean=mean,
        median=median,
        population_variance=population_variance,
        population_standard_deviation=(
            population_standard_deviation
        ),
        first_quartile=first_quartile,
        third_quartile=third_quartile,
        interquartile_range=interquartile_range,
        median_absolute_deviation=(
            median_absolute_deviation
        ),
        maximum_absolute_value=(
            maximum_absolute_value
        ),
        value_range=value_range,
        reference_value=reference_value,
        degenerate=degenerate,
    )


# -----------------------------------------------------------------------------
# 17.9. Direction transformation
# -----------------------------------------------------------------------------

def orient_score_for_comparison(
    score: Number,
    *,
    direction: str = DEFAULT_SCORE_NORMALIZATION_DIRECTION,
) -> float:
    """
    Transform a score so that larger oriented values always mean better.

    The original score is preserved separately.
    """

    value = float(
        _coerce_finite_score_value(
            score,
            name="score for direction transformation",
        )
    )
    normalized_direction = normalize_score_direction(
        direction
    )

    if normalized_direction == SCORE_DIRECTION_HIGHER_IS_BETTER:
        return value

    if normalized_direction == SCORE_DIRECTION_LOWER_IS_BETTER:
        return -value

    if normalized_direction == SCORE_DIRECTION_ABSOLUTE_IS_BETTER:
        return abs(value)

    if normalized_direction == SCORE_DIRECTION_ABSOLUTE_IS_WORSE:
        return -abs(value)

    raise ScoreNormalizationInputError(
        f"Unsupported score direction: {normalized_direction!r}."
    )


def orient_score_collection(
    values: Iterable[Number],
    *,
    direction: str = DEFAULT_SCORE_NORMALIZATION_DIRECTION,
) -> Tuple[float, ...]:
    """
    Orient a collection so that higher values always represent better scores.
    """

    return tuple(
        orient_score_for_comparison(
            value,
            direction=direction,
        )
        for value in values
    )


# -----------------------------------------------------------------------------
# 17.10. Degenerate normalization
# -----------------------------------------------------------------------------

def resolve_degenerate_normalized_values(
    values: Sequence[float],
    *,
    options: ScoreNormalizationOptions,
) -> Tuple[float, ...]:
    """
    Resolve normalized values when the input distribution is degenerate.
    """

    policy = options.degenerate_policy

    if not values:
        return ()

    if policy == SCORE_DEGENERATE_ZERO:
        return tuple(0.0 for _ in values)

    if policy == SCORE_DEGENERATE_MIDPOINT:
        return tuple(
            options.midpoint
            for _ in values
        )

    if policy == SCORE_DEGENERATE_PRESERVE:
        return tuple(float(value) for value in values)

    if policy == SCORE_DEGENERATE_RANK_EQUAL:
        return tuple(0.5 for _ in values)

    if policy == SCORE_DEGENERATE_ERROR:
        raise ScoreNormalizationDegenerateError(
            "The score distribution is degenerate."
        )

    raise ScoreNormalizationDegenerateError(
        f"Unsupported degenerate policy: {policy!r}."
    )


# -----------------------------------------------------------------------------
# 17.11. Core normalization algorithms
# -----------------------------------------------------------------------------

def normalize_min_max_values(
    values: Sequence[float],
    *,
    lower_bound: float = 0.0,
    upper_bound: float = 1.0,
    epsilon: float = DEFAULT_SCORE_NORMALIZATION_EPSILON,
) -> Tuple[float, ...]:
    """
    Apply min-max normalization to a non-degenerate sequence.
    """

    if not values:
        return ()

    minimum = min(values)
    maximum = max(values)
    denominator = maximum - minimum

    if denominator <= epsilon:
        raise ScoreNormalizationDegenerateError(
            "Min-max normalization requires a non-zero score range."
        )

    output_range = upper_bound - lower_bound

    return tuple(
        lower_bound
        + (
            (value - minimum)
            / denominator
        )
        * output_range
        for value in values
    )


def normalize_symmetric_min_max_values(
    values: Sequence[float],
    *,
    epsilon: float = DEFAULT_SCORE_NORMALIZATION_EPSILON,
) -> Tuple[float, ...]:
    """
    Map a non-degenerate score collection to [-1, 1].
    """

    return normalize_min_max_values(
        values,
        lower_bound=-1.0,
        upper_bound=1.0,
        epsilon=epsilon,
    )


def normalize_z_score_values(
    values: Sequence[float],
    *,
    epsilon: float = DEFAULT_SCORE_NORMALIZATION_EPSILON,
) -> Tuple[float, ...]:
    """
    Apply population z-score normalization.
    """

    if not values:
        return ()

    mean = statistics.fmean(values)
    standard_deviation = math.sqrt(
        statistics.pvariance(values)
    )

    if standard_deviation <= epsilon:
        raise ScoreNormalizationDegenerateError(
            "Z-score normalization requires non-zero variance."
        )

    return tuple(
        (value - mean) / standard_deviation
        for value in values
    )


def normalize_robust_z_score_values(
    values: Sequence[float],
    *,
    epsilon: float = DEFAULT_SCORE_NORMALIZATION_EPSILON,
) -> Tuple[float, ...]:
    """
    Apply robust z-score normalization using median and MAD.

    The factor 1.4826 makes MAD comparable to standard deviation
    for normally distributed values.
    """

    if not values:
        return ()

    median = float(statistics.median(values))
    mad = score_median_absolute_deviation(
        values,
        center=median,
    )
    scaled_mad = 1.4826 * mad

    if scaled_mad <= epsilon:
        raise ScoreNormalizationDegenerateError(
            "Robust z-score normalization requires non-zero MAD."
        )

    return tuple(
        (value - median) / scaled_mad
        for value in values
    )


def average_rank_values(
    values: Sequence[float],
    *,
    higher_is_better: bool = True,
    epsilon: float = DEFAULT_SCORE_NORMALIZATION_EPSILON,
) -> Tuple[float, ...]:
    """
    Calculate average ranks with deterministic tie handling.

    Rank 1 always represents the best value.
    """

    if not values:
        return ()

    indexed = list(enumerate(values))

    indexed.sort(
        key=lambda item: (
            -item[1]
            if higher_is_better
            else item[1],
            item[0],
        )
    )

    ranks = [0.0] * len(values)
    start = 0

    while start < len(indexed):
        end = start + 1
        reference_value = indexed[start][1]

        while (
            end < len(indexed)
            and abs(
                indexed[end][1]
                - reference_value
            )
            <= epsilon
        ):
            end += 1

        first_rank = start + 1
        last_rank = end
        average_rank = (
            first_rank + last_rank
        ) / 2.0

        for position in range(start, end):
            original_index = indexed[position][0]
            ranks[original_index] = average_rank

        start = end

    return tuple(ranks)


def normalize_percentile_rank_values(
    values: Sequence[float],
    *,
    epsilon: float = DEFAULT_SCORE_NORMALIZATION_EPSILON,
) -> Tuple[float, ...]:
    """
    Convert scores to percentiles in [0, 1].

    The best value receives 1.0 and the worst receives 0.0.
    Ties receive the same average-rank percentile.
    """

    if not values:
        return ()

    if len(values) == 1:
        return (1.0,)

    ranks = average_rank_values(
        values,
        higher_is_better=True,
        epsilon=epsilon,
    )
    denominator = len(values) - 1

    return tuple(
        1.0 - (
            (rank - 1.0)
            / denominator
        )
        for rank in ranks
    )


def normalize_reference_ratio_values(
    values: Sequence[float],
    *,
    reference_value: float,
    epsilon: float = DEFAULT_SCORE_NORMALIZATION_EPSILON,
) -> Tuple[float, ...]:
    """
    Normalize scores by division through a reference value.
    """

    reference = float(
        _coerce_finite_score_value(
            reference_value,
            name="reference value",
        )
    )

    if abs(reference) <= epsilon:
        raise ScoreNormalizationReferenceError(
            "Reference-ratio normalization requires a non-zero "
            "reference value."
        )

    return tuple(
        value / reference
        for value in values
    )


def normalize_reference_difference_values(
    values: Sequence[float],
    *,
    reference_value: float,
) -> Tuple[float, ...]:
    """
    Normalize scores as differences from a reference value.
    """

    reference = float(
        _coerce_finite_score_value(
            reference_value,
            name="reference value",
        )
    )

    return tuple(
        value - reference
        for value in values
    )


def normalize_max_absolute_values(
    values: Sequence[float],
    *,
    epsilon: float = DEFAULT_SCORE_NORMALIZATION_EPSILON,
) -> Tuple[float, ...]:
    """
    Normalize values by the largest absolute score.
    """

    if not values:
        return ()

    maximum_absolute_value = max(
        abs(value)
        for value in values
    )

    if maximum_absolute_value <= epsilon:
        raise ScoreNormalizationDegenerateError(
            "Maximum-absolute normalization requires at least one "
            "non-zero value."
        )

    return tuple(
        value / maximum_absolute_value
        for value in values
    )


def clip_normalized_score(
    value: Number,
    *,
    lower_bound: Number,
    upper_bound: Number,
) -> float:
    """
    Clip a score to a closed numerical interval.
    """

    normalized_value = float(
        _coerce_finite_score_value(
            value,
            name="normalized score",
        )
    )
    lower = float(lower_bound)
    upper = float(upper_bound)

    return min(
        max(normalized_value, lower),
        upper,
    )


def normalize_score_values(
    values: Sequence[Number],
    *,
    options: ScoreNormalizationOptions = (
        DEFAULT_SCORE_NORMALIZATION_OPTIONS
    ),
) -> Tuple[
    Tuple[float, ...],
    ScoreNormalizationStatistics,
]:
    """
    Normalize an arbitrary numerical score sequence.

    Direction transformation is applied before the selected method.
    """

    validate_score_normalization_options(options)

    raw_values = tuple(
        float(
            _coerce_finite_score_value(
                value,
                name="score normalization input",
            )
        )
        for value in values
    )

    oriented_values = orient_score_collection(
        raw_values,
        direction=options.direction,
    )

    statistics_result = (
        build_score_normalization_statistics(
            oriented_values,
            options=options,
        )
    )

    if not oriented_values:
        return (), statistics_result

    method = options.method

    if method == SCORE_NORMALIZATION_NONE:
        normalized_values = oriented_values

    else:
        try:
            if method == SCORE_NORMALIZATION_MIN_MAX:
                normalized_values = normalize_min_max_values(
                    oriented_values,
                    lower_bound=options.lower_bound,
                    upper_bound=options.upper_bound,
                    epsilon=options.epsilon,
                )

            elif method == SCORE_NORMALIZATION_SYMMETRIC_MIN_MAX:
                normalized_values = (
                    normalize_symmetric_min_max_values(
                        oriented_values,
                        epsilon=options.epsilon,
                    )
                )

            elif method == SCORE_NORMALIZATION_Z_SCORE:
                normalized_values = normalize_z_score_values(
                    oriented_values,
                    epsilon=options.epsilon,
                )

            elif method == SCORE_NORMALIZATION_ROBUST_Z_SCORE:
                normalized_values = (
                    normalize_robust_z_score_values(
                        oriented_values,
                        epsilon=options.epsilon,
                    )
                )

            elif method == SCORE_NORMALIZATION_PERCENTILE_RANK:
                normalized_values = (
                    normalize_percentile_rank_values(
                        oriented_values,
                        epsilon=options.epsilon,
                    )
                )

            elif method == SCORE_NORMALIZATION_REFERENCE_RATIO:
                reference_value = (
                    statistics_result.reference_value
                )

                if reference_value is None:
                    raise ScoreNormalizationReferenceError(
                        "No reference value could be resolved."
                    )

                normalized_values = (
                    normalize_reference_ratio_values(
                        oriented_values,
                        reference_value=reference_value,
                        epsilon=options.epsilon,
                    )
                )

            elif (
                method
                == SCORE_NORMALIZATION_REFERENCE_DIFFERENCE
            ):
                reference_value = (
                    statistics_result.reference_value
                )

                if reference_value is None:
                    raise ScoreNormalizationReferenceError(
                        "No reference value could be resolved."
                    )

                normalized_values = (
                    normalize_reference_difference_values(
                        oriented_values,
                        reference_value=reference_value,
                    )
                )

            elif method == SCORE_NORMALIZATION_MAX_ABSOLUTE:
                normalized_values = (
                    normalize_max_absolute_values(
                        oriented_values,
                        epsilon=options.epsilon,
                    )
                )

            else:
                raise ScoreNormalizationMethodError(
                    f"Unsupported normalization method: {method!r}."
                )

        except ScoreNormalizationDegenerateError:
            normalized_values = (
                resolve_degenerate_normalized_values(
                    oriented_values,
                    options=options,
                )
            )

    if options.clip:
        normalized_values = tuple(
            clip_normalized_score(
                value,
                lower_bound=options.lower_bound,
                upper_bound=options.upper_bound,
            )
            for value in normalized_values
        )

    return (
        tuple(float(value) for value in normalized_values),
        statistics_result,
    )


# -----------------------------------------------------------------------------
# 17.12. Pose-result materialization
# -----------------------------------------------------------------------------

def materialize_pose_scoring_results(
    values: Any,
) -> Tuple[PoseScoringResult, ...]:
    """
    Convert a pose-scoring result or iterable into an immutable tuple.
    """

    if values is None:
        return ()

    if isinstance(values, PoseScoringResult):
        return (values,)

    if isinstance(
        values,
        (
            str,
            bytes,
            bytearray,
            Mapping,
        ),
    ):
        raise ScoreNormalizationInputError(
            "Expected PoseScoringResult objects, not a string or mapping."
        )

    try:
        normalized_values = tuple(values)
    except TypeError as exc:
        raise ScoreNormalizationInputError(
            "Pose normalization input must be iterable."
        ) from exc

    for value in normalized_values:
        if not isinstance(value, PoseScoringResult):
            raise ScoreNormalizationInputError(
                "All normalization inputs must be PoseScoringResult "
                "instances."
            )

    return normalized_values


# -----------------------------------------------------------------------------
# 17.13. Ranking
# -----------------------------------------------------------------------------

def normalized_pose_ranking_value(
    score: NormalizedPoseScore,
    *,
    mode: str = DEFAULT_SCORE_NORMALIZATION_RANKING_MODE,
) -> float:
    """
    Return the metric used to rank one normalized pose.
    """

    normalized_mode = (
        normalize_score_normalization_ranking_mode(
            mode
        )
    )

    if normalized_mode == SCORE_RANKING_NORMALIZED_SCORE:
        return score.normalized_score

    if normalized_mode == SCORE_RANKING_RAW_SCORE:
        return score.oriented_score

    if (
        normalized_mode
        == SCORE_RANKING_ABSOLUTE_NORMALIZED_SCORE
    ):
        return abs(score.normalized_score)

    if normalized_mode == SCORE_RANKING_ABSOLUTE_RAW_SCORE:
        return abs(score.oriented_score)

    raise ScoreNormalizationValidationError(
        f"Unsupported ranking mode: {normalized_mode!r}."
    )


def assign_normalized_pose_ranks(
    scores: Sequence[NormalizedPoseScore],
    *,
    ranking_mode: str = (
        DEFAULT_SCORE_NORMALIZATION_RANKING_MODE
    ),
    epsilon: float = DEFAULT_SCORE_NORMALIZATION_EPSILON,
) -> Tuple[NormalizedPoseScore, ...]:
    """
    Assign competition ranks and average tied ranks.

    All ranking metrics are treated as higher-is-better because score
    direction was already resolved during orientation.
    """

    if not scores:
        return ()

    normalized_mode = (
        normalize_score_normalization_ranking_mode(
            ranking_mode
        )
    )

    values = tuple(
        normalized_pose_ranking_value(
            score,
            mode=normalized_mode,
        )
        for score in scores
    )

    average_ranks = average_rank_values(
        values,
        higher_is_better=True,
        epsilon=epsilon,
    )

    ordered_indices = sorted(
        range(len(scores)),
        key=lambda index: (
            -values[index],
            scores[index].pose_id,
            scores[index].input_index,
        ),
    )

    competition_ranks: Dict[int, int] = {}
    current_rank = 1

    for position, index in enumerate(ordered_indices):
        if position == 0:
            current_rank = 1

        else:
            previous_index = ordered_indices[position - 1]

            if (
                abs(
                    values[index]
                    - values[previous_index]
                )
                > epsilon
            ):
                current_rank = position + 1

        competition_ranks[index] = current_rank

    best_value = max(values)
    worst_value = min(values)

    value_counts = {
        index: sum(
            abs(value - values[index]) <= epsilon
            for value in values
        )
        for index in range(len(values))
    }

    denominator = max(1, len(scores) - 1)

    ranked = tuple(
        replace(
            score,
            rank=competition_ranks[index],
            tied_rank=average_ranks[index],
            percentile=(
                1.0
                if len(scores) == 1
                else 1.0
                - (
                    average_ranks[index] - 1.0
                )
                / denominator
            ),
            best=(
                abs(values[index] - best_value)
                <= epsilon
            ),
            worst=(
                abs(values[index] - worst_value)
                <= epsilon
            ),
            tied=value_counts[index] > 1,
            metadata={
                **dict(score.metadata),
                "ranking_mode": normalized_mode,
                "ranking_value": values[index],
            },
        )
        for index, score in enumerate(scores)
    )

    return tuple(
        sorted(
            ranked,
            key=lambda score: (
                score.rank
                if score.rank is not None
                else math.inf,
                score.pose_id,
                score.input_index,
            ),
        )
    )


# -----------------------------------------------------------------------------
# 17.14. Main pose normalization
# -----------------------------------------------------------------------------

def normalize_pose_scores(
    pose_results: Any,
    *,
    options: ScoreNormalizationOptions = (
        DEFAULT_SCORE_NORMALIZATION_OPTIONS
    ),
) -> ScoreNormalizationResult:
    """
    Normalize total scores from multiple PoseScoringResult objects.
    """

    validate_score_normalization_options(options)

    normalized_pose_results = (
        materialize_pose_scoring_results(
            pose_results
        )
    )

    if not normalized_pose_results:
        statistics_result = (
            build_score_normalization_statistics(
                (),
                options=options,
            )
        )

        return ScoreNormalizationResult(
            status=SCORE_NORMALIZATION_STATUS_EMPTY,
            method=options.method,
            direction=options.direction,
            scores=(),
            statistics=statistics_result,
            message="No pose scores were supplied for normalization.",
            metadata={
                "options": options.to_dict(
                    include_metadata=True
                ),
            },
        )

    for pose_result in normalized_pose_results:
        validate_pose_scoring_result(pose_result)

    raw_values = tuple(
        pose_result.final_score
        for pose_result in normalized_pose_results
    )
    oriented_values = orient_score_collection(
        raw_values,
        direction=options.direction,
    )

    normalized_values, statistics_result = (
        normalize_score_values(
            raw_values,
            options=options,
        )
    )

    normalized_scores = tuple(
        NormalizedPoseScore(
            pose_id=pose_result.pose_id,
            model_id=pose_result.model_id,
            ligand_id=pose_result.ligand_id,
            input_index=index,
            raw_score=raw_value,
            oriented_score=oriented_value,
            normalized_score=normalized_value,
            method=options.method,
            direction=options.direction,
            pose_result=(
                pose_result
                if options.preserve_pose_result
                else None
            ),
            metadata={
                "pose_status": pose_result.status,
                "interaction_count": (
                    pose_result.summary.interaction_count
                ),
                "residue_count": (
                    pose_result.summary.residue_count
                ),
                "pose_polarity": (
                    pose_result.summary.pose_polarity
                ),
            },
        )
        for (
            index,
            (
                pose_result,
                raw_value,
                oriented_value,
                normalized_value,
            ),
        )
        in enumerate(
            zip(
                normalized_pose_results,
                raw_values,
                oriented_values,
                normalized_values,
            )
        )
    )

    if options.assign_ranks:
        normalized_scores = assign_normalized_pose_ranks(
            normalized_scores,
            ranking_mode=options.ranking_mode,
            epsilon=options.epsilon,
        )

    best_pose_ids = tuple(
        score.pose_id
        for score in normalized_scores
        if score.best
    )
    worst_pose_ids = tuple(
        score.pose_id
        for score in normalized_scores
        if score.worst
    )

    partial_pose_count = sum(
        pose_result.status
        == POSE_SCORING_STATUS_PARTIAL
        for pose_result in normalized_pose_results
    )

    failed_pose_count = sum(
        pose_result.status
        in {
            POSE_SCORING_STATUS_FAILED,
            POSE_SCORING_STATUS_EMPTY,
        }
        for pose_result in normalized_pose_results
    )

    if statistics_result.degenerate:
        status = SCORE_NORMALIZATION_STATUS_DEGENERATE
        message = (
            "Pose scores were processed using the configured "
            "degenerate-distribution policy."
        )

    elif partial_pose_count or failed_pose_count:
        status = SCORE_NORMALIZATION_STATUS_PARTIAL
        message = (
            "Pose scores were normalized, but at least one input "
            "pose was partial, empty or failed."
        )

    else:
        status = SCORE_NORMALIZATION_STATUS_NORMALIZED
        message = "Pose scores were normalized successfully."

    result = ScoreNormalizationResult(
        status=status,
        method=options.method,
        direction=options.direction,
        scores=normalized_scores,
        statistics=statistics_result,
        best_pose_ids=best_pose_ids,
        worst_pose_ids=worst_pose_ids,
        message=message,
        metadata={
            "ranking_mode": options.ranking_mode,
            "degenerate_policy": options.degenerate_policy,
            "partial_pose_count": partial_pose_count,
            "failed_pose_count": failed_pose_count,
            "input_count": len(normalized_pose_results),
            "output_bounds": (
                options.lower_bound,
                options.upper_bound,
            ),
        },
    )

    if options.validate_result:
        validate_score_normalization_result(result)

    return result


# -----------------------------------------------------------------------------
# 17.15. Normalization from numerical values
# -----------------------------------------------------------------------------

def normalize_raw_pose_scores(
    scores: Iterable[Number],
    *,
    pose_ids: Optional[Iterable[str]] = None,
    options: ScoreNormalizationOptions = (
        DEFAULT_SCORE_NORMALIZATION_OPTIONS
    ),
) -> ScoreNormalizationResult:
    """
    Normalize raw numerical pose scores without PoseScoringResult objects.
    """

    raw_scores = tuple(
        float(
            _coerce_finite_score_value(
                value,
                name="raw pose score",
            )
        )
        for value in scores
    )

    if pose_ids is None:
        normalized_pose_ids = tuple(
            f"pose_{index + 1}"
            for index in range(len(raw_scores))
        )
    else:
        normalized_pose_ids = tuple(
            _coerce_identifier(value)
            for value in pose_ids
        )

        if len(normalized_pose_ids) != len(raw_scores):
            raise ScoreNormalizationInputError(
                "pose_ids and scores must have the same length."
            )

    oriented_values = orient_score_collection(
        raw_scores,
        direction=options.direction,
    )
    normalized_values, statistics_result = normalize_score_values(
        raw_scores,
        options=options,
    )

    normalized_scores = tuple(
        NormalizedPoseScore(
            pose_id=pose_id or f"pose_{index + 1}",
            model_id="",
            ligand_id="",
            input_index=index,
            raw_score=raw_score,
            oriented_score=oriented_score,
            normalized_score=normalized_score,
            method=options.method,
            direction=options.direction,
        )
        for index, (
            pose_id,
            raw_score,
            oriented_score,
            normalized_score,
        ) in enumerate(
            zip(
                normalized_pose_ids,
                raw_scores,
                oriented_values,
                normalized_values,
            )
        )
    )

    if options.assign_ranks:
        normalized_scores = assign_normalized_pose_ranks(
            normalized_scores,
            ranking_mode=options.ranking_mode,
            epsilon=options.epsilon,
        )

    status = (
        SCORE_NORMALIZATION_STATUS_EMPTY
        if not normalized_scores
        else (
            SCORE_NORMALIZATION_STATUS_DEGENERATE
            if statistics_result.degenerate
            else SCORE_NORMALIZATION_STATUS_NORMALIZED
        )
    )

    result = ScoreNormalizationResult(
        status=status,
        method=options.method,
        direction=options.direction,
        scores=normalized_scores,
        statistics=statistics_result,
        best_pose_ids=tuple(
            score.pose_id
            for score in normalized_scores
            if score.best
        ),
        worst_pose_ids=tuple(
            score.pose_id
            for score in normalized_scores
            if score.worst
        ),
        message=(
            "Raw pose scores were normalized."
            if normalized_scores
            else "No raw pose scores were supplied."
        ),
    )

    if options.validate_result:
        validate_score_normalization_result(result)

    return result


# -----------------------------------------------------------------------------
# 17.16. Single-score transformation using fitted statistics
# -----------------------------------------------------------------------------

def normalize_score_with_statistics(
    value: Number,
    *,
    statistics_result: ScoreNormalizationStatistics,
    options: ScoreNormalizationOptions = (
        DEFAULT_SCORE_NORMALIZATION_OPTIONS
    ),
) -> float:
    """
    Normalize one new value using previously calculated statistics.

    Percentile-rank normalization is intentionally unsupported here because
    it requires the complete comparison distribution.
    """

    validate_score_normalization_statistics(
        statistics_result
    )
    validate_score_normalization_options(options)

    raw_value = float(
        _coerce_finite_score_value(
            value,
            name="new score value",
        )
    )
    oriented_value = orient_score_for_comparison(
        raw_value,
        direction=options.direction,
    )

    if statistics_result.count == 0:
        raise ScoreNormalizationInputError(
            "Cannot transform a score using empty statistics."
        )

    method = options.method

    if method == SCORE_NORMALIZATION_NONE:
        result = oriented_value

    elif method == SCORE_NORMALIZATION_MIN_MAX:
        if (
            statistics_result.minimum is None
            or statistics_result.maximum is None
            or statistics_result.value_range is None
        ):
            raise ScoreNormalizationValidationError(
                "Min-max statistics are incomplete."
            )

        if statistics_result.value_range <= options.epsilon:
            return resolve_degenerate_normalized_values(
                (oriented_value,),
                options=options,
            )[0]

        result = (
            options.lower_bound
            + (
                oriented_value
                - statistics_result.minimum
            )
            / statistics_result.value_range
            * options.output_range
        )

    elif method == SCORE_NORMALIZATION_SYMMETRIC_MIN_MAX:
        if (
            statistics_result.minimum is None
            or statistics_result.value_range is None
        ):
            raise ScoreNormalizationValidationError(
                "Symmetric min-max statistics are incomplete."
            )

        if statistics_result.value_range <= options.epsilon:
            return resolve_degenerate_normalized_values(
                (oriented_value,),
                options=options,
            )[0]

        result = (
            -1.0
            + 2.0
            * (
                oriented_value
                - statistics_result.minimum
            )
            / statistics_result.value_range
        )

    elif method == SCORE_NORMALIZATION_Z_SCORE:
        if (
            statistics_result.mean is None
            or statistics_result.population_standard_deviation is None
        ):
            raise ScoreNormalizationValidationError(
                "Z-score statistics are incomplete."
            )

        standard_deviation = (
            statistics_result.population_standard_deviation
        )

        if standard_deviation <= options.epsilon:
            return resolve_degenerate_normalized_values(
                (oriented_value,),
                options=options,
            )[0]

        result = (
            oriented_value - statistics_result.mean
        ) / standard_deviation

    elif method == SCORE_NORMALIZATION_ROBUST_Z_SCORE:
        if (
            statistics_result.median is None
            or statistics_result.median_absolute_deviation is None
        ):
            raise ScoreNormalizationValidationError(
                "Robust z-score statistics are incomplete."
            )

        scaled_mad = (
            1.4826
            * statistics_result.median_absolute_deviation
        )

        if scaled_mad <= options.epsilon:
            return resolve_degenerate_normalized_values(
                (oriented_value,),
                options=options,
            )[0]

        result = (
            oriented_value - statistics_result.median
        ) / scaled_mad

    elif method == SCORE_NORMALIZATION_REFERENCE_RATIO:
        if statistics_result.reference_value is None:
            raise ScoreNormalizationReferenceError(
                "Reference statistics are incomplete."
            )

        result = normalize_reference_ratio_values(
            (oriented_value,),
            reference_value=statistics_result.reference_value,
            epsilon=options.epsilon,
        )[0]

    elif method == SCORE_NORMALIZATION_REFERENCE_DIFFERENCE:
        if statistics_result.reference_value is None:
            raise ScoreNormalizationReferenceError(
                "Reference statistics are incomplete."
            )

        result = (
            oriented_value
            - statistics_result.reference_value
        )

    elif method == SCORE_NORMALIZATION_MAX_ABSOLUTE:
        maximum_absolute_value = (
            statistics_result.maximum_absolute_value
        )

        if (
            maximum_absolute_value is None
            or maximum_absolute_value <= options.epsilon
        ):
            return resolve_degenerate_normalized_values(
                (oriented_value,),
                options=options,
            )[0]

        result = (
            oriented_value
            / maximum_absolute_value
        )

    elif method == SCORE_NORMALIZATION_PERCENTILE_RANK:
        raise ScoreNormalizationMethodError(
            "Percentile-rank transformation requires the complete "
            "comparison distribution."
        )

    else:
        raise ScoreNormalizationMethodError(
            f"Unsupported normalization method: {method!r}."
        )

    if options.clip:
        result = clip_normalized_score(
            result,
            lower_bound=options.lower_bound,
            upper_bound=options.upper_bound,
        )

    return float(result)


# -----------------------------------------------------------------------------
# 17.17. Lookup and ranking helpers
# -----------------------------------------------------------------------------

def get_normalized_pose_score(
    result: ScoreNormalizationResult,
    pose_id: str,
) -> Optional[NormalizedPoseScore]:
    """
    Return the first normalized score matching a pose identifier.
    """

    validate_score_normalization_result(result)

    normalized_pose_id = _coerce_identifier(pose_id)

    for score in result.scores:
        if score.pose_id == normalized_pose_id:
            return score

    return None


def get_all_normalized_pose_scores(
    result: ScoreNormalizationResult,
    pose_id: str,
) -> Tuple[NormalizedPoseScore, ...]:
    """
    Return every normalized score matching a pose identifier.
    """

    validate_score_normalization_result(result)

    normalized_pose_id = _coerce_identifier(pose_id)

    return tuple(
        score
        for score in result.scores
        if score.pose_id == normalized_pose_id
    )


def best_normalized_pose_scores(
    result: ScoreNormalizationResult,
    *,
    limit: Optional[int] = None,
) -> Tuple[NormalizedPoseScore, ...]:
    """
    Return the best normalized pose scores in ranking order.
    """

    validate_score_normalization_result(result)

    if limit is None:
        return result.scores

    normalized_limit = max(0, int(limit))

    return result.scores[:normalized_limit]


def normalized_pose_score_mapping(
    result: ScoreNormalizationResult,
) -> Mapping[str, float]:
    """
    Return normalized scores keyed by pose identifier.

    When duplicate pose identifiers exist, the last ranked occurrence is
    retained. Use get_all_normalized_pose_scores() when duplicates matter.
    """

    validate_score_normalization_result(result)

    return MappingProxyType(
        {
            score.pose_id: score.normalized_score
            for score in result.scores
        }
    )


def normalized_pose_rank_mapping(
    result: ScoreNormalizationResult,
) -> Mapping[str, Optional[int]]:
    """
    Return pose ranks keyed by pose identifier.
    """

    validate_score_normalization_result(result)

    return MappingProxyType(
        {
            score.pose_id: score.rank
            for score in result.scores
        }
    )


# -----------------------------------------------------------------------------
# 17.18. Group-wise normalization
# -----------------------------------------------------------------------------

def group_pose_results_for_normalization(
    pose_results: Iterable[PoseScoringResult],
    *,
    key_function: Callable[[PoseScoringResult], Any],
) -> Mapping[str, Tuple[PoseScoringResult, ...]]:
    """
    Group pose results before independent normalization.
    """

    groups: Dict[str, List[PoseScoringResult]] = {}

    for pose_result in pose_results:
        validate_pose_scoring_result(pose_result)

        key = str(key_function(pose_result))

        groups.setdefault(key, []).append(pose_result)

    return MappingProxyType(
        {
            key: tuple(values)
            for key, values in sorted(groups.items())
        }
    )


def normalize_pose_scores_by_group(
    pose_results: Iterable[PoseScoringResult],
    *,
    key_function: Callable[[PoseScoringResult], Any],
    options: ScoreNormalizationOptions = (
        DEFAULT_SCORE_NORMALIZATION_OPTIONS
    ),
) -> Mapping[str, ScoreNormalizationResult]:
    """
    Normalize pose scores independently inside deterministic groups.
    """

    groups = group_pose_results_for_normalization(
        pose_results,
        key_function=key_function,
    )

    return MappingProxyType(
        {
            key: normalize_pose_scores(
                values,
                options=options,
            )
            for key, values in groups.items()
        }
    )


def normalize_pose_scores_by_ligand(
    pose_results: Iterable[PoseScoringResult],
    *,
    options: ScoreNormalizationOptions = (
        DEFAULT_SCORE_NORMALIZATION_OPTIONS
    ),
) -> Mapping[str, ScoreNormalizationResult]:
    """
    Normalize poses independently for each ligand identifier.
    """

    return normalize_pose_scores_by_group(
        pose_results,
        key_function=lambda result: (
            result.ligand_id or "unknown"
        ),
        options=options,
    )


def normalize_pose_scores_by_model(
    pose_results: Iterable[PoseScoringResult],
    *,
    options: ScoreNormalizationOptions = (
        DEFAULT_SCORE_NORMALIZATION_OPTIONS
    ),
) -> Mapping[str, ScoreNormalizationResult]:
    """
    Normalize poses independently for each model identifier.
    """

    return normalize_pose_scores_by_group(
        pose_results,
        key_function=lambda result: (
            result.model_id or "unknown"
        ),
        options=options,
    )


# -----------------------------------------------------------------------------
# 17.19. Summary
# -----------------------------------------------------------------------------

def summarize_score_normalization_result(
    result: ScoreNormalizationResult,
) -> Mapping[str, Any]:
    """
    Return an immutable compact normalization summary.
    """

    validate_score_normalization_result(result)

    return MappingProxyType(
        {
            "status": result.status,
            "method": result.method,
            "direction": result.direction,
            "pose_count": len(result.scores),
            "best_pose_ids": result.best_pose_ids,
            "worst_pose_ids": result.worst_pose_ids,
            "statistics": MappingProxyType(
                result.statistics.to_dict(
                    include_metadata=False
                )
            ),
            "ranking": tuple(
                {
                    "rank": score.rank,
                    "tied_rank": score.tied_rank,
                    "pose_id": score.pose_id,
                    "raw_score": score.raw_score,
                    "normalized_score": (
                        score.normalized_score
                    ),
                    "percentile": score.percentile,
                    "tied": score.tied,
                }
                for score in result.scores
            ),
        }
    )


# -----------------------------------------------------------------------------
# 17.20. Serialization
# -----------------------------------------------------------------------------

def normalized_pose_score_to_dict(
    score: NormalizedPoseScore,
    *,
    include_metadata: bool = True,
    include_pose_result: bool = False,
) -> Dict[str, Any]:
    """
    Convert one normalized pose score to a dictionary.
    """

    validate_normalized_pose_score(score)

    return score.to_dict(
        include_metadata=include_metadata,
        include_pose_result=include_pose_result,
    )


def score_normalization_result_to_dict(
    result: ScoreNormalizationResult,
    *,
    include_metadata: bool = True,
    include_pose_results: bool = False,
) -> Dict[str, Any]:
    """
    Convert a normalization result to a dictionary.
    """

    validate_score_normalization_result(result)

    return result.to_dict(
        include_metadata=include_metadata,
        include_pose_results=include_pose_results,
    )


def serialize_score_normalization_result(
    result: ScoreNormalizationResult,
    *,
    indent: Optional[int] = 2,
    sort_keys: bool = True,
    include_metadata: bool = True,
    include_pose_results: bool = False,
) -> str:
    """
    Serialize a normalization result as JSON.
    """

    return json.dumps(
        score_normalization_result_to_dict(
            result,
            include_metadata=include_metadata,
            include_pose_results=include_pose_results,
        ),
        indent=indent,
        sort_keys=sort_keys,
        ensure_ascii=False,
        default=str,
    )


# -----------------------------------------------------------------------------
# 17.21. Explainability
# -----------------------------------------------------------------------------

def explain_normalized_pose_score(
    score: NormalizedPoseScore,
    *,
    statistics_result: Optional[
        ScoreNormalizationStatistics
    ] = None,
) -> ScoreExplanation:
    """
    Explain the normalized score of one pose.
    """

    validate_normalized_pose_score(score)

    if score.best:
        severity = EXPLANATION_SEVERITY_SUCCESS
    elif score.worst:
        severity = EXPLANATION_SEVERITY_WARNING
    else:
        severity = EXPLANATION_SEVERITY_INFO

    metadata: Dict[str, Any] = {
        "raw_score": score.raw_score,
        "oriented_score": score.oriented_score,
        "normalized_score": score.normalized_score,
        "rank": score.rank,
        "tied_rank": score.tied_rank,
        "percentile": score.percentile,
        "method": score.method,
        "direction": score.direction,
        "tied": score.tied,
    }

    if statistics_result is not None:
        metadata["normalization_statistics"] = (
            statistics_result.to_dict(
                include_metadata=True
            )
        )

    return ScoreExplanation(
        explanation_id=(
            f"normalized_pose_score:{score.pose_id}:"
            f"{score.input_index}"
        ),
        title=f"Normalized pose score: {score.pose_id}",
        message=(
            "The total pose score was transformed relative to the "
            "comparison set using the configured normalization method."
        ),
        scope=EXPLANATION_SCOPE_POSE,
        severity=severity,
        level=EXPLANATION_LEVEL_SUMMARY,
        value=score.normalized_score,
        reference_value=0.0,
        entity_id=score.pose_id,
        tags=(
            "score_normalization",
            score.method,
            score.direction,
            "best" if score.best else (
                "worst" if score.worst else "ranked"
            ),
        ),
        metadata=metadata,
    )


def explain_score_normalization_result(
    result: ScoreNormalizationResult,
) -> ScoreExplanation:
    """
    Explain a complete cross-pose normalization result.
    """

    validate_score_normalization_result(result)

    if (
        result.status
        == SCORE_NORMALIZATION_STATUS_NORMALIZED
    ):
        severity = EXPLANATION_SEVERITY_SUCCESS

    elif result.status in {
        SCORE_NORMALIZATION_STATUS_PARTIAL,
        SCORE_NORMALIZATION_STATUS_DEGENERATE,
    }:
        severity = EXPLANATION_SEVERITY_WARNING

    elif result.status == SCORE_NORMALIZATION_STATUS_FAILED:
        severity = EXPLANATION_SEVERITY_ERROR

    else:
        severity = EXPLANATION_SEVERITY_INFO

    return ScoreExplanation(
        explanation_id="pose_score_normalization",
        title="Cross-pose score normalization",
        message=result.message,
        scope=EXPLANATION_SCOPE_COLLECTION,
        severity=severity,
        level=EXPLANATION_LEVEL_SUMMARY,
        value=(
            result.scores[0].normalized_score
            if result.scores
            else None
        ),
        reference_value=(
            result.statistics.reference_value
        ),
        tags=(
            "score_normalization",
            result.method,
            result.direction,
            result.status,
        ),
        children=tuple(
            explain_normalized_pose_score(
                score,
                statistics_result=result.statistics,
            )
            for score in result.scores
        ),
        metadata={
            "statistics": result.statistics.to_dict(
                include_metadata=True
            ),
            "best_pose_ids": result.best_pose_ids,
            "worst_pose_ids": result.worst_pose_ids,
        },
    )


# -----------------------------------------------------------------------------
# 17.22. Validation
# -----------------------------------------------------------------------------

def validate_score_normalization_options(
    options: ScoreNormalizationOptions,
) -> ScoreNormalizationOptions:
    """
    Validate and return normalization options.
    """

    if not isinstance(
        options,
        ScoreNormalizationOptions,
    ):
        raise ScoreNormalizationValidationError(
            "Expected ScoreNormalizationOptions."
        )

    if options.upper_bound <= options.lower_bound:
        raise ScoreNormalizationValidationError(
            "Normalization bounds are invalid."
        )

    if options.epsilon <= 0.0:
        raise ScoreNormalizationValidationError(
            "Normalization epsilon must be positive."
        )

    return options


def validate_score_normalization_statistics(
    statistics_result: ScoreNormalizationStatistics,
) -> ScoreNormalizationStatistics:
    """
    Validate and return normalization statistics.
    """

    if not isinstance(
        statistics_result,
        ScoreNormalizationStatistics,
    ):
        raise ScoreNormalizationValidationError(
            "Expected ScoreNormalizationStatistics."
        )

    if statistics_result.count == 0:
        optional_values = (
            statistics_result.minimum,
            statistics_result.maximum,
            statistics_result.mean,
            statistics_result.median,
        )

        if any(
            value is not None
            for value in optional_values
        ):
            raise ScoreNormalizationValidationError(
                "Empty statistics must not define central values."
            )

        return statistics_result

    required_values = (
        statistics_result.minimum,
        statistics_result.maximum,
        statistics_result.mean,
        statistics_result.median,
        statistics_result.population_variance,
        statistics_result.population_standard_deviation,
        statistics_result.value_range,
    )

    if any(value is None for value in required_values):
        raise ScoreNormalizationValidationError(
            "Non-empty statistics are incomplete."
        )

    assert statistics_result.minimum is not None
    assert statistics_result.maximum is not None
    assert statistics_result.value_range is not None

    if statistics_result.maximum < statistics_result.minimum:
        raise ScoreNormalizationValidationError(
            "Statistics maximum cannot be smaller than minimum."
        )

    expected_range = (
        statistics_result.maximum
        - statistics_result.minimum
    )

    if (
        abs(
            expected_range
            - statistics_result.value_range
        )
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise ScoreNormalizationValidationError(
            "Statistics value_range is inconsistent."
        )

    return statistics_result


def validate_normalized_pose_score(
    score: NormalizedPoseScore,
) -> NormalizedPoseScore:
    """
    Validate and return one normalized pose score.
    """

    if not isinstance(score, NormalizedPoseScore):
        raise ScoreNormalizationValidationError(
            "Expected NormalizedPoseScore."
        )

    if score.rank is not None and score.rank < 1:
        raise ScoreNormalizationValidationError(
            "Normalized pose rank must be positive."
        )

    if (
        score.percentile is not None
        and not 0.0 <= score.percentile <= 1.0
    ):
        raise ScoreNormalizationValidationError(
            "Normalized pose percentile is invalid."
        )

    if score.pose_result is not None:
        validate_pose_scoring_result(
            score.pose_result
        )

        if (
            abs(
                score.raw_score
                - score.pose_result.final_score
            )
            > SCORE_COMPARISON_TOLERANCE
        ):
            raise ScoreNormalizationValidationError(
                "Normalized raw score differs from the preserved "
                "PoseScoringResult."
            )

    return score


def validate_score_normalization_result(
    result: ScoreNormalizationResult,
) -> ScoreNormalizationResult:
    """
    Validate and return a normalization result.
    """

    if not isinstance(
        result,
        ScoreNormalizationResult,
    ):
        raise ScoreNormalizationValidationError(
            "Expected ScoreNormalizationResult."
        )

    validate_score_normalization_statistics(
        result.statistics
    )

    for score in result.scores:
        validate_normalized_pose_score(score)

    if result.statistics.count != len(result.scores):
        raise ScoreNormalizationValidationError(
            "Statistics count differs from normalized score count."
        )

    if result.scores:
        calculated_best_pose_ids = tuple(
            score.pose_id
            for score in result.scores
            if score.best
        )
        calculated_worst_pose_ids = tuple(
            score.pose_id
            for score in result.scores
            if score.worst
        )

        if (
            calculated_best_pose_ids
            != result.best_pose_ids
        ):
            raise ScoreNormalizationValidationError(
                "best_pose_ids is inconsistent with normalized scores."
            )

        if (
            calculated_worst_pose_ids
            != result.worst_pose_ids
        ):
            raise ScoreNormalizationValidationError(
                "worst_pose_ids is inconsistent with normalized scores."
            )

        ranks = tuple(
            score.rank
            for score in result.scores
            if score.rank is not None
        )

        if ranks and min(ranks) != 1:
            raise ScoreNormalizationValidationError(
                "Normalized pose rankings must begin at rank 1."
            )

    return result


# -----------------------------------------------------------------------------
# 17.23. Section consistency validation
# -----------------------------------------------------------------------------

def _validate_section_17_score_normalization() -> None:
    """
    Validate score normalization during module import.
    """

    raw_result = normalize_raw_pose_scores(
        (
            2.0,
            4.0,
            6.0,
        ),
        pose_ids=(
            "pose_1",
            "pose_2",
            "pose_3",
        ),
        options=ScoreNormalizationOptions(
            method=SCORE_NORMALIZATION_MIN_MAX,
            direction=SCORE_DIRECTION_HIGHER_IS_BETTER,
            lower_bound=0.0,
            upper_bound=1.0,
        ),
    )

    if (
        raw_result.status
        != SCORE_NORMALIZATION_STATUS_NORMALIZED
    ):
        raise RuntimeError(
            "Score normalization status validation failed."
        )

    normalized_mapping = normalized_pose_score_mapping(
        raw_result
    )

    if (
        abs(normalized_mapping["pose_1"] - 0.0)
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Min-max lower-bound validation failed."
        )

    if (
        abs(normalized_mapping["pose_2"] - 0.5)
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Min-max midpoint validation failed."
        )

    if (
        abs(normalized_mapping["pose_3"] - 1.0)
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Min-max upper-bound validation failed."
        )

    if raw_result.scores[0].pose_id != "pose_3":
        raise RuntimeError(
            "Normalized pose ranking validation failed."
        )

    if raw_result.scores[0].rank != 1:
        raise RuntimeError(
            "Best normalized rank validation failed."
        )

    lower_is_better_result = normalize_raw_pose_scores(
        (
            -6.0,
            -8.0,
            -10.0,
        ),
        pose_ids=(
            "pose_a",
            "pose_b",
            "pose_c",
        ),
        options=ScoreNormalizationOptions(
            method=SCORE_NORMALIZATION_MIN_MAX,
            direction=SCORE_DIRECTION_LOWER_IS_BETTER,
        ),
    )

    if (
        lower_is_better_result.scores[0].pose_id
        != "pose_c"
    ):
        raise RuntimeError(
            "Lower-is-better direction validation failed."
        )

    z_score_result = normalize_raw_pose_scores(
        (
            1.0,
            2.0,
            3.0,
        ),
        options=ScoreNormalizationOptions(
            method=SCORE_NORMALIZATION_Z_SCORE,
        ),
    )

    z_score_mean = statistics.fmean(
        score.normalized_score
        for score in z_score_result.scores
    )

    if abs(z_score_mean) > SCORE_COMPARISON_TOLERANCE:
        raise RuntimeError(
            "Z-score centering validation failed."
        )

    robust_result = normalize_raw_pose_scores(
        (
            1.0,
            2.0,
            3.0,
            100.0,
        ),
        options=ScoreNormalizationOptions(
            method=SCORE_NORMALIZATION_ROBUST_Z_SCORE,
        ),
    )

    if len(robust_result.scores) != 4:
        raise RuntimeError(
            "Robust normalization count validation failed."
        )

    percentile_result = normalize_raw_pose_scores(
        (
            10.0,
            10.0,
            5.0,
        ),
        pose_ids=(
            "tied_1",
            "tied_2",
            "lower",
        ),
        options=ScoreNormalizationOptions(
            method=SCORE_NORMALIZATION_PERCENTILE_RANK,
        ),
    )

    tied_scores = tuple(
        score
        for score in percentile_result.scores
        if score.pose_id in {
            "tied_1",
            "tied_2",
        }
    )

    if not all(score.tied for score in tied_scores):
        raise RuntimeError(
            "Normalized tie detection validation failed."
        )

    if not all(score.rank == 1 for score in tied_scores):
        raise RuntimeError(
            "Competition-rank validation failed."
        )

    degenerate_result = normalize_raw_pose_scores(
        (
            5.0,
            5.0,
            5.0,
        ),
        options=ScoreNormalizationOptions(
            method=SCORE_NORMALIZATION_MIN_MAX,
            degenerate_policy=SCORE_DEGENERATE_MIDPOINT,
        ),
    )

    if (
        degenerate_result.status
        != SCORE_NORMALIZATION_STATUS_DEGENERATE
    ):
        raise RuntimeError(
            "Degenerate normalization status validation failed."
        )

    if not all(
        abs(score.normalized_score - 0.5)
        <= SCORE_COMPARISON_TOLERANCE
        for score in degenerate_result.scores
    ):
        raise RuntimeError(
            "Degenerate midpoint validation failed."
        )

    reference_result = normalize_raw_pose_scores(
        (
            2.0,
            4.0,
            8.0,
        ),
        options=ScoreNormalizationOptions(
            method=SCORE_NORMALIZATION_REFERENCE_RATIO,
            reference_mode=SCORE_REFERENCE_EXPLICIT,
            reference_value=4.0,
        ),
    )

    reference_mapping = normalized_pose_score_mapping(
        reference_result
    )

    if (
        abs(reference_mapping["pose_1"] - 0.5)
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Reference-ratio validation failed."
        )

    transformed = normalize_score_with_statistics(
        4.0,
        statistics_result=raw_result.statistics,
        options=ScoreNormalizationOptions(
            method=SCORE_NORMALIZATION_MIN_MAX,
        ),
    )

    if (
        abs(transformed - 0.5)
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Fitted score transformation validation failed."
        )

    explanation = explain_score_normalization_result(
        raw_result
    )

    if len(explanation.children) != 3:
        raise RuntimeError(
            "Normalization explanation validation failed."
        )

    serialized = serialize_score_normalization_result(
        raw_result
    )

    if "pose_3" not in serialized:
        raise RuntimeError(
            "Normalization serialization validation failed."
        )

    validate_score_normalization_options(
        DEFAULT_SCORE_NORMALIZATION_OPTIONS
    )
    validate_score_normalization_statistics(
        raw_result.statistics
    )

    for score in raw_result.scores:
        validate_normalized_pose_score(score)

    validate_score_normalization_result(
        raw_result
    )


_validate_section_17_score_normalization()


