    "validate_scoring_chimerax_object_spec",
    "validate_scoring_chimerax_command",
    "validate_scoring_chimerax_command_set",
    "validate_scoring_chimerax_pseudobond_spec",
    "validate_scoring_chimerax_attribute_assignment",
